window.COURSE = {"title":"海纳教育·英语重点词点读","totalLists":120,"source":{"filename":"Unit1-Unit32 .docx","sha256":"3ea7fb29231be3a59b99a0c85a6f4eecbff915dc97252f279fdc028777198e96","format":"DOCX","paragraphCount":1536},"lists":{"1":{"vocabulary":[{"word":"best","ipa":"/best/","partsOfSpeech":"adj./adv./n.","meaning":"最好的，最好地，最好的人/物"},{"word":"vocabulary","ipa":"/vəˈkæbjələri; vəʊˈkæbjələri/","partsOfSpeech":"n.","meaning":"词汇，词汇量，词表"},{"word":"tell","ipa":"/tel/","partsOfSpeech":"v.","meaning":"告诉，吩咐，分辨"},{"word":"empty","ipa":"/ˈempti/","partsOfSpeech":"adj./v.","meaning":"空的，空虚的，空旷的；倒空"},{"word":"household","ipa":"/ˈhaʊshəʊld/","partsOfSpeech":"n./adj.","meaning":"一家人，家庭；家庭的"},{"word":"online","ipa":"/ˌɒnˈlaɪn/","partsOfSpeech":"adj./adv.","meaning":"在线的，联网的，在网上，联机地"},{"word":"until","ipa":"/ənˈtɪl/","partsOfSpeech":"prep./conj.","meaning":"直到...为止，直到...才"},{"word":"pay","ipa":"/peɪ/","partsOfSpeech":"v.","meaning":"支付，偿还；给（报酬/注意/尊敬）"},{"word":"although","ipa":"/ɔːlˈðəʊ/","partsOfSpeech":"conj.","meaning":"尽管，虽然"},{"word":"discuss","ipa":"/dɪˈskʌs/","partsOfSpeech":"v.","meaning":"讨论，商量，论述"},{"word":"remember","ipa":"/rɪˈmembə(r)/","partsOfSpeech":"v.","meaning":"想起，记住"},{"word":"mistake","ipa":"/mɪˈsteɪk/","partsOfSpeech":"n./v.","meaning":"错误，弄错，误认"},{"word":"woman","ipa":"/ˈwʊmən/","partsOfSpeech":"n.","meaning":"女人，女性"},{"word":"walk","ipa":"/wɔːk/","partsOfSpeech":"v./n.","meaning":"步行，走，散步"},{"word":"steel","ipa":"/stiːl/","partsOfSpeech":"n.","meaning":"钢，钢铁"}],"examples":[{"text":"Tom Sawyer and Huckleberry Finn are considered Twain's best works.","translation":"《汤姆·索亚历险记》和《哈克贝利·费恩历险记》被认为是吐温最优秀的作品。","source":"（2013年真题·阅读理解·Passage Three）","speechText":"Tom Sawyer and Huckleberry Finn are considered Twain's best works.","annotations":[],"targetForms":[],"audio":"audio/course-examples/c963a370377de50d039892c9.mp3"},{"text":"Grammar, vocabulary and pronunciation are not the only important elements in learning a foreign language.","translation":"语法、词汇和发音并不是学习外语的唯一重要因素。","source":"（2018年·阅读理解·Passage Three）","speechText":"Grammar, vocabulary and pronunciation are not the only important elements in learning a foreign language.","annotations":[],"targetForms":[],"audio":"audio/course-examples/9e69456cac79d08c2563a518.mp3"},{"text":"Many a young person tells（tell的第三人称单数形式） me he wants to be a writer.","translation":"许多年轻人告诉我，他们想当作家。","source":"（2015年真题·阅读理解·Passage One）","speechText":"Many a young person tells me he wants to be a writer.","annotations":[{"text":"（tell的第三人称单数形式）","start":25,"end":40,"anchor":"tells"}],"targetForms":["tells"],"audio":"audio/course-examples/9fcd58ab1a97d743b249d82c.mp3"},{"text":"When you picture a desert, you probably imagine a vast, empty landscape far from any water.","translation":"想到沙漠时，你可能会想象出一片辽阔、空旷、远离任何水源的地貌。","source":"（2026年真题·阅读理解·Passage Three）","speechText":"When you picture a desert, you probably imagine a vast, empty landscape far from any water.","annotations":[],"targetForms":[],"audio":"audio/course-examples/9ca7d39eff02cd318a66ed21.mp3"},{"text":"Released from these household chores, many wives have found jobs outside the home.","translation":"从这些家务中解脱出来后，许多妻子找到了家庭之外的工作。","source":"（2013年真题·阅读理解·Passage Two）","speechText":"Released from these household chores, many wives have found jobs outside the home.","annotations":[],"targetForms":[],"audio":"audio/course-examples/70b5ffdbfe7801abd9cb78c8.mp3"},{"text":"Experts in media studies and online psychology have been examining the fake news phenomenon.","translation":"媒体研究和网络心理学领域的专家一直在研究假新闻现象。","source":"（2020年真题·选句填空）","speechText":"Experts in media studies and online psychology have been examining the fake news phenomenon.","annotations":[],"targetForms":[],"audio":"audio/course-examples/2d0237af087516c6d19a6e6d.mp3"},{"text":"I didn't leave until he told me to.","translation":"直到他叫我离开，我才离开。","source":"（2016年真题·词汇语法·第39题）","speechText":"I didn't leave until he told me to.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e00be1cbbf3b5d8e3fb29cbb.mp3"},{"text":"Students must also pay for room and board.","translation":"学生还必须支付食宿费。","source":"（2021年真题·完形填空）","speechText":"Students must also pay for room and board.","annotations":[],"targetForms":[],"audio":"audio/course-examples/dfa8db51448ac8dece8df111.mp3"},{"text":"Although she was sometimes described as pretty, she never married.","translation":"虽然有时人们说她长得漂亮，但她终身未婚。","source":"（2015年真题·阅读理解·Passage Three）","speechText":"Although she was sometimes described as pretty, she never married.","annotations":[],"targetForms":[],"audio":"audio/course-examples/4ba0194d2a106b092b023706.mp3"},{"text":"Some activities, like discussing（discuss的-ing形式） and reading, are basic to studying.","translation":"一些活动，如讨论和阅读，是学习的基础。","source":"（2017年真题·阅读理解·Passage Two）","speechText":"Some activities, like discussing and reading, are basic to studying.","annotations":[{"text":"（discuss的-ing形式）","start":32,"end":48,"anchor":"discussing"}],"targetForms":["discussing"],"audio":"audio/course-examples/a4b22e07250c3cc18fd62928.mp3"},{"text":"An actor named Steve Roach thinks that people collect things to remember their childhood.","translation":"一位名叫Steve Roach的演员认为，人们收藏物品是为了回忆童年。","source":"（2022年真题·阅读理解·Passage One）","speechText":"An actor named Steve Roach thinks that people collect things to remember their childhood.","annotations":[],"targetForms":[],"audio":"audio/course-examples/4e20bff60437db8ad03ca7d6.mp3"},{"text":"I'm sorry I have made so many mistakes（mistake的复数形式）.","translation":"对不起，我犯了这么多错误。","source":"（2017年真题·词汇语法·第21题）","speechText":"I'm sorry I have made so many mistakes.","annotations":[{"text":"（mistake的复数形式）","start":38,"end":52,"anchor":"mistakes"}],"targetForms":["mistakes"],"audio":"audio/course-examples/b327f0dbf227640dac50d6c5.mp3"},{"text":"Women（woman的复数形式） are achieving economic independence.","translation":"女性正在实现经济独立。","source":"（2013年真题·阅读理解·Passage Two）","speechText":"Women are achieving economic independence.","annotations":[{"text":"（woman的复数形式）","start":5,"end":17,"anchor":"Women"}],"targetForms":["Women"],"audio":"audio/course-examples/14deaec1cb10b14e72f2ebde.mp3"},{"text":"Imagine walking（walk的-ing形式） through someone's apartment.","translation":"想象一下在某人的公寓里走动的情景。","source":"（2021年真题·阅读理解·Passage Two）","speechText":"Imagine walking through someone's apartment.","annotations":[{"text":"（walk的-ing形式）","start":15,"end":28,"anchor":"walking"}],"targetForms":["walking"],"audio":"audio/course-examples/545c06a89be2469d9bf9ad5f.mp3"},{"text":"The most recent designs give buildings brains as well as concrete and steel supports.","translation":"最新的设计不仅为建筑提供混凝土和钢材支撑，还赋予建筑“大脑”。","source":"（2014年真题·阅读理解·Passage Three）","speechText":"The most recent designs give buildings brains as well as concrete and steel supports.","annotations":[],"targetForms":[],"audio":"audio/course-examples/0a228ebfb80b6e70fb49589d.mp3"}]},"2":{"vocabulary":[{"word":"strike","ipa":"/straɪk/","partsOfSpeech":"v./n.","meaning":"打，击，撞，达成；罢工"},{"word":"fire","ipa":"/ˈfaɪə(r)/","partsOfSpeech":"n./v.","meaning":"火，火灾，开火，解雇"},{"word":"maintain","ipa":"/meɪnˈteɪn/","partsOfSpeech":"v.","meaning":"保持，主张"},{"word":"participate","ipa":"/pɑːˈtɪsɪpeɪt/","partsOfSpeech":"v.","meaning":"参与，参加"},{"word":"hotel","ipa":"/həʊˈtel/","partsOfSpeech":"n.","meaning":"酒店，宾馆"},{"word":"host","ipa":"/həʊst/","partsOfSpeech":"n./v.","meaning":"男主人，东道主；主持；主办"},{"word":"victim","ipa":"/ˈvɪktɪm/","partsOfSpeech":"n.","meaning":"受害者，牺牲品，遇难者"},{"word":"also","ipa":"/ˈɔːlsəʊ/","partsOfSpeech":"adv.","meaning":"也，而且，此外"},{"word":"violence","ipa":"/ˈvaɪələns/","partsOfSpeech":"n.","meaning":"暴力，暴行，暴虐"},{"word":"analyse","ipa":"/ˈænəlaɪz/","partsOfSpeech":"v.","meaning":"分析，分解"},{"word":"ancestor","ipa":"/ˈænsestə(r)/","partsOfSpeech":"n.","meaning":"祖先，祖宗，先辈"},{"word":"playground","ipa":"/ˈpleɪɡraʊnd/","partsOfSpeech":"n.","meaning":"操场，游乐场"},{"word":"tiny","ipa":"/ˈtaɪni/","partsOfSpeech":"adj.","meaning":"极小的，微小的，微不足道的"},{"word":"tie","ipa":"/taɪ/","partsOfSpeech":"v./n.","meaning":"系，打结，打成平局；领带"},{"word":"sorrow","ipa":"/ˈsɒrəʊ/","partsOfSpeech":"n.","meaning":"悲伤，悲痛，忧伤"}],"examples":[{"text":"Kondo stresses that it is not about throwing things away, but about finding the things you want to remain with you and striking（strike的-ing形式） a balance between personal joy and possessions.","translation":"近藤强调，重点不是扔掉东西，而是找出你希望留在身边的物品，并在个人快乐与拥有的物品之间达成平衡。","source":"（2021年真题·阅读理解·Passage Two）","speechText":"Kondo stresses that it is not about throwing things away, but about finding the things you want to remain with you and striking a balance between personal joy and possessions.","annotations":[{"text":"（strike的-ing形式）","start":127,"end":142,"anchor":"striking"}],"targetForms":["striking"],"audio":"audio/20261016-list1/examples/14.mp3"},{"text":"Since then, Alison Lundberg, a communications executive, has repeatedly told her 4-year-old daughter Ava that she should call 911 if someone is sick or if there is a fire or another kind of emergency at home.","translation":"此后，身为传播领域高管的艾莉森·伦德伯格（Alison Lundberg）反复告诉她4岁的女儿艾娃（Ava）：如果家里有人生病、发生火灾或出现其他紧急情况，就应该拨打911。","source":"（2026年真题·阅读理解·Passage Two）","speechText":"Since then, Alison Lundberg, a communications executive, has repeatedly told her 4-year-old daughter Ava that she should call 911 if someone is sick or if there is a fire or another kind of emergency at home.","annotations":[],"targetForms":[],"audio":"audio/course-examples/d71b2a46f40762139593a8e0.mp3"},{"text":"Nishinari’s previous research showed that ants can maintain their flow even at high densities.","translation":"Nishinari先前的研究表明，即使密度很高，蚂蚁也能保持顺畅通行。","source":"（2025年真题·阅读理解·Passage Three）","speechText":"Nishinari’s previous research showed that ants can maintain their flow even at high densities.","annotations":[],"targetForms":[],"audio":"audio/20261016-list1/examples/12.mp3"},{"text":"Because of such benefits, many want to participate in the activity, though some do not know where to begin.","translation":"由于有这些好处，许多人想参与这项活动，尽管有些人不知道该从哪里开始。","source":"（2024年真题·选句填空）","speechText":"Because of such benefits, many want to participate in the activity, though some do not know where to begin.","annotations":[],"targetForms":[],"audio":"audio/course-examples/97c46a3a8d31451389454cf3.mp3"},{"text":"There are many inexpensive, older hotels（hotel的复数形式） near bus or train stations.","translation":"汽车站或火车站附近有许多价格低廉的老旅馆。","source":"（2015年真题·阅读理解·Passage Two）","speechText":"There are many inexpensive, older hotels near bus or train stations.","annotations":[{"text":"（hotel的复数形式）","start":40,"end":52,"anchor":"hotels"}],"targetForms":["hotels"],"audio":"audio/course-examples/729e5165204251d5563667be.mp3"},{"text":"He has played in and hosted（host的过去分词形式） competitions all around the globe.","translation":"他曾在世界各地参加并主持比赛。","source":"（2021年真题·阅读理解·Passage One）","speechText":"He has played in and hosted competitions all around the globe.","annotations":[{"text":"（host的过去分词形式）","start":27,"end":40,"anchor":"hosted"}],"targetForms":["hosted"],"audio":"audio/course-examples/48f7931e8d1781990d643d8a.mp3"},{"text":"By comparison, an earthquake of similar intensity that shook America in 1988 claimed 25,000 victims（victim的复数形式）.","translation":"相比之下，1988年美国发生的一场震级相当的地震，造成了25,000人遇难。","source":"（2014年真题·阅读理解·Passage Three）","speechText":"By comparison, an earthquake of similar intensity that shook America in 1988 claimed 25,000 victims.","annotations":[{"text":"（victim的复数形式）","start":99,"end":112,"anchor":"victims"}],"targetForms":["victims"],"audio":"audio/20261016-list1/examples/01.mp3"},{"text":"Yet he also feels uneasy and troubled.","translation":"然而，他也感到不安和烦恼。","source":"（2018年真题·阅读理解·Passage one）","speechText":"Yet he also feels uneasy and troubled.","annotations":[],"targetForms":[],"audio":"audio/course-examples/f358be063a6405167e9aab83.mp3"},{"text":"Thus for rats, population and violence are directly related.","translation":"因此，对老鼠来说，种群数量与暴力行为有直接关系。","source":"（2014年真题·阅读理解·Passage One）","speechText":"Thus for rats, population and violence are directly related.","annotations":[],"targetForms":[],"audio":"audio/20261016-list1/examples/02.mp3"},{"text":"Some stay very close to the words on the page; others take off imaginatively from the words, interpreting, criticizing, analysing（analyse的-ing形式） and examining.","translation":"有些人阅读时紧扣原文；另一些人则会从文字出发，展开想象，对内容进行解读、评论、分析和审视。","source":"（2016年真题·阅读理解·Passage Two）","speechText":"Some stay very close to the words on the page; others take off imaginatively from the words, interpreting, criticizing, analysing and examining.","annotations":[{"text":"（analyse的-ing形式）","start":129,"end":145,"anchor":"analysing"}],"targetForms":["analysing"],"audio":"audio/course-examples/ca4579c007bf19bd4ddc3733.mp3"},{"text":"Hers was an old family; her ancestors（ancestor的复数形式） had come to the United States 200 years before.","translation":"她出身于一个古老的家族；她的祖先早在两百年前就来到了美国。","source":"（2015年真题·阅读理解·Passage Three）","speechText":"Hers was an old family; her ancestors had come to the United States 200 years before.","annotations":[{"text":"（ancestor的复数形式）","start":37,"end":52,"anchor":"ancestors"}],"targetForms":["ancestors"],"audio":"audio/20261016-list1/examples/07.mp3"},{"text":"We can find many sports facilities on the playground of this primary school.","translation":"我们可以在这所小学的操场上看到许多体育设施。","source":"（2018年真题·词汇语法·第29题）","speechText":"We can find many sports facilities on the playground of this primary school.","annotations":[],"targetForms":[],"audio":"audio/20261016-list1/examples/06.mp3"},{"text":"Her technique for making space is to go through things by category, starting with clothing, then books, papers, tiny objects, and finally, memorable items.","translation":"她腾出空间的方法是按类别整理物品：先整理衣物，再整理书籍、文件、小物件，最后整理有纪念意义的物品。","source":"（2021年真题·阅读理解·Passage Two）","speechText":"Her technique for making space is to go through things by category, starting with clothing, then books, papers, tiny objects, and finally, memorable items.","annotations":[],"targetForms":[],"audio":"audio/20261016-list1/examples/05.mp3"},{"text":"You win, lose, or tie (不分胜负).","translation":"你会获胜、落败或打成平手。","source":"（2021年真题·阅读理解·Passage One）","speechText":"You win, lose, or tie .","annotations":[{"text":"(不分胜负)","start":22,"end":28,"anchor":"tie"}],"targetForms":[],"audio":"audio/20261016-list1/examples/15.mp3"},{"text":"The saying \"Shared sorrow is half a sorrow; shared joy is double joy\" points out the importance of emotional help.","translation":"“分担的忧愁减半，分享的快乐加倍”这句话指出了情感支持的重要性。","source":"（2026年真题·选句填空）","speechText":"The saying \"Shared sorrow is half a sorrow; shared joy is double joy\" points out the importance of emotional help.","annotations":[],"targetForms":[],"audio":"audio/20261016-list1/examples/03.mp3"}]},"3":{"vocabulary":[{"word":"somewhat","ipa":"/ˈsʌmwɒt/","partsOfSpeech":"adv.","meaning":"稍微，有点儿，在某种程度上"},{"word":"annoy","ipa":"/əˈnɔɪ/","partsOfSpeech":"v.","meaning":"惹恼，打搅，使烦恼，使生气"},{"word":"bend","ipa":"/bend/","partsOfSpeech":"v./n.","meaning":"弯曲，屈服，转弯处，弯道"},{"word":"crucial","ipa":"/ˈkruːʃ(ə)l/","partsOfSpeech":"adj.","meaning":"至关重要的，决定性的，关键的"},{"word":"under","ipa":"/ˈʌndə(r)/","partsOfSpeech":"prep./adv.","meaning":"在……下面；少于；在……情况下"},{"word":"equator","ipa":"/ɪˈkweɪtə(r)/","partsOfSpeech":"n.","meaning":"赤道"},{"word":"museum","ipa":"/mjuˈziːəm/","partsOfSpeech":"n.","meaning":"博物馆，博物院，展览馆"},{"word":"music","ipa":"/ˈmjuːzɪk/","partsOfSpeech":"n.","meaning":"音乐，乐曲，乐谱"},{"word":"shelter","ipa":"/ˈʃeltə(r)/","partsOfSpeech":"n./v.","meaning":"避难所；庇护；保护；躲避"},{"word":"impossible","ipa":"/ɪmˈpɒsəb(ə)l/","partsOfSpeech":"adj.","meaning":"不可能的，办不到的"},{"word":"bet","ipa":"/bet/","partsOfSpeech":"v./n.","meaning":"打赌；赌注"},{"word":"grandparent","ipa":"/ˈɡrænpeərənt/","partsOfSpeech":"n.","meaning":"祖父/母，外祖父/母，祖父母辈"},{"word":"grandmother","ipa":"/ˈɡrænmʌðə(r)/","partsOfSpeech":"n.","meaning":"奶奶，外婆"},{"word":"learn","ipa":"/lɜːn/","partsOfSpeech":"v.","meaning":"学习，学会"},{"word":"some","ipa":"/səm; sʌm/","partsOfSpeech":"adj./pron.","meaning":"一些，某些，部分"}],"examples":[{"text":"In 2002 an amazing 89 percent of workers said they were very satisfied or somewhat satisfied with their jobs.","translation":"2002年，竟有89%的劳动者表示，他们对自己的工作非常满意或比较满意。","source":"（2016年真题·阅读理解·Passage One）","speechText":"In 2002 an amazing 89 percent of workers said they were very satisfied or somewhat satisfied with their jobs.","annotations":[],"targetForms":[],"audio":"audio/course-examples/30cee7c72846acffab864f24.mp3"},{"text":"I sometimes do feel abandoned and annoyed（annoy的过去分词形式）.","translation":"我有时确实感到自己被冷落了，心里很恼火。","source":"（2018年真题·阅读理解·Passage one）","speechText":"I sometimes do feel abandoned and annoyed.","annotations":[{"text":"（annoy的过去分词形式）","start":41,"end":55,"anchor":"annoyed"}],"targetForms":["annoyed"],"audio":"audio/course-examples/045fffa9207860933bb7ea0c.mp3"},{"text":"In the past, making structures quake-resistant meant firm yet flexible materials, such as steel and wood, that bent（bend的过去式） without breaking.","translation":"过去，让建筑结构具备抗震能力，意味着采用钢材和木材等坚固而又有韧性的材料，使其弯曲而不断裂。","source":"（2014年真题·阅读理解·Passage Three）","speechText":"In the past, making structures quake-resistant meant firm yet flexible materials, such as steel and wood, that bent without breaking.","annotations":[{"text":"（bend的过去式）","start":115,"end":125,"anchor":"bent"}],"targetForms":["bent"],"audio":"audio/20261016-list1/examples/10.mp3"},{"text":"Focusing on our health is particularly crucial.","translation":"关注我们的健康尤为重要。","source":"（2025年真题·选句填空）","speechText":"Focusing on our health is particularly crucial.","annotations":[],"targetForms":[],"audio":"audio/20261016-list1/examples/13.mp3"},{"text":"Think about leaders who you have worked under in the past.","translation":"想一想你过去曾在其领导下工作过的那些领导者。","source":"（2023年真题·选句填空）","speechText":"Think about leaders who you have worked under in the past.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e202121adbafe32ccf327082.mp3"},{"text":"Strong winds blow all the time towards the equator and then to the west.","translation":"强风持续吹向赤道，随后转向西方。","source":"（2026年真题·阅读理解·Passage Three）","speechText":"Strong winds blow all the time towards the equator and then to the west.","annotations":[],"targetForms":[],"audio":"audio/course-examples/6b1929fa79eb68d747b677c9.mp3"},{"text":"Researchers have found that people who go to concerts, shows and museums（museum的复数形式） can live longer than those who do not.","translation":"研究人员发现，去听音乐会、看演出和参观博物馆的人，可能比不参加这些活动的人活得更久。","source":"（2020年真题·完形填空）","speechText":"Researchers have found that people who go to concerts, shows and museums can live longer than those who do not.","annotations":[{"text":"（museum的复数形式）","start":72,"end":85,"anchor":"museums"}],"targetForms":["museums"],"audio":"audio/course-examples/c110931840a06eaf864bb6d5.mp3"},{"text":"You can also take a walk or listen to music.","translation":"你也可以散散步或听听音乐。","source":"（2021年真题·选句填空）","speechText":"You can also take a walk or listen to music.","annotations":[],"targetForms":[],"audio":"audio/course-examples/2774664b2eac9af2393e6655.mp3"},{"text":"Whether you volunteer at your local youth group or take dogs from shelters（shelter的复数形式） for a walk, the simple fact that you are giving up your time to help someone else is incredible.","translation":"无论你是在当地的青少年团体做志愿者，还是带收容所里的狗出去散步，仅仅是你愿意付出自己的时间去帮助别人，就已经非常了不起。","source":"（2018年配套材料·选句填空）","speechText":"Whether you volunteer at your local youth group or take dogs from shelters for a walk, the simple fact that you are giving up your time to help someone else is incredible.","annotations":[{"text":"（shelter的复数形式）","start":74,"end":88,"anchor":"shelters"}],"targetForms":["shelters"],"audio":"audio/20261016-list1/examples/04.mp3"},{"text":"There were so many days in the month that it was impossible for each day to have its own name.","translation":"一个月里的天数太多，因此不可能让每一天都有自己的名称。","source":"（2019年真题·阅读理解·Passage Three·第60题选项）","speechText":"There were so many days in the month that it was impossible for each day to have its own name.","annotations":[],"targetForms":[],"audio":"audio/course-examples/1508912cdf2b203404ccf775.mp3"},{"text":"Therefore, putting it near a sunny window to obtain enough indirect light would be your best bet.","translation":"因此，把它放在阳光充足的窗户附近，以获得足够的散射光，会是最好的选择。","source":"（2014年配套材料·选句填空）","speechText":"Therefore, putting it near a sunny window to obtain enough indirect light would be your best bet.","annotations":[],"targetForms":[],"audio":"audio/course-examples/976be1e85e4e01486671fb81.mp3"},{"text":"Today's grandparents（grandparent的复数形式） are joining their grandchildren on social media.","translation":"如今，祖父母也开始和孙辈一起使用社交媒体。","source":"（2021年真题·阅读理解·Passage Three）","speechText":"Today's grandparents are joining their grandchildren on social media.","annotations":[{"text":"（grandparent的复数形式）","start":20,"end":38,"anchor":"grandparents"}],"targetForms":["grandparents"],"audio":"audio/course-examples/1a24d245a2625369f82693fd.mp3"},{"text":"Unlike her grandmother's（grandmother的所有格形式） generation, Chloe's age group is spending so much time on their phones at home that they are missing out on spending time with their friends in real life.","translation":"与她祖母那一代人不同，Chloe这一年龄段的人在家花太多时间玩手机，以至于错过了在现实生活中与朋友相处的机会。","source":"（2021年真题·阅读理解·Passage Three）","speechText":"Unlike her grandmother's generation, Chloe's age group is spending so much time on their phones at home that they are missing out on spending time with their friends in real life.","annotations":[{"text":"（grandmother的所有格形式）","start":24,"end":43,"anchor":"grandmother's"}],"targetForms":["grandmother's"],"audio":"audio/course-examples/34e0938b16ef509a6dc8e47b.mp3"},{"text":"Kids are also learning（learn的现在分词形式） how to have proper phone conversations.","translation":"孩子们也在学习如何得体地进行电话交谈。","source":"（2026年真题·阅读理解·Passage Two）","speechText":"Kids are also learning how to have proper phone conversations.","annotations":[{"text":"（learn的现在分词形式）","start":22,"end":36,"anchor":"learning"}],"targetForms":["learning"],"audio":"audio/course-examples/fc1de60e86f15e6efcff7fea.mp3"},{"text":"There are some good tips for beginners.","translation":"这里有一些适合初学者的实用建议。","source":"（2024年真题·选句填空）","speechText":"There are some good tips for beginners.","annotations":[],"targetForms":[],"audio":"audio/course-examples/d757eae913ee821904b0196d.mp3"}]},"4":{"vocabulary":[{"word":"show","ipa":"/ʃəʊ/","partsOfSpeech":"v./n.","meaning":"展示；演出；展览；表明；显示"},{"word":"information","ipa":"/ˌɪnfəˈmeɪʃ(ə)n/","partsOfSpeech":"n.","meaning":"信息"},{"word":"paper","ipa":"/ˈpeɪpə(r)/","partsOfSpeech":"n./adj.","meaning":"纸，论文，报纸，纸质的"},{"word":"control","ipa":"/kənˈtrəʊl/","partsOfSpeech":"v./n.","meaning":"控制，管理，限制，操纵"},{"word":"increase","ipa":"/ɪnˈkriːs;ˈɪnkriːs/","partsOfSpeech":"v./n.","meaning":"增加，增长，提高，增多"},{"word":"realize","ipa":"/ˈriːəlaɪz/","partsOfSpeech":"v.","meaning":"意识到；认识到；了解；实现"},{"word":"return","ipa":"/rɪˈtɜːn/","partsOfSpeech":"v./n.","meaning":"返回；回报"},{"word":"nothing","ipa":"/ˈnʌθɪŋ/","partsOfSpeech":"pron./n.","meaning":"没有什么，毫无，无关紧要的事"},{"word":"morning","ipa":"/ˈmɔːnɪŋ/","partsOfSpeech":"n.","meaning":"早晨，上午，开端"},{"word":"routine","ipa":"/ruːˈtiːn/","partsOfSpeech":"n./adj.","meaning":"日常工作，惯例；例行的，常规的"},{"word":"unless","ipa":"/ənˈles/","partsOfSpeech":"conj.","meaning":"除非，如果不"},{"word":"welfare","ipa":"/ˈwelfeə(r)/","partsOfSpeech":"n.","meaning":"福利，幸福，安康，社会保障"},{"word":"worry","ipa":"/ˈwʌri/","partsOfSpeech":"v./n.","meaning":"担心，发愁；烦恼，令人担忧的事"},{"word":"party","ipa":"/ˈpɑːti/","partsOfSpeech":"n./v.","meaning":"派对，聚会，政党，狂欢"},{"word":"nowadays","ipa":"/ˈnaʊədeɪz/","partsOfSpeech":"adv.","meaning":"现今，当今，现在"}],"examples":[{"text":"The study shows（show的第三人称单数形式） that most people do not react as strongly as expected.","translation":"研究表明，大多数人的反应并没有预期中那么强烈。","source":"（2026年真题·阅读理解·Passage One）","speechText":"The study shows that most people do not react as strongly as expected.","annotations":[{"text":"（show的第三人称单数形式）","start":15,"end":30,"anchor":"shows"}],"targetForms":["shows"],"audio":"audio/course-examples/92d3440497077cd5cc2da11d.mp3"},{"text":"A travel agent can give you information on special economy fares for trains, buses and planes.","translation":"旅行代理可以向你提供火车、汽车和飞机的特价经济票价信息。","source":"（2015年真题·阅读理解·Passage Two）","speechText":"A travel agent can give you information on special economy fares for trains, buses and planes.","annotations":[],"targetForms":[],"audio":"audio/course-examples/59384132a2ae4c0fe4b60141.mp3"},{"text":"One paper looking into the ideal amount of sleep found that “Sleep duration recommendations issued by public health authorities help to inform the population of interventions, policies, and healthy sleep behaviors.”","translation":"一篇探讨理想睡眠时长的论文指出：“公共卫生部门发布的睡眠时长建议，有助于让公众了解相关的干预措施、政策以及健康的睡眠行为。”","source":"（2024年真题·阅读理解·Passage Three）","speechText":"One paper looking into the ideal amount of sleep found that “Sleep duration recommendations issued by public health authorities help to inform the population of interventions, policies, and healthy sleep behaviors.”","annotations":[],"targetForms":[],"audio":"audio/course-examples/0284cfa20eecf1fdf4983448.mp3"},{"text":"Some of us get angry easily, while others do not let anger control them.","translation":"我们当中有些人很容易生气，而另一些人不会让愤怒控制自己。","source":"（2021年真题·选句填空）","speechText":"Some of us get angry easily, while others do not let anger control them.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e79864fdeb8a021242e8b5d1.mp3"},{"text":"As the density of whales increased（increase的过去式）, their singing behaviors changed.","translation":"随着鲸群密度增加，它们的歌唱行为发生了变化。","source":"（2023年真题·阅读理解·Passage Three）","speechText":"As the density of whales increased, their singing behaviors changed.","annotations":[{"text":"（increase的过去式）","start":34,"end":48,"anchor":"increased"}],"targetForms":["increased"],"audio":"audio/course-examples/ca09aa7e18600b309cfa7b5f.mp3"},{"text":"I felt very small when I realized（realize的过去式） the hugeness of the universe.","translation":"当我意识到宇宙如此浩瀚时，便感到自己十分渺小。","source":"（2025年真题·翻译）","speechText":"I felt very small when I realized the hugeness of the universe.","annotations":[{"text":"（realize的过去式）","start":33,"end":46,"anchor":"realized"}],"targetForms":["realized"],"audio":"audio/course-examples/a94606850598cfcac213721a.mp3"},{"text":"This worry often leads people to think that the other person expects something big in return.","translation":"这种担忧常常让人以为，对方期待得到丰厚的回报。","source":"（2026年真题·阅读理解·Passage One）","speechText":"This worry often leads people to think that the other person expects something big in return.","annotations":[],"targetForms":[],"audio":"audio/course-examples/a7f3b1a4ed66e095a3f0847c.mp3"},{"text":"Don't stand there doing nothing.","translation":"别站在那里无所事事。","source":"（2019年真题·词汇语法·第22题）","speechText":"Don't stand there doing nothing.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e5d6df1f5aea20ddb966d1c8.mp3"},{"text":"The road was wet this morning.","translation":"今天早上路面是湿的。","source":"（2017年真题·词汇语法·第48题）","speechText":"The road was wet this morning.","annotations":[],"targetForms":[],"audio":"audio/course-examples/bcfb807bd6b4891249cd33c5.mp3"},{"text":"Records suggest that backward walking has been part of traditional exercise routines（routine的复数形式） for centuries.","translation":"记录表明，倒着走几百年来一直是传统锻炼方式的一部分。","source":"（2025年真题·阅读理解·Passage Two）","speechText":"Records suggest that backward walking has been part of traditional exercise routines for centuries.","annotations":[{"text":"（routine的复数形式）","start":84,"end":98,"anchor":"routines"}],"targetForms":["routines"],"audio":"audio/course-examples/9c2432a640a63e39bc418b87.mp3"},{"text":"You will never gain success unless you are fully devoted to your work.","translation":"除非你全身心投入工作，否则永远不会取得成功。","source":"（2019年真题·词汇语法·第43题）","speechText":"You will never gain success unless you are fully devoted to your work.","annotations":[],"targetForms":[],"audio":"audio/course-examples/b6a6c114b5dea91fd2c56343.mp3"},{"text":"These payments to the poor are called welfare.","translation":"这些发给穷人的款项被称为福利金。","source":"（2016年真题·阅读理解·Passage Three）","speechText":"These payments to the poor are called welfare.","annotations":[],"targetForms":[],"audio":"audio/course-examples/3b871ed0a908852cdaba2886.mp3"},{"text":"In many cases, forgiveness comes naturally, making the worry unnecessary.","translation":"在许多情况下，原谅是自然而然发生的，因此这样的担忧并无必要。","source":"（2026年真题·阅读理解·Passage One）","speechText":"In many cases, forgiveness comes naturally, making the worry unnecessary.","annotations":[],"targetForms":[],"audio":"audio/course-examples/d78601fbf6db95b27be33fac.mp3"},{"text":"Under no circumstances shall we cancel the party.","translation":"无论在什么情况下，我们都绝不会取消聚会。","source":"（2017年真题·词汇语法·第31题）","speechText":"Under no circumstances shall we cancel the party.","annotations":[],"targetForms":[],"audio":"audio/course-examples/a723b30183b517b1fdb6f24a.mp3"},{"text":"Nowadays, we still have a collecting instinct.","translation":"如今，我们仍然保留着收藏的本能。","source":"（2022年真题·阅读理解·Passage One）","speechText":"Nowadays, we still have a collecting instinct.","annotations":[],"targetForms":[],"audio":"audio/course-examples/6ef4757debd6135d842f403e.mp3"}]},"5":{"vocabulary":[{"word":"ignore","ipa":"/ɪɡˈnɔː(r)/","partsOfSpeech":"v.","meaning":"忽视，不顾，不理睬，无视"},{"word":"himself","ipa":"/hɪmˈself/","partsOfSpeech":"pron.","meaning":"他自己，他亲自"},{"word":"vary","ipa":"/ˈveəri/","partsOfSpeech":"v.","meaning":"变化，改变，不同，使多样化"},{"word":"visit","ipa":"/ˈvɪzɪt/","partsOfSpeech":"v./n.","meaning":"访问，参观，拜访，视察"},{"word":"allow","ipa":"/əˈlaʊ/","partsOfSpeech":"v.","meaning":"允许，准许，给予，让，使"},{"word":"anymore","ipa":"/ˌeniˈmɔː(r)/","partsOfSpeech":"adv.","meaning":"再也不，不再"},{"word":"plus","ipa":"/plʌs/","partsOfSpeech":"prep./adj./n.","meaning":"加上，正的，优势，超过"},{"word":"tide","ipa":"/taɪd/","partsOfSpeech":"n.","meaning":"潮汐，潮流，趋势"},{"word":"soul","ipa":"/səʊl/","partsOfSpeech":"n.","meaning":"灵魂，心灵，精神，精髓"},{"word":"solid","ipa":"/ˈsɒlɪd/","partsOfSpeech":"adj./n.","meaning":"固体的，坚固的，可靠的，固体"},{"word":"amazing","ipa":"/əˈmeɪzɪŋ/","partsOfSpeech":"adj.","meaning":"令人惊异的，了不起的，惊人的"},{"word":"educate","ipa":"/ˈedʒukeɪt/","partsOfSpeech":"v.","meaning":"教育，培养，指导"},{"word":"crime","ipa":"/kraɪm/","partsOfSpeech":"n.","meaning":"罪行，犯罪，罪恶"},{"word":"theory","ipa":"/ˈθɪəri/","partsOfSpeech":"n.","meaning":"理论，学说，推测，假设"},{"word":"superior","ipa":"/suːˈpɪəriə(r)/","partsOfSpeech":"adj./n.","meaning":"优秀的，上级的，优越的，上司"}],"examples":[{"text":"Winners were likely to ignore their opponents completely.","translation":"获胜者很可能会完全忽视对手","source":"（2021年·阅读理解·Passage One）","speechText":"Winners were likely to ignore their opponents completely.","annotations":[],"targetForms":[],"audio":"audio/course-examples/c493e7d60bd05d3e93d1e468.mp3"},{"text":"Since his wife died, he has thrown himself into the research work.","translation":"自从妻子去世后，他就全身心投入了研究工作。","source":"（2014年真题·词汇语法·第25题）","speechText":"Since his wife died, he has thrown himself into the research work.","annotations":[],"targetForms":[],"audio":"audio/course-examples/1c243fc613d333ddd7cdf628.mp3"},{"text":"As in other institutions of higher learning, ballet students receive monthly government stipends in their last four years, varying（vary的-ing形式） from 160 to 200 rubles ($16 to $20).","translation":"与其他高等院校一样，芭蕾舞学生在最后四年里每月会获得政府津贴，金额从160卢布到200卢布不等，相当于16至20美元。","source":"（2013年真题·阅读理解·Passage One）","speechText":"As in other institutions of higher learning, ballet students receive monthly government stipends in their last four years, varying from 160 to 200 rubles ($16 to $20).","annotations":[{"text":"（vary的-ing形式）","start":130,"end":143,"anchor":"varying"}],"targetForms":["varying"],"audio":"audio/course-examples/f3d022383563705238d7ae21.mp3"},{"text":"I will pay a visit to my old friend the minute she comes back from abroad.","translation":"她一从国外回来，我就去看望这位老朋友。","source":"（2018年真题·词汇语法·第34题）","speechText":"I will pay a visit to my old friend the minute she comes back from abroad.","annotations":[],"targetForms":[],"audio":"audio/course-examples/c375e2bd08e73ad1e2980844.mp3"},{"text":"Allow things to settle with time.","translation":"让事情随着时间慢慢平息下来。","source":"（2021年真题·选句填空）","speechText":"Allow things to settle with time.","annotations":[],"targetForms":[],"audio":"audio/course-examples/a93c41e3ce03f9a10db0e363.mp3"},{"text":"My most negative opinion is that we don't have any privacy anymore because everything about us is now recorded someplace.","translation":"我最不满的一点是，我们已经没有任何隐私了，因为如今有关我们的一切都被记录在了某个地方。","source":"（2023年真题·阅读理解·Passage Two）","speechText":"My most negative opinion is that we don't have any privacy anymore because everything about us is now recorded someplace.","annotations":[],"targetForms":[],"audio":"audio/course-examples/f8316133e75a61bb2720bba2.mp3"},{"text":"But when it comes to teaching a large lecture hall of 100-plus first-year students, first impressions are make or break.","translation":"但要给100多名一年级学生的大班授课时，第一印象往往决定成败。","source":"（2024年真题·阅读理解·Passage One）","speechText":"But when it comes to teaching a large lecture hall of 100-plus first-year students, first impressions are make or break.","annotations":[],"targetForms":[],"audio":"audio/course-examples/c309105d08853f7ed3f6f4cd.mp3"},{"text":"The road to the island only appears when the tide has receded.","translation":"只有退潮后，通往那座岛的道路才会显露出来。","source":"（2014年真题·词汇语法·第27题）","speechText":"The road to the island only appears when the tide has receded.","annotations":[],"targetForms":[],"audio":"audio/course-examples/22442b46e28ed495a05b7921.mp3"},{"text":"A smile has proven to have a positive effect on the mind and soul.","translation":"事实证明，微笑会对人的思想和心灵产生积极影响。","source":"（2021年真题·选句填空·完整句选项）","speechText":"A smile has proven to have a positive effect on the mind and soul.","annotations":[],"targetForms":[],"audio":"audio/course-examples/a8b8623387e55a3913975c67.mp3"},{"text":"“It’s like water turning from a liquid to a solid form,” says Katsuhiro Nishinari, a physicist at the University of Tokyo.","translation":"东京大学物理学家Katsuhiro Nishinari说：“这就像水从液态变成固态一样。”","source":"（2025年真题·阅读理解·Passage Three）","speechText":"“It’s like water turning from a liquid to a solid form,” says Katsuhiro Nishinari, a physicist at the University of Tokyo.","annotations":[],"targetForms":[],"audio":"audio/course-examples/1e2212a6bc1c5bd262cb993b.mp3"},{"text":"In 2002 an amazing 89 percent of workers said they were very satisfied or somewhat satisfied with their jobs.","translation":"2002年，竟有89%的劳动者表示，他们对自己的工作非常满意或比较满意。","source":"（2016年真题·阅读理解·Passage One）","speechText":"In 2002 an amazing 89 percent of workers said they were very satisfied or somewhat satisfied with their jobs.","annotations":[],"targetForms":[],"audio":"audio/course-examples/30cee7c72846acffab864f24.mp3"},{"text":"She was educated（educate的过去分词形式） at the local Amherst Academy and Mount Holyoke Women’s Seminary.","translation":"她曾就读于当地的阿默斯特学院和霍利奥克山女子学校。","source":"（2015年真题·阅读理解·Passage Three）","speechText":"She was educated at the local Amherst Academy and Mount Holyoke Women’s Seminary.","annotations":[{"text":"（educate的过去分词形式）","start":16,"end":32,"anchor":"educated"}],"targetForms":["educated"],"audio":"audio/course-examples/6b558587d30abb9d662d6860.mp3"},{"text":"Besides, to stop children from using these services just because crimes（crime的复数形式） are being committed online would be like telling them not to attend college because students may have accidents on campus.","translation":"此外，仅仅因为网络上存在犯罪行为就禁止儿童使用这些服务，这就像是告诉他们不要去上大学，理由是学生在校园里可能会遭遇意外。","source":"（2017年真题·阅读理解·Passage One）","speechText":"Besides, to stop children from using these services just because crimes are being committed online would be like telling them not to attend college because students may have accidents on campus.","annotations":[{"text":"（crime的复数形式）","start":71,"end":83,"anchor":"crimes"}],"targetForms":["crimes"],"audio":"audio/course-examples/00c96d1973be626afa925f00.mp3"},{"text":"Haglund believes the app can teach responsible spending habits, whereas schools tend to focus more on economic theories（theory的复数形式）.","translation":"Haglund认为，这款应用能够教会孩子负责任的消费习惯，而学校往往更侧重经济理论。","source":"（2020年真题·阅读理解·Passage Three）","speechText":"Haglund believes the app can teach responsible spending habits, whereas schools tend to focus more on economic theories.","annotations":[{"text":"（theory的复数形式）","start":119,"end":132,"anchor":"theories"}],"targetForms":["theories"],"audio":"audio/course-examples/f6f8d63a07c5b00d41975218.mp3"},{"text":"This new instrument is far superior to the old one we bought three years ago.","translation":"这台新仪器远比我们三年前买的那台旧仪器好。","source":"（2013年真题·词汇语法·第47题）","speechText":"This new instrument is far superior to the old one we bought three years ago.","annotations":[],"targetForms":[],"audio":"audio/course-examples/ba13aa0b624d5182b086723a.mp3"}]},"6":{"vocabulary":[{"word":"incredible","ipa":"/ɪnˈkredəb(ə)l/","partsOfSpeech":"adj.","meaning":"难以置信的，极好的，惊人的"},{"word":"piece","ipa":"/piːs/","partsOfSpeech":"n.","meaning":"块，件，篇，部分"},{"word":"soldier","ipa":"/ˈsəʊldʒə(r)/","partsOfSpeech":"n.","meaning":"士兵，军人"},{"word":"grandchild","ipa":"/ˈɡræntʃaɪld/","partsOfSpeech":"n.","meaning":"孙子/女，外孙子/女"},{"word":"straight","ipa":"/streɪt/","partsOfSpeech":"adj./adv.","meaning":"直的；笔直地，直接地，坦率地"},{"word":"emotion","ipa":"/ɪˈməʊʃ(ə)n/","partsOfSpeech":"n.","meaning":"情绪，情感，激动"},{"word":"muscle","ipa":"/ˈmʌs(ə)l/","partsOfSpeech":"n.","meaning":"肌肉，力量"},{"word":"cry","ipa":"/kraɪ/","partsOfSpeech":"v./n.","meaning":"哭泣，叫喊，呼号，大声说"},{"word":"narrow","ipa":"/ˈnærəʊ/","partsOfSpeech":"adj./v.","meaning":"狭窄的，有限的，勉强的；变窄"},{"word":"fish","ipa":"/fɪʃ/","partsOfSpeech":"n./v.","meaning":"鱼，鱼肉，钓鱼，搜寻"},{"word":"enter","ipa":"/ˈentə(r)/","partsOfSpeech":"v.","meaning":"进入，参加，输入，登记"},{"word":"our","ipa":"/ˈaʊə(r)/","partsOfSpeech":"det.","meaning":"我们的"},{"word":"creature","ipa":"/ˈkriːtʃə(r)/","partsOfSpeech":"n.","meaning":"生物，动物，创造物"},{"word":"job","ipa":"/dʒɒb/","partsOfSpeech":"n.","meaning":"工作，职业，任务"},{"word":"too","ipa":"/tuː/","partsOfSpeech":"adv.","meaning":"也，太，非常，过于"}],"examples":[{"text":"Whether you volunteer at your local youth group or take dogs from shelters for a walk, the simple fact that you are giving up your time to help someone else is incredible.","translation":"无论是去当地的青年团体做志愿者，还是带收容所里的狗去散步，只要你愿意贡献出自己的时间去帮助他人，这本身就是一件了不起的事。","source":"（2018年配套材料·选句填空）","speechText":"Whether you volunteer at your local youth group or take dogs from shelters for a walk, the simple fact that you are giving up your time to help someone else is incredible.","annotations":[],"targetForms":[],"audio":"audio/20261016-list1/examples/04.mp3"},{"text":"The rooms are almost empty, and the only pieces（piece的复数形式） of furniture are a simple table and a folded sofa.","translation":"房间里几乎空无一物，仅有的家具是一张简单的桌子和一张折叠沙发。","source":"（2021年真题·阅读理解·Passage Two）","speechText":"The rooms are almost empty, and the only pieces of furniture are a simple table and a folded sofa.","annotations":[{"text":"（piece的复数形式）","start":47,"end":59,"anchor":"pieces"}],"targetForms":["pieces"],"audio":"audio/course-examples/5a558116e0c5525377e7278a.mp3"},{"text":"Should we produce soldiers（soldier的复数形式） to do our fighting?","translation":"我们是否应该培养士兵来替我们作战？","source":"（2019年真题·阅读理解·Passage Two）","speechText":"Should we produce soldiers to do our fighting?","annotations":[{"text":"（soldier的复数形式）","start":26,"end":40,"anchor":"soldiers"}],"targetForms":["soldiers"],"audio":"audio/course-examples/8ba26d5593ad2be496ed8d97.mp3"},{"text":"Today's grandparents are joining their grandchildren（grandchild的复数形式） on social media.","translation":"如今，祖父母也开始加入社交媒体，与孙辈们保持联系。","source":"（2021年真题·阅读理解·Passage Three）","speechText":"Today's grandparents are joining their grandchildren on social media.","annotations":[{"text":"（grandchild的复数形式）","start":52,"end":69,"anchor":"grandchildren"}],"targetForms":["grandchildren"],"audio":"audio/course-examples/1a24d245a2625369f82693fd.mp3"},{"text":"There are three main factors that allow deserts to form next to oceans: how air goes straight up or down, how air moves horizontally (水平地), and how mountain ranges interact with air moisture (水汽).","translation":"有三个主要因素使沙漠能够在海洋附近形成：空气如何垂直升降、如何水平移动，以及山脉如何与空气中的水分相互作用。","source":"（2026年真题·阅读理解·Passage Three）","speechText":"There are three main factors that allow deserts to form next to oceans: how air goes straight up or down, how air moves horizontally , and how mountain ranges interact with air moisture .","annotations":[{"text":"(水平地)","start":133,"end":138,"anchor":"horizontally"},{"text":"(水汽)","start":191,"end":195,"anchor":"moisture"}],"targetForms":[],"audio":"audio/course-examples/7475098f45b558798b70540b.mp3"},{"text":"Gratitude is a simple but powerful emotion that can change our life.","translation":"感恩是一种简单却有力量的情感，能够改变我们的生活。","source":"（2016年配套材料·英译汉）","speechText":"Gratitude is a simple but powerful emotion that can change our life.","annotations":[],"targetForms":[],"audio":"audio/course-examples/93d1243c3ff4dc73dc2a0f09.mp3"},{"text":"Recent research suggests that backward walking does more than strengthen muscles（muscle的复数形式）—it also sharpens cognitive function.","translation":"近期研究表明，倒着走不仅能增强肌肉，还能提升认知功能。","source":"（2025年真题·阅读理解·Passage Two）","speechText":"Recent research suggests that backward walking does more than strengthen muscles—it also sharpens cognitive function.","annotations":[{"text":"（muscle的复数形式）","start":80,"end":93,"anchor":"muscles"}],"targetForms":["muscles"],"audio":"audio/course-examples/0567b4369fe0417812d74fbb.mp3"},{"text":"Lin Daiyu is so sensitive that she even cries（cry的第三人称单数形式） for the falling flowers in spring.","translation":"林黛玉十分敏感，甚至会为春天的落花流泪。","source":"（2018年真题·词汇语法·第28题）","speechText":"Lin Daiyu is so sensitive that she even cries for the falling flowers in spring.","annotations":[{"text":"（cry的第三人称单数形式）","start":45,"end":59,"anchor":"cries"}],"targetForms":["cries"],"audio":"audio/course-examples/e459e1180c9b80fe764a446a.mp3"},{"text":"The boy had a narrow escape when he ran across the road in front of the bus.","translation":"那个男孩在公交车前横穿马路，险些遭遇不测。","source":"（2019年真题·词汇语法·第37题）","speechText":"The boy had a narrow escape when he ran across the road in front of the bus.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e96396a3bd8c06ef9a40e84d.mp3"},{"text":"Some of these wastes are eaten directly by the larger fishes（fish的复数形式）.","translation":"其中一些废弃物会直接被体型较大的鱼吃掉。","source":"（2015年配套材料·选词填空）","speechText":"Some of these wastes are eaten directly by the larger fishes.","annotations":[{"text":"（fish的复数形式）","start":60,"end":71,"anchor":"fishes"}],"targetForms":["fishes"],"audio":"audio/course-examples/4e2f99b87f6d3aecdcdf4af6.mp3"},{"text":"You have no business entering（enter的-ing形式） that office building after dark.","translation":"天黑后，你无权进入那栋办公楼。","source":"（2013年真题·词汇语法·第21题）","speechText":"You have no business entering that office building after dark.","annotations":[{"text":"（enter的-ing形式）","start":29,"end":43,"anchor":"entering"}],"targetForms":["entering"],"audio":"audio/course-examples/0d5c7b9e94e31f10e29100fc.mp3"},{"text":"Focusing on our health is particularly crucial.","translation":"关注我们的健康尤为重要。","source":"（2025年真题·选句填空）","speechText":"Focusing on our health is particularly crucial.","annotations":[],"targetForms":[],"audio":"audio/20261016-list1/examples/13.mp3"},{"text":"As each black creature fluttered and flapped away into the graying sky, she watched it, tears in her eyes.","translation":"每一只黑色的小生灵振翅飞向渐渐泛灰的天空时，她都望着它，眼中含着泪水。","source":"（2014年真题·词汇语法·第45题）","speechText":"As each black creature fluttered and flapped away into the graying sky, she watched it, tears in her eyes.","annotations":[],"targetForms":[],"audio":"audio/course-examples/8f766aff6f61fccf39d6fda8.mp3"},{"text":"For most Americans, job satisfaction is nearly equivalent to life satisfaction.","translation":"对大多数美国人来说，工作满意度几乎等同于生活满意度。","source":"（2016年真题·阅读理解·Passage One）","speechText":"For most Americans, job satisfaction is nearly equivalent to life satisfaction.","annotations":[],"targetForms":[],"audio":"audio/course-examples/f86ff423b9eb4101b9244039.mp3"},{"text":"Families, too, are simpler today.","translation":"如今，家庭结构也更加简单了。","source":"（2013年真题·阅读理解·Passage Two）","speechText":"Families, too, are simpler today.","annotations":[],"targetForms":[],"audio":"audio/course-examples/d8737ae88b75c8280f120a99.mp3"}]},"7":{"vocabulary":[{"word":"care","ipa":"/keə(r)/","partsOfSpeech":"n./v.","meaning":"照顾，关心，照料，忧虑，护理"},{"word":"human","ipa":"/ˈhjuːmən/","partsOfSpeech":"adj./n.","meaning":"人的，人类的，人类"},{"word":"level","ipa":"/ˈlev(ə)l/","partsOfSpeech":"n./adj./v.","meaning":"水平，等级，平坦的，使平坦"},{"word":"college","ipa":"/ˈkɒlɪdʒ/","partsOfSpeech":"n.","meaning":"大学，学院，学会"},{"word":"insect","ipa":"/ˈɪnsekt/","partsOfSpeech":"n.","meaning":"昆虫，卑鄙的人"},{"word":"religious","ipa":"/rɪˈlɪdʒəs/","partsOfSpeech":"adj.","meaning":"宗教的，虔诚的，笃信宗教的"},{"word":"society","ipa":"/səˈsaɪəti/","partsOfSpeech":"n.","meaning":"社会，协会，交际"},{"word":"oil","ipa":"/ɔɪl/","partsOfSpeech":"n./v.","meaning":"油，石油，给...加润滑油"},{"word":"moment","ipa":"/ˈməʊmənt/","partsOfSpeech":"n.","meaning":"瞬间，片刻，时刻，时机"},{"word":"rest","ipa":"/rest/","partsOfSpeech":"n./v.","meaning":"休息，剩余部分，停止，依靠"},{"word":"install","ipa":"/ɪnˈstɔːl/","partsOfSpeech":"v.","meaning":"安装，安置，任命，设置"},{"word":"spring","ipa":"/sprɪŋ/","partsOfSpeech":"n./v.","meaning":"春天，泉水，跳跃，涌现"},{"word":"within","ipa":"/wɪˈðɪn/","partsOfSpeech":"prep./adv.","meaning":"在...之内，在内部"},{"word":"range","ipa":"/reɪndʒ/","partsOfSpeech":"n./v.","meaning":"范围，山脉，排列，漫游"},{"word":"note","ipa":"/nəʊt/","partsOfSpeech":"n./v.","meaning":"笔记，便条，注意，记录，指出"}],"examples":[{"text":"If symptoms persist, contact your health care professional.","translation":"如果症状持续，请联系医护人员。","source":"（2015年配套材料·选句填空）","speechText":"If symptoms persist, contact your health care professional.","annotations":[],"targetForms":[],"audio":"audio/course-examples/ca3bfe402acad9e975731e99.mp3"},{"text":"Thousands of years ago, humans（human的复数形式） collected nuts and fruits.","translation":"几千年前，人类采集坚果和水果。","source":"（2022年真题·阅读理解·Passage One）","speechText":"Thousands of years ago, humans collected nuts and fruits.","annotations":[{"text":"（human的复数形式）","start":30,"end":42,"anchor":"humans"}],"targetForms":["humans"],"audio":"audio/course-examples/380ee8d2396124ce1c5f2fdd.mp3"},{"text":"The latter represents higher levels（level的复数形式） of comprehension.","translation":"后者代表着更高层次的理解。","source":"（2016年真题·阅读理解·Passage Two）","speechText":"The latter represents higher levels of comprehension.","annotations":[{"text":"（level的复数形式）","start":35,"end":47,"anchor":"levels"}],"targetForms":["levels"],"audio":"audio/course-examples/0492698f0fe48669c55c3e9a.mp3"},{"text":"Jim’s plans to go to college fell through at the last moment.","translation":"Jim的上大学计划在最后关头落空了。","source":"（2019年真题·词汇语法·第35题）","speechText":"Jim’s plans to go to college fell through at the last moment.","annotations":[],"targetForms":[],"audio":"audio/course-examples/f661de506f5ba4a2fe2326ec.mp3"},{"text":"In early spring, those insects（insect的复数形式） are still sleeping.","translation":"早春时节，那些昆虫还在休眠。","source":"（2023年真题·阅读理解·Passage One）","speechText":"In early spring, those insects are still sleeping.","annotations":[{"text":"（insect的复数形式）","start":30,"end":43,"anchor":"insects"}],"targetForms":["insects"],"audio":"audio/course-examples/7ba20212fcb894e321f52f68.mp3"},{"text":"The Jews followed their example, but kept every seventh day for religious purposes.","translation":"犹太人效仿了他们的做法，但把每七天中的第七天保留作宗教活动之用。","source":"（2019年真题·阅读理解·Passage Three）","speechText":"The Jews followed their example, but kept every seventh day for religious purposes.","annotations":[],"targetForms":[],"audio":"audio/course-examples/4024c9ed1370c639683c84b3.mp3"},{"text":"Minimalism goes against consumer society by dramatically reducing possessions.","translation":"极简主义通过大幅减少个人物品，来对抗消费社会的观念。","source":"（2021年真题·阅读理解·Passage Two）","speechText":"Minimalism goes against consumer society by dramatically reducing possessions.","annotations":[],"targetForms":[],"audio":"audio/course-examples/df08de1ba6f4159633a89635.mp3"},{"text":"Environmentalists are doing everything within their power to minimize the impact of the oil spill.","translation":"环保人士正在竭尽所能，尽量减轻漏油事件的影响。","source":"（2014年真题·词汇语法·第28题）","speechText":"Environmentalists are doing everything within their power to minimize the impact of the oil spill.","annotations":[],"targetForms":[],"audio":"audio/course-examples/1e6217a1deddd24833f61a74.mp3"},{"text":"The moment we think about canceling a plan, guilt follows.","translation":"当我们动了取消计划的念头时，内疚感便随之而来。","source":"（2026年真题·阅读理解·Passage One）","speechText":"The moment we think about canceling a plan, guilt follows.","annotations":[],"targetForms":[],"audio":"audio/course-examples/f14e061591f384e79b41a21d.mp3"},{"text":"Despite the good news, civil engineers aren’t resting（rest的-ing形式） on their successes.","translation":"尽管传来了好消息，土木工程师们并没有满足于已经取得的成功。","source":"（2014年真题·阅读理解·Passage Three）","speechText":"Despite the good news, civil engineers aren’t resting on their successes.","annotations":[{"text":"（rest的-ing形式）","start":53,"end":66,"anchor":"resting"}],"targetForms":["resting"],"audio":"audio/course-examples/16cb5545765d5f85dd2c985b.mp3"},{"text":"This is one of two schools in Richmond where the city has installed（install的过去分词形式） new enforcement cameras to catch speeders.","translation":"这是里士满市内两所安装了新型执法摄像头的学校之一，这些摄像头旨在抓拍超速行驶者。","source":"（2024年真题·阅读理解·Passage Two）","speechText":"This is one of two schools in Richmond where the city has installed new enforcement cameras to catch speeders.","annotations":[{"text":"（install的过去分词形式）","start":67,"end":83,"anchor":"installed"}],"targetForms":["installed"],"audio":"audio/course-examples/dff25f694569c7c5de0783ee.mp3"},{"text":"In early spring, those insects are still sleeping.","translation":"早春时节，那些昆虫还在休眠。","source":"（2023年真题·阅读理解·Passage One）","speechText":"In early spring, those insects are still sleeping.","annotations":[],"targetForms":[],"audio":"audio/course-examples/7ba20212fcb894e321f52f68.mp3"},{"text":"Within a few days she was 'trying out' for me.","translation":"几天之内，她就为我“试镜”了。","source":"（2017年真题·阅读理解·Passage Three）","speechText":"Within a few days she was 'trying out' for me.","annotations":[],"targetForms":[],"audio":"audio/course-examples/30fb2558ba0621eb00474b8e.mp3"},{"text":"The apps suggest minimum ages ranging（range的-ing形式） from six to nine for the prepaid card.","translation":"应用程序建议预付卡的适用年龄为六至九岁。","source":"（2020年真题·阅读理解·Passage Three）","speechText":"The apps suggest minimum ages ranging from six to nine for the prepaid card.","annotations":[{"text":"（range的-ing形式）","start":37,"end":51,"anchor":"ranging"}],"targetForms":["ranging"],"audio":"audio/course-examples/56025b8b979ef31c3c156004.mp3"},{"text":"Many humpbacks seek to bring in mates with a combination of singing and physical movements, the study notes（note的第三人称单数形式）.","translation":"研究指出，许多座头鲸试图通过唱歌和身体动作相结合的方式来吸引配偶。","source":"（2023年真题·阅读理解·Passage Three）","speechText":"Many humpbacks seek to bring in mates with a combination of singing and physical movements, the study notes.","annotations":[{"text":"（note的第三人称单数形式）","start":107,"end":122,"anchor":"notes"}],"targetForms":["notes"],"audio":"audio/course-examples/7dbd130b83974c4c38d7f1e0.mp3"}]},"8":{"vocabulary":[{"word":"dollar","ipa":"/ˈdɒlə(r)/","partsOfSpeech":"n.","meaning":"美元，元（货币单位）"},{"word":"heart","ipa":"/hɑːt/","partsOfSpeech":"n.","meaning":"心脏，内心，中心，核心"},{"word":"upon","ipa":"/əˈpɒn/","partsOfSpeech":"prep.","meaning":"在...之上，根据，接近"},{"word":"arrange","ipa":"/əˈreɪndʒ/","partsOfSpeech":"v.","meaning":"安排，排列，整理，准备"},{"word":"top","ipa":"/tɒp/","partsOfSpeech":"n./adj.","meaning":"顶部，顶端，最高的，首要的"},{"word":"spare","ipa":"/speə(r)/","partsOfSpeech":"adj./v./n.","meaning":"多余的，备用的，节约，备用零件"},{"word":"supply","ipa":"/səˈplaɪ/","partsOfSpeech":"v./n.","meaning":"供给，补给，生活用品"},{"word":"bell","ipa":"/bel/","partsOfSpeech":"n.","meaning":"钟，铃，钟声，铃声"},{"word":"customer","ipa":"/ˈkʌstəmə(r)/","partsOfSpeech":"n.","meaning":"顾客，主顾，客户"},{"word":"embrace","ipa":"/ɪmˈbreɪs/","partsOfSpeech":"v./n.","meaning":"拥抱，包含，欣然接受，信奉"},{"word":"trust","ipa":"/trʌst/","partsOfSpeech":"n./v.","meaning":"信任，信赖，托付，相信"},{"word":"murder","ipa":"/ˈmɜːdə(r)/","partsOfSpeech":"n./v.","meaning":"谋杀，杀害，谋杀罪"},{"word":"feed","ipa":"/fiːd/","partsOfSpeech":"v./n.","meaning":"喂养，供给，进食，饲料"},{"word":"cat","ipa":"/kæt/","partsOfSpeech":"n.","meaning":"猫，猫科动物"},{"word":"tissue","ipa":"/ˈtɪʃuː/","partsOfSpeech":"n.","meaning":"组织，纸巾，薄纱"}],"examples":[{"text":"Mary changed her dollars（dollar的复数形式） for the equivalent amount of pounds.","translation":"Mary把美元兑换成了等值的英镑。","source":"（2017年真题·词汇语法·第33题）","speechText":"Mary changed her dollars for the equivalent amount of pounds.","annotations":[{"text":"（dollar的复数形式）","start":24,"end":37,"anchor":"dollars"}],"targetForms":["dollars"],"audio":"audio/course-examples/7bfc26ee06cafc87faffbb0c.mp3"},{"text":"Then, my heart was filled with joy and happiness.","translation":"那时，我的心里充满了喜悦和幸福。","source":"（2025年真题·翻译）","speechText":"Then, my heart was filled with joy and happiness.","annotations":[],"targetForms":[],"audio":"audio/course-examples/408baaa258850fedfb05c543.mp3"},{"text":"You can start by coming up with a media plan based upon your family's priorities and circumstances.","translation":"你可以先根据家庭的重点需求和具体情况，制定一份媒体使用计划。","source":"（2026年真题·阅读理解·Passage Two）","speechText":"You can start by coming up with a media plan based upon your family's priorities and circumstances.","annotations":[],"targetForms":[],"audio":"audio/course-examples/91496db73b17cb16ad09d954.mp3"},{"text":"The question is: How do we arrange them in a fair way with the public support?","translation":"问题是：我们如何在获得公众支持的同时，以公平的方式安排它们？","source":"（2024年真题·阅读理解·Passage Two）","speechText":"The question is: How do we arrange them in a fair way with the public support?","annotations":[],"targetForms":[],"audio":"audio/course-examples/58d83d5bd92ea870737735e6.mp3"},{"text":"Getting on well with yourself should be a top priority to you if you want to be a happy person.","translation":"如果你想成为一个快乐的人，就应该把与自己和谐相处放在首位。","source":"（2023年真题·翻译）","speechText":"Getting on well with yourself should be a top priority to you if you want to be a happy person.","annotations":[],"targetForms":[],"audio":"audio/course-examples/7f8d66e90b75ff9a100029b5.mp3"},{"text":"Should we grow reserve organs for ourselves, each of us having, as it were, a \"savings bank\" full of spare kidneys, livers, or hands?","translation":"我们是否应该为自己培育备用器官，让每个人都拥有一个“储蓄库”，里面存满了备用的肾脏、肝脏或手？","source":"（2019年·阅读理解·Passage Two）","speechText":"Should we grow reserve organs for ourselves, each of us having, as it were, a \"savings bank\" full of spare kidneys, livers, or hands?","annotations":[],"targetForms":[],"audio":"audio/course-examples/e89c98b0dcc409fcfc0eadab.mp3"},{"text":"At Lufka Refillable Zero Waste store in Tampa, customers bring in reusable containers to fill with soap, shampoo and cleaning supplies （supply的复数形式）instead of buying products in single-use packaging.","translation":"在坦帕的 Lufka 可重复填充零废弃商店，顾客带来可重复使用的容器，装入肥皂、洗发水和清洁用品，而不是购买采用一次性包装的产品。","source":"（2026年真题·选词填空）","speechText":"At Lufka Refillable Zero Waste store in Tampa, customers bring in reusable containers to fill with soap, shampoo and cleaning supplies instead of buying products in single-use packaging.","annotations":[{"text":"（supply的复数形式）","start":135,"end":148,"anchor":"supplies"}],"targetForms":["supplies"],"audio":"audio/course-examples/bf0ca81b176602377245ff4c.mp3"},{"text":"It was as if a warning bell went off in my head.","translation":"仿佛我的脑海中响起了警报声。","source":"（2017年真题·阅读理解·Passage Three）","speechText":"It was as if a warning bell went off in my head.","annotations":[],"targetForms":[],"audio":"audio/course-examples/ea1ca3a75c86357637c8d217.mp3"},{"text":"Customers'（customer的复数所有格形式） containers are weighed first, then filled.","translation":"先给顾客的容器称重，然后再装入商品。","source":"（2026年真题·完形填空）","speechText":"Customers' containers are weighed first, then filled.","annotations":[{"text":"（customer的复数所有格形式）","start":10,"end":28,"anchor":"Customers"}],"targetForms":["Customers"],"audio":"audio/course-examples/9dac400994454d068c5e7cd2.mp3"},{"text":"The foreigner may be unsure as to when to shake hands or embrace, when to start conversations, or how to approach a stranger.","translation":"外国人可能不确定什么时候应该握手或拥抱，什么时候开始交谈，或者怎样接近一位陌生人并与其交往。","source":"（2019年配套材料·选词填空）","speechText":"The foreigner may be unsure as to when to shake hands or embrace, when to start conversations, or how to approach a stranger.","annotations":[],"targetForms":[],"audio":"audio/course-examples/da99ee1cbf2b1d2104a3054f.mp3"},{"text":"Try to see if the story you are reading is on the news sites that you know and trust.","translation":"试着查看一下，你正在阅读的这篇报道是否也出现在你熟悉并信任的新闻网站上。","source":"（2020年真题·选句填空）","speechText":"Try to see if the story you are reading is on the news sites that you know and trust.","annotations":[],"targetForms":[],"audio":"audio/course-examples/1ca6a4801198d7df91e95603.mp3"},{"text":"He was charged by the police with having murdered（murder的过去分词形式） his wife.","translation":"警方指控他谋杀了自己的妻子。","source":"（2016年真题·词汇语法·第36题）","speechText":"He was charged by the police with having murdered his wife.","annotations":[{"text":"（murder的过去分词形式）","start":49,"end":64,"anchor":"murdered"}],"targetForms":["murdered"],"audio":"audio/course-examples/75e04eb723a8dc60e6a60828.mp3"},{"text":"When Ben is hungry, he will remind his family to feed him.","translation":"Ben饿了的时候，会提醒家人给它喂食。","source":"（2025年真题·阅读理解·Passage One·阅读题补全）","speechText":"When Ben is hungry, he will remind his family to feed him.","annotations":[],"targetForms":[],"audio":"audio/course-examples/b37d322030ea9801c2910f6b.mp3"},{"text":"That fall, Yulia and her daughter were planning to adopt their first cat.","translation":"那个秋天，Yulia和女儿正计划领养她们的第一只猫。","source":"（2025年真题·阅读理解·Passage One）","speechText":"That fall, Yulia and her daughter were planning to adopt their first cat.","annotations":[],"targetForms":[],"audio":"audio/course-examples/9788f28cad095cded792106d.mp3"},{"text":"Another technique takes embryo (胚胎) cells and develops them into a wide variety of cell types and tissues（tissue的复数形式）.","translation":"另一种技术利用胚胎细胞，将其培养成各种不同类型的细胞和组织。","source":"（2017年配套材料·选词填空）","speechText":"Another technique takes embryo cells and develops them into a wide variety of cell types and tissues.","annotations":[{"text":"(胚胎)","start":31,"end":35,"anchor":"embryo"},{"text":"（tissue的复数形式）","start":105,"end":118,"anchor":"tissues"}],"targetForms":["tissues"],"audio":"audio/course-examples/c13c9101c8789e7edf25d898.mp3"}]},"9":{"vocabulary":[{"word":"duration","ipa":"/djuˈreɪʃn/","partsOfSpeech":"n.","meaning":"持续时间，期间"},{"word":"somehow","ipa":"/ˈsʌmhaʊ/","partsOfSpeech":"adv.","meaning":"以某种方式，不知怎么地，设法"},{"word":"factory","ipa":"/ˈfæktri; ˈfæktəri/","partsOfSpeech":"n.","meaning":"工厂，制造厂"},{"word":"touch","ipa":"/tʌtʃ/","partsOfSpeech":"v./n.","meaning":"触摸，接触，联系"},{"word":"upset","ipa":"/ˌʌpˈset/","partsOfSpeech":"adj./v.","meaning":"心烦的，苦恼的，打乱，使心烦"},{"word":"like","ipa":"/laɪk/","partsOfSpeech":"prep./v./conj.","meaning":"像，如同，喜欢，例如"},{"word":"think","ipa":"/θɪŋk/","partsOfSpeech":"v.","meaning":"想，认为，思考，考虑"},{"word":"young","ipa":"/jʌŋ/","partsOfSpeech":"adj./n.","meaning":"年轻的，幼小的，年轻人，幼崽"},{"word":"author","ipa":"/ˈɔːθə(r)/","partsOfSpeech":"n./v.","meaning":"作者，作家，创始人，撰写"},{"word":"high","ipa":"/haɪ/","partsOfSpeech":"adj./adv.","meaning":"高的，高级的，高高地"},{"word":"habit","ipa":"/ˈhæbɪt/","partsOfSpeech":"n.","meaning":"习惯，习性，嗜好"},{"word":"believe","ipa":"/bɪˈliːv/","partsOfSpeech":"v.","meaning":"相信，认为，猜想"},{"word":"invent","ipa":"/ɪnˈvent/","partsOfSpeech":"v.","meaning":"发明，创造，虚构"},{"word":"mind","ipa":"/maɪnd/","partsOfSpeech":"n./v.","meaning":"头脑，理智；介意"},{"word":"soil","ipa":"/sɔɪl/","partsOfSpeech":"n.","meaning":"泥土，土壤"}],"examples":[{"text":"One paper looking into the ideal amount of sleep found that “Sleep duration recommendations issued by public health authorities help to inform the population of interventions, policies, and healthy sleep behaviors.”","translation":"一项研究睡眠理想时长的论文发现：“公共卫生机构发布的睡眠时长建议有助于向公众传达干预措施、政策以及健康睡眠行为的信息。”","source":"（2024年真题·阅读理解·Passage Three）","speechText":"One paper looking into the ideal amount of sleep found that “Sleep duration recommendations issued by public health authorities help to inform the population of interventions, policies, and healthy sleep behaviors.”","annotations":[],"targetForms":[],"audio":"audio/course-examples/0284cfa20eecf1fdf4983448.mp3"},{"text":"But unlike cars, ants somehow manage to avoid the problem of stop-and-go traffic.","translation":"但与汽车不同，蚂蚁似乎总能设法避免走走停停的交通问题。","source":"（2025年真题·阅读理解·Passage Three）","speechText":"But unlike cars, ants somehow manage to avoid the problem of stop-and-go traffic.","annotations":[],"targetForms":[],"audio":"audio/course-examples/4ddfa6becb113bdeb0050a15.mp3"},{"text":"This situation changed, however, when suddenly factories（factory的复数形式） began dumping enormous quantities of materials into the seas.","translation":"然而，当工厂突然开始向海洋倾倒大量物质时，这种情况就改变了。","source":"（2015年配套材料·选词填空）","speechText":"This situation changed, however, when suddenly factories began dumping enormous quantities of materials into the seas.","annotations":[{"text":"（factory的复数形式）","start":56,"end":70,"anchor":"factories"}],"targetForms":["factories"],"audio":"audio/course-examples/5e4e298d1fa0881c8f66f89c.mp3"},{"text":"Don't touch that wire, it's live.","translation":"别碰那根电线，它带电。","source":"（2016年真题·词汇语法·第35题）","speechText":"Don't touch that wire, it's live.","annotations":[],"targetForms":[],"audio":"audio/course-examples/dddddf294d41da57d86b493e.mp3"},{"text":"If you’re feeling tired, upset or lonely, getting lost in a story can give you comfort and help you to relax.","translation":"如果你感到疲惫、烦躁或孤独，沉浸在一个故事中能给你安慰，也有助于放松身心。","source":"（2016年配套材料·选句填空）","speechText":"If you’re feeling tired, upset or lonely, getting lost in a story can give you comfort and help you to relax.","annotations":[],"targetForms":[],"audio":"audio/course-examples/80dd30192ac29b5a76aef3fe.mp3"},{"text":"No one likes（like的第三人称单数形式） getting a speeding ticket.","translation":"没有人喜欢收到超速罚单。","source":"（2024年真题·阅读理解·Passage Two）","speechText":"No one likes getting a speeding ticket.","annotations":[{"text":"（like的第三人称单数形式）","start":12,"end":27,"anchor":"likes"}],"targetForms":["likes"],"audio":"audio/course-examples/1247cf277b98fb112a0bb8e1.mp3"},{"text":"Nobody will think what you say is foolish.","translation":"没有人会认为你说的话很愚蠢。","source":"（2017年真题·阅读理解·Passage Two）","speechText":"Nobody will think what you say is foolish.","annotations":[],"targetForms":[],"audio":"audio/course-examples/73327aafadb7a430832de20a.mp3"},{"text":"Young adult women have new freedom, too.","translation":"年轻的成年女性也拥有了新的自由。","source":"（2013年真题·阅读理解·Passage Two）","speechText":"Young adult women have new freedom, too.","annotations":[],"targetForms":[],"audio":"audio/course-examples/3719ee04bac687152ed3b2df.mp3"},{"text":"No author in American literature is better known or more loved than Samuel Langhorne Clemens.","translation":"在美国文学界，没有哪位作家比Samuel Langhorne Clemens更有名，也没有哪位作家比他更受喜爱。","source":"（2013年真题·阅读理解·Passage Three）","speechText":"No author in American literature is better known or more loved than Samuel Langhorne Clemens.","annotations":[],"targetForms":[],"audio":"audio/course-examples/3ef9536bc2e3302862b875aa.mp3"},{"text":"The latter represents higher（high的比较级） levels of comprehension.","translation":"后者代表着更高层次的理解。","source":"（2016年真题·阅读理解·Passage Two）","speechText":"The latter represents higher levels of comprehension.","annotations":[{"text":"（high的比较级）","start":28,"end":38,"anchor":"higher"}],"targetForms":["higher"],"audio":"audio/course-examples/0492698f0fe48669c55c3e9a.mp3"},{"text":"Habit can help people adjust to their own energy cycle.","translation":"习惯可以帮助人们适应自身的能量循环。","source":"（2018年真题·阅读理解·Passage Two）","speechText":"Habit can help people adjust to their own energy cycle.","annotations":[],"targetForms":[],"audio":"audio/course-examples/9d3de7b6833dba856d380610.mp3"},{"text":"The study shows that cancelers believe expensive gifts or large favors are necessary.","translation":"研究表明，取消者认为昂贵的礼物或丰厚的恩惠是必要的。","source":"（2026年真题·阅读理解·Passage One）","speechText":"The study shows that cancelers believe expensive gifts or large favors are necessary.","annotations":[],"targetForms":[],"audio":"audio/course-examples/4fd31541486098b830471212.mp3"},{"text":"The reason was quite simple: Men had not invented（invent的过去分词形式） the week.","translation":"原因很简单：人们还没有发明出星期。","source":"（2019年真题·阅读理解·Passage Three）","speechText":"The reason was quite simple: Men had not invented the week.","annotations":[{"text":"（invent的过去分词形式）","start":49,"end":64,"anchor":"invented"}],"targetForms":["invented"],"audio":"audio/course-examples/618b99baa7444c6b94bc533c.mp3"},{"text":"Relax yourself, and make your mind clear.","translation":"放松自己，让头脑清醒起来。","source":"（2017年配套材料·选句填空）","speechText":"Relax yourself, and make your mind clear.","annotations":[],"targetForms":[],"audio":"audio/course-examples/2c4018922f766b593ad1ceda.mp3"},{"text":"Early cleaning of a garden is often followed by early covering the soil with mulch.","translation":"花园的清理往往进行得比较早，随后土壤也会很早就被覆盖上一层覆盖物。","source":"（2023年真题·阅读理解·Passage One）","speechText":"Early cleaning of a garden is often followed by early covering the soil with mulch.","annotations":[],"targetForms":[],"audio":"audio/course-examples/8abce722febdb56c3391cfba.mp3"}]},"10":{"vocabulary":[{"word":"opinion","ipa":"/əˈpɪnjən/","partsOfSpeech":"n.","meaning":"意见，看法，主张，评价"},{"word":"library","ipa":"/ˈlaɪbrəri/","partsOfSpeech":"n.","meaning":"图书馆，藏书"},{"word":"thousand","ipa":"/ˈθaʊz(ə)nd/","partsOfSpeech":"num./n.","meaning":"一千，数千，成千上万"},{"word":"stage","ipa":"/steɪdʒ/","partsOfSpeech":"n./v.","meaning":"阶段，舞台，戏剧，上演"},{"word":"weekend","ipa":"/ˌwiːkˈend; ˈwiːkend/","partsOfSpeech":"n.","meaning":"周末，周末休假"},{"word":"partner","ipa":"/ˈpɑːtnə(r)/","partsOfSpeech":"n./v.","meaning":"伙伴，合伙人，配偶，结成伙伴"},{"word":"nor","ipa":"/nɔː(r)/","partsOfSpeech":"conj./adv.","meaning":"也不，也没有"},{"word":"immediately","ipa":"/ɪˈmiːdiətli/","partsOfSpeech":"adv./conj.","meaning":"立即，马上，直接地；一……就。"},{"word":"head","ipa":"/hed/","partsOfSpeech":"n./v.","meaning":"头，头部，首脑，朝...方向走"},{"word":"water","ipa":"/ˈwɔːtə(r)/","partsOfSpeech":"n./v.","meaning":"水，水域，浇水，流泪"},{"word":"alarm","ipa":"/əˈlɑːm/","partsOfSpeech":"n./v.","meaning":"警报，闹钟，恐慌，使惊恐"},{"word":"attack","ipa":"/əˈtæk/","partsOfSpeech":"v./n.","meaning":"攻击，进攻，抨击，（疾病）发作"},{"word":"nobody","ipa":"/ˈnəʊbədi/","partsOfSpeech":"pron./n.","meaning":"没人，无人；小人物、无足轻重的人。"},{"word":"rely","ipa":"/rɪˈlaɪ/","partsOfSpeech":"v.","meaning":"依靠，依赖，信赖，指望"},{"word":"trace","ipa":"/treɪs/","partsOfSpeech":"v./n.","meaning":"追踪，追溯，痕迹，微量"}],"examples":[{"text":"Psychologists and collectors have different opinions（opinion的复数形式）.","translation":"心理学家和收藏者有着不同的看法。","source":"（2022年真题·阅读理解·Passage One）","speechText":"Psychologists and collectors have different opinions.","annotations":[{"text":"（opinion的复数形式）","start":52,"end":66,"anchor":"opinions"}],"targetForms":["opinions"],"audio":"audio/course-examples/c2cffe55e326be6e72e79551.mp3"},{"text":"You’ll be fined unless you return the books to the school library by this weekend.","translation":"除非你在本周末之前把书归还学校图书馆，否则就会被罚款。","source":"（2018年真题·词汇语法·第23题）","speechText":"You’ll be fined unless you return the books to the school library by this weekend.","annotations":[],"targetForms":[],"audio":"audio/course-examples/ca1382a0437c8327c07ad879.mp3"},{"text":"Thousands（thousand的复数形式） of years ago, humans collected nuts and fruits.","translation":"几千年前，人类采集坚果和水果。","source":"（2022年真题·阅读理解·Passage One）","speechText":"Thousands of years ago, humans collected nuts and fruits.","annotations":[{"text":"（thousand的复数形式）","start":9,"end":24,"anchor":"Thousands"}],"targetForms":["Thousands"],"audio":"audio/course-examples/380ee8d2396124ce1c5f2fdd.mp3"},{"text":"Talk to your students before and after class, walk up and down the stairs when you teach your class rather than stay on the stage.","translation":"课前课后与学生交谈；上课时在阶梯教室的台阶间走动，而不要一直待在讲台上。","source":"（2024年真题·阅读理解·Passage One）","speechText":"Talk to your students before and after class, walk up and down the stairs when you teach your class rather than stay on the stage.","annotations":[],"targetForms":[],"audio":"audio/course-examples/add3081541fe2c98997617d9.mp3"},{"text":"You’ll be fined unless you return the books to the school library by this weekend.","translation":"除非你在本周末之前把书归还学校图书馆，否则就会被罚款。","source":"（2018年真题·词汇语法·第23题）","speechText":"You’ll be fined unless you return the books to the school library by this weekend.","annotations":[],"targetForms":[],"audio":"audio/course-examples/ca1382a0437c8327c07ad879.mp3"},{"text":"As a result, any lessening of their partner’s（partner的所有格形式） attention may be thought of as rejection or abandonment.","translation":"因此，伴侣给予的关注稍有减少，都可能被视为拒绝或抛弃。","source":"（2018年真题·阅读理解·Passage one）","speechText":"As a result, any lessening of their partner’s attention may be thought of as rejection or abandonment.","annotations":[{"text":"（partner的所有格形式）","start":45,"end":60,"anchor":"partner’s"}],"targetForms":["partner’s"],"audio":"audio/course-examples/6b955bfa5552b9f30d4ad64c.mp3"},{"text":"We can’t simply judge a person by his voice, nor can we neglect intonation.","translation":"我们不能仅凭一个人的声音来判断他，也不能忽视语调。","source":"（2018年真题·阅读理解·Passage Three）","speechText":"We can’t simply judge a person by his voice, nor can we neglect intonation.","annotations":[],"targetForms":[],"audio":"audio/course-examples/4d7958c100cfe5602676e1d6.mp3"},{"text":"I immediately bought a used manual typewriter and felt like a genuine writer.","translation":"我立刻买了一台二手手动打字机，觉得自己像个真正的作家了。","source":"（2015年真题·阅读理解·Passage One）","speechText":"I immediately bought a used manual typewriter and felt like a genuine writer.","annotations":[],"targetForms":[],"audio":"audio/course-examples/c9d0776837acc24d596584c7.mp3"},{"text":"He would greet me every morning with head rubs.","translation":"每天早晨，它都会用头蹭我，向我打招呼。","source":"（2025年真题·阅读理解·Passage One）","speechText":"He would greet me every morning with head rubs.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e35d697ffbf108ffa9cc0748.mp3"},{"text":"“It’s like water turning from a liquid to a solid form,” says Katsuhiro Nishinari, a physicist at the University of Tokyo.","translation":"“这就像水从液体变成固体一样。”东京大学的物理学家西成活裕说道。","source":"（2025年真题·阅读理解·Passage Three）","speechText":"“It’s like water turning from a liquid to a solid form,” says Katsuhiro Nishinari, a physicist at the University of Tokyo.","annotations":[],"targetForms":[],"audio":"audio/course-examples/1e2212a6bc1c5bd262cb993b.mp3"},{"text":"The creation and accidental release of extremely poisonous microbes, however, is only one cause for alarm.","translation":"然而，制造出剧毒微生物并使其意外泄漏，仅仅是令人担忧的原因之一。","source":"（2019年真题·阅读理解·Passage Two）","speechText":"The creation and accidental release of extremely poisonous microbes, however, is only one cause for alarm.","annotations":[],"targetForms":[],"audio":"audio/course-examples/99d383a2ffeddd309ac9846e.mp3"},{"text":"Adopting healthy everyday habits means your body is in better condition to fight off potential attacks（attack的复数形式） by germs and combat an illness more effectively if you do get sick.","translation":"养成健康的生活习惯，意味着你的身体更有能力抵御病菌的攻击，并在生病时更有效地对抗疾病。","source":"（2015年配套材料·选句填空）","speechText":"Adopting healthy everyday habits means your body is in better condition to fight off potential attacks by germs and combat an illness more effectively if you do get sick.","annotations":[{"text":"（attack的复数形式）","start":102,"end":115,"anchor":"attacks"}],"targetForms":["attacks"],"audio":"audio/course-examples/8305eff3ea6438f965d1597a.mp3"},{"text":"Nobody will think what you say is foolish.","translation":"没有人会认为你说的话是愚蠢的。","source":"（2017年真题·阅读理解·Passage Two）","speechText":"Nobody will think what you say is foolish.","annotations":[],"targetForms":[],"audio":"audio/course-examples/73327aafadb7a430832de20a.mp3"},{"text":"According to Simon Ingram, humpback whales rely on their songs for their survival and recovery.","translation":"根据西蒙·英格拉姆的说法，座头鲸依靠它们的歌声来维持生存并实现恢复。","source":"（2023年阅读 Passage Three）","speechText":"According to Simon Ingram, humpback whales rely on their songs for their survival and recovery.","annotations":[],"targetForms":[],"audio":"audio/course-examples/548f3eb9f2b6543409628bd9.mp3"},{"text":"They speak of what the New York Times calls \"metal-hungry microbes that might be used to mine valuable trace metals from ocean water\".","translation":"他们谈到了《纽约时报》所称的“可能用于从海水中开采有价值的微量金属的嗜金属微生物”。","source":"（2019年真题·阅读理解·Passage Two）","speechText":"They speak of what the New York Times calls \"metal-hungry microbes that might be used to mine valuable trace metals from ocean water\".","annotations":[],"targetForms":[],"audio":"audio/course-examples/85e5e945dd77bce895caba29.mp3"}]},"11":{"vocabulary":[{"word":"spell","ipa":"/spel/","partsOfSpeech":"v.","meaning":"拼写"},{"word":"sofa","ipa":"/ˈsəʊfə/","partsOfSpeech":"n.","meaning":"沙发，长椅"},{"word":"abroad","ipa":"/əˈbrɔːd/","partsOfSpeech":"adv.","meaning":"在国外，到海外，广为流传"},{"word":"belief","ipa":"/bɪˈliːf/","partsOfSpeech":"n.","meaning":"信念，信仰，信任"},{"word":"danger","ipa":"/ˈdeɪndʒə(r)/","partsOfSpeech":"n.","meaning":"危险，危险物，威胁"},{"word":"cover","ipa":"/ˈkʌvə(r)/","partsOfSpeech":"v./n.","meaning":"覆盖，包括，封面，掩蔽处"},{"word":"innovation","ipa":"/ˌɪnəˈveɪʃ(ə)n/","partsOfSpeech":"n.","meaning":"创新，革新，新方法，新事物"},{"word":"ant","ipa":"/ænt/","partsOfSpeech":"n.","meaning":"蚂蚁"},{"word":"distance","ipa":"/ˈdɪstəns/","partsOfSpeech":"n./v.","meaning":"距离，远方，疏远，把...远远甩在后面"},{"word":"species","ipa":"/ˈspiːʃiːz/","partsOfSpeech":"n.","meaning":"物种，种类，类型"},{"word":"earth","ipa":"/ɜːθ/","partsOfSpeech":"n.","meaning":"地球，泥土，大地"},{"word":"implement","ipa":"/ˈɪmplɪment;ˈɪmplɪmənt/","partsOfSpeech":"v./n.","meaning":"实施，执行；工具，器具"},{"word":"dad","ipa":"/dæd/","partsOfSpeech":"n.","meaning":"爸爸"},{"word":"of","ipa":"/ɒv; əv/","partsOfSpeech":"prep.","meaning":"...的，关于，属于"},{"word":"take","ipa":"/teɪk/","partsOfSpeech":"v.","meaning":"拿，取，带，接受，花费"}],"examples":[{"text":"Men did not know how to spell \"week\"","translation":"人们不知道如何拼写 week 这个单词。","source":"（2019年·阅读理解·Passage Three）","speechText":"Men did not know how to spell \"week\"","annotations":[],"targetForms":[],"audio":"audio/course-examples/6be68344adea72d5d56f04a1.mp3"},{"text":"The rooms are almost empty, and the only pieces of furniture are a simple table and folded sofa.","translation":"房间里几乎空无一物，仅有的家具是一张简单的桌子和一张折叠沙发。","source":"（2021年真题·阅读理解·Passage Two）","speechText":"The rooms are almost empty, and the only pieces of furniture are a simple table and folded sofa.","annotations":[],"targetForms":[],"audio":"audio/course-examples/a1d5553871d68bf22004a970.mp3"},{"text":"I will pay a visit to my old friend the minute she comes back from abroad.","translation":"她一从国外回来，我就去看望这位老朋友。","source":"（2018年真题·词汇语法·第34题）","speechText":"I will pay a visit to my old friend the minute she comes back from abroad.","annotations":[],"targetForms":[],"audio":"audio/course-examples/c375e2bd08e73ad1e2980844.mp3"},{"text":"A class is said rather vaguely to consist of a group of persons sharing similar occupations and incomes, and as a consequence similar life-styles and beliefs（belief的复数形式）.","translation":"一个阶级通常被笼统地指为一群拥有相似职业和收入的人，因而也具有相似的生活方式和信念。","source":"（2014年真题·词汇语法·第49题）","speechText":"A class is said rather vaguely to consist of a group of persons sharing similar occupations and incomes, and as a consequence similar life-styles and beliefs.","annotations":[{"text":"（belief的复数形式）","start":157,"end":170,"anchor":"beliefs"}],"targetForms":["beliefs"],"audio":"audio/course-examples/49e1fd8a4b3a6da9a85e66f7.mp3"},{"text":"Ensure that your walking space is safe without the danger of tripping over yourself.","translation":"确保行走区域安全，不会有让自己绊倒的危险。","source":"（2025年真题·阅读理解·Passage Two）","speechText":"Ensure that your walking space is safe without the danger of tripping over yourself.","annotations":[],"targetForms":[],"audio":"audio/course-examples/ca11df74513a87d5fe714bee.mp3"},{"text":"Early cleaning of a garden is often followed by early covering（cover的-ing形式） the soil with mulch.","translation":"花园的清理往往进行得比较早，随后土壤也会很早就被覆盖上一层覆盖物。","source":"（2023年真题·阅读理解·Passage One）","speechText":"Early cleaning of a garden is often followed by early covering the soil with mulch.","annotations":[{"text":"（cover的-ing形式）","start":62,"end":76,"anchor":"covering"}],"targetForms":["covering"],"audio":"audio/course-examples/8abce722febdb56c3391cfba.mp3"},{"text":"Write a letter to apply for membership of the International Cultural Tourism Innovation Team（国际文化旅游创新团队）.","translation":"撰写一封申请加入国际文化旅游创新团队的信件","source":"（2025年·写作）","speechText":"Write a letter to apply for membership of the International Cultural Tourism Innovation Team.","annotations":[{"text":"（国际文化旅游创新团队）","start":92,"end":104,"anchor":"Team"}],"targetForms":[],"audio":"audio/course-examples/c79be8c04bf4a841a996b37c.mp3"},{"text":"From a plane, cars on the highway look like ants（ant的复数形式）.","translation":"从飞机上看，高速公路上的汽车就像蚂蚁一样。","source":"（2025年真题·阅读理解·Passage Three）","speechText":"From a plane, cars on the highway look like ants.","annotations":[{"text":"（ant的复数形式）","start":48,"end":58,"anchor":"ants"}],"targetForms":["ants"],"audio":"audio/course-examples/1db156fbd01852c76cc257c3.mp3"},{"text":"It’s also important to keep a distance from others to help prevent the spread of your illness.","translation":"与他人保持一定距离也很重要，这有助于防止把自己的疾病传染给别人。","source":"（2015年配套材料·选句填空·完整句选项）","speechText":"It’s also important to keep a distance from others to help prevent the spread of your illness.","annotations":[],"targetForms":[],"audio":"audio/course-examples/4b93c57028ca712485d1761f.mp3"},{"text":"It is estimated that as many as 2,000 species of mammals and birds will become extinct in the next 100 years.","translation":"据估计，在未来一百年内，多达两千种哺乳动物和鸟类将会灭绝。","source":"（2015年配套材料·英译汉）","speechText":"It is estimated that as many as 2,000 species of mammals and birds will become extinct in the next 100 years.","annotations":[],"targetForms":[],"audio":"audio/course-examples/b3969dc18b721b7c5cca0711.mp3"},{"text":"But surprisingly, some of the driest places on Earth lie right beside the ocean.","translation":"但令人惊讶的是，地球上一些最干旱的地方就位于海洋旁边。","source":"（2026年真题·阅读理解·Passage Three）","speechText":"But surprisingly, some of the driest places on Earth lie right beside the ocean.","annotations":[],"targetForms":[],"audio":"audio/course-examples/3cd8338306fe186bd8f1d45d.mp3"},{"text":"By implementing（implement的-ing形式） these strategies, we can boost our health in cold weather.","translation":"通过实施这些方法，我们能在寒冷天气里改善健康状况。","source":"（2025年真题·选句填空）","speechText":"By implementing these strategies, we can boost our health in cold weather.","annotations":[{"text":"（implement的-ing形式）","start":15,"end":33,"anchor":"implementing"}],"targetForms":["implementing"],"audio":"audio/course-examples/15eb3937ce08d24c7f22c681.mp3"},{"text":"Before you go “yuck”, it can be anyone — your mum or dad, grandparents or friend.","translation":"在你脱口说出“真恶心”之前，要知道，对方可以是任何人——你的爸爸妈妈、祖父母或朋友。","source":"（2018年配套材料·选句填空）","speechText":"Before you go “yuck”, it can be anyone — your mum or dad, grandparents or friend.","annotations":[],"targetForms":[],"audio":"audio/course-examples/276d2e0ff48490c48e0cf37c.mp3"},{"text":"It also shows a new image of Chinese brands in the world.","translation":"这也展现了中国品牌在世界上的新形象。","source":"（2026年真题·翻译）","speechText":"It also shows a new image of Chinese brands in the world.","annotations":[],"targetForms":[],"audio":"audio/course-examples/aa0e6e301c1ece87cc9719e8.mp3"},{"text":"Offer to do something, finish a project or take the kids to their piano lessons.","translation":"主动提出做点什么、完成一个项目，或者送孩子们去上钢琴课。","source":"（2019年真题·阅读理解·Passage One）","speechText":"Offer to do something, finish a project or take the kids to their piano lessons.","annotations":[],"targetForms":[],"audio":"audio/course-examples/89ff5e18cd6acb5c93cd43b7.mp3"}]},"12":{"vocabulary":[{"word":"become","ipa":"/bɪˈkʌm/","partsOfSpeech":"v.","meaning":"变成，成为，变得"},{"word":"school","ipa":"/skuːl/","partsOfSpeech":"n./v.","meaning":"学校，学院，学派，教育"},{"word":"early","ipa":"/ˈɜːli/","partsOfSpeech":"adj./adv.","meaning":"早的，早期的，早，提早"},{"word":"hard","ipa":"/hɑːd/","partsOfSpeech":"adj./adv.","meaning":"坚硬的，困难的，努力地，猛烈地"},{"word":"found","ipa":"/faʊnd/","partsOfSpeech":"v.","meaning":"建立，创立"},{"word":"behind","ipa":"/bɪˈhaɪnd/","partsOfSpeech":"prep./adv.","meaning":"在...后面，落后于，在背后"},{"word":"kind","ipa":"/kaɪnd/","partsOfSpeech":"adj./n.","meaning":"仁慈的，和蔼的，种类，性质"},{"word":"discover","ipa":"/dɪˈskʌvə(r)/","partsOfSpeech":"v.","meaning":"发现，发觉，了解到，认识"},{"word":"necessary","ipa":"/ˈnesəsəri/","partsOfSpeech":"adj./n.","meaning":"必要的，必需的，必然的，必需品"},{"word":"soon","ipa":"/suːn/","partsOfSpeech":"adv.","meaning":"不久，很快，早"},{"word":"opponent","ipa":"/əˈpəʊnənt/","partsOfSpeech":"n./adj.","meaning":"对手，敌手，反对者，对立的"},{"word":"meet","ipa":"/miːt/","partsOfSpeech":"v./n.","meaning":"遇见，会面，满足，运动会"},{"word":"remind","ipa":"/rɪˈmaɪnd/","partsOfSpeech":"v.","meaning":"提醒，使想起"},{"word":"third","ipa":"/θɜːd/","partsOfSpeech":"num./n.","meaning":"第三，三分之一"},{"word":"perhaps","ipa":"/pəˈhæps/","partsOfSpeech":"adv.","meaning":"也许，可能，大概"}],"examples":[{"text":"If they prove themselves able, they could become guide dogs.","translation":"如果它们证明自己能够胜任，就有可能成为导盲犬。","source":"（2022年真题·阅读理解·Passage Two）","speechText":"If they prove themselves able, they could become guide dogs.","annotations":[],"targetForms":[],"audio":"audio/course-examples/08fc7231b881fc32e18775a5.mp3"},{"text":"You’ll be late for school again!","translation":"你上学又要迟到了！","source":"（2018年真题·阅读理解·Passage Two）","speechText":"You’ll be late for school again!","annotations":[],"targetForms":[],"audio":"audio/course-examples/20ab96d55dd2ce8a6a116903.mp3"},{"text":"In early spring, those insects are still sleeping.","translation":"早春时节，那些昆虫还在休眠。","source":"（2023年真题·阅读理解·Passage One）","speechText":"In early spring, those insects are still sleeping.","annotations":[],"targetForms":[],"audio":"audio/course-examples/7ba20212fcb894e321f52f68.mp3"},{"text":"To do this, you must become a hard working person that the employees can follow.","translation":"要做到这一点，你必须成为一个勤奋工作、值得员工效仿的人。","source":"（2023年真题·选句填空）","speechText":"To do this, you must become a hard working person that the employees can follow.","annotations":[],"targetForms":[],"audio":"audio/course-examples/ac74f8ba423a745020bda4c5.mp3"},{"text":"Sometimes, their collections become museums or libraries, for example, Henry Huntington, who founded（found的过去式） a library in Los Angeles to house his collection of books.","translation":"有时，他们的收藏会变成博物馆或图书馆，例如亨利·亨廷顿，他在洛杉矶创办了一座图书馆，用来存放他的藏书。","source":"（2022年·阅读理解·Passage One）","speechText":"Sometimes, their collections become museums or libraries, for example, Henry Huntington, who founded a library in Los Angeles to house his collection of books.","annotations":[{"text":"（found的过去式）","start":100,"end":111,"anchor":"founded"}],"targetForms":["founded"],"audio":"audio/course-examples/d1de891d618a22b2c767e634.mp3"},{"text":"The little girl jumped from behind the door to welcome her father.","translation":"小女孩从门后跳出来，迎接她的父亲。","source":"（2017年真题·词汇语法·第37题）","speechText":"The little girl jumped from behind the door to welcome her father.","annotations":[],"targetForms":[],"audio":"audio/course-examples/bd1880aa161e5778eba45aa2.mp3"},{"text":"We all experience some kind of anger in our life.","translation":"我们在生活中都会经历某种形式的愤怒。","source":"（2021年真题·选句填空）","speechText":"We all experience some kind of anger in our life.","annotations":[],"targetForms":[],"audio":"audio/course-examples/23743399c2b4c2f40a590f2f.mp3"},{"text":"Scientists have discovered（discover的过去分词形式） that exercise can decrease depression, lower anxiety and help us sleep.","translation":"科学家发现，运动能够减轻抑郁、降低焦虑，并帮助我们入睡。","source":"（2020年真题·翻译）","speechText":"Scientists have discovered that exercise can decrease depression, lower anxiety and help us sleep.","annotations":[{"text":"（discover的过去分词形式）","start":26,"end":43,"anchor":"discovered"}],"targetForms":["discovered"],"audio":"audio/course-examples/660debe4c73bec1658688153.mp3"},{"text":"Big gifts or heavy favors are rarely necessary.","translation":"大礼物或丰厚的馈赠很少是必要的。","source":"（2026年真题·阅读理解·Passage One）","speechText":"Big gifts or heavy favors are rarely necessary.","annotations":[],"targetForms":[],"audio":"audio/course-examples/a0665a7c2addceae4669b101.mp3"},{"text":"But she also knows that will not happen anytime soon.","translation":"但她也知道，这件事近期不会发生。","source":"（2024年真题·阅读理解·Passage Two）","speechText":"But she also knows that will not happen anytime soon.","annotations":[],"targetForms":[],"audio":"audio/course-examples/7f4b9d11536343552114fec4.mp3"},{"text":"You have to size up your opponent.","translation":"你必须仔细判断对手的情况。","source":"（2021年真题·阅读理解·Passage One）","speechText":"You have to size up your opponent.","annotations":[],"targetForms":[],"audio":"audio/course-examples/9a4958816973592ebe9e772b.mp3"},{"text":"When I first met（meet的过去式） Nina, I disliked her at once.","translation":"我第一次见到Nina时，就立刻不喜欢她。","source":"（2017年真题·阅读理解·Passage Three）","speechText":"When I first met Nina, I disliked her at once.","annotations":[{"text":"（meet的过去式）","start":16,"end":26,"anchor":"met"}],"targetForms":["met"],"audio":"audio/course-examples/466c54259f84570831b492cc.mp3"},{"text":"When Ben is hungry, he will remind his family to feed him.","translation":"Ben饿了的时候，会提醒家人给它喂食。","source":"（2025年真题·阅读理解·Passage One·阅读题补全）","speechText":"When Ben is hungry, he will remind his family to feed him.","annotations":[],"targetForms":[],"audio":"audio/course-examples/b37d322030ea9801c2910f6b.mp3"},{"text":"According to the Centers for Disease Control and Prevention, more than a third of Americans do not achieve the recommended seven to nine hours of sleep per night.","translation":"根据美国疾病控制与预防中心的数据，超过三分之一的美国人每晚睡眠达不到建议的七至九小时。","source":"（2024年真题·阅读理解·Passage Three）","speechText":"According to the Centers for Disease Control and Prevention, more than a third of Americans do not achieve the recommended seven to nine hours of sleep per night.","annotations":[],"targetForms":[],"audio":"audio/course-examples/92181ef755839a02deb01a38.mp3"},{"text":"He said perhaps the human body can even power the phones.","translation":"他说，也许人体甚至能够给手机供电。","source":"（2023年真题·阅读理解·Passage Two）","speechText":"He said perhaps the human body can even power the phones.","annotations":[],"targetForms":[],"audio":"audio/course-examples/09aa82a479165a3bfbde9d80.mp3"}]},"13":{"vocabulary":[{"word":"warn","ipa":"/wɔːn/","partsOfSpeech":"v.","meaning":"警告，告诫，提醒"},{"word":"qualify","ipa":"/ˈkwɒlɪfaɪ/","partsOfSpeech":"v.","meaning":"取得资格，使合格，限定"},{"word":"newspaper","ipa":"/ˈnjuːzpeɪpə(r)/","partsOfSpeech":"n.","meaning":"报纸，报社"},{"word":"finish","ipa":"/ˈfɪnɪʃ/","partsOfSpeech":"v./n.","meaning":"完成，结束，毁灭，结尾"},{"word":"half","ipa":"/hɑːf/","partsOfSpeech":"n./adj./adv.","meaning":"一半，半个，半，一半地"},{"word":"truth","ipa":"/truːθ/","partsOfSpeech":"n.","meaning":"真理，真相，真实，事实"},{"word":"sake","ipa":"/seɪk/","partsOfSpeech":"n.","meaning":"缘故，理由，目的，利益"},{"word":"again","ipa":"/əˈɡen/","partsOfSpeech":"adv.","meaning":"又，再次，此外"},{"word":"audience","ipa":"/ˈɔːdiəns/","partsOfSpeech":"n.","meaning":"观众，听众，读者"},{"word":"pin","ipa":"/pɪn/","partsOfSpeech":"n./v.","meaning":"别针，大头针，固定"},{"word":"track","ipa":"/træk/","partsOfSpeech":"n./v.","meaning":"轨道，踪迹，小道，追踪"},{"word":"therefore","ipa":"/ˈðeəfɔː(r)/","partsOfSpeech":"adv.","meaning":"因此，所以"},{"word":"sock","ipa":"/sɒk/","partsOfSpeech":"n./v.","meaning":"袜子，短袜，重击"},{"word":"absorb","ipa":"/əbˈzɔːb/","partsOfSpeech":"v.","meaning":"吸收，吸引，承受，理解"},{"word":"bathroom","ipa":"/ˈbɑːθruːm; ˈbɑːθrʊm/","partsOfSpeech":"n.","meaning":"浴室，洗手间，厕所"}],"examples":[{"text":"But garden experts warn — not too fast.","translation":"但园艺专家提醒说：别急着动手。","source":"（2023年真题·阅读理解·Passage One）","speechText":"But garden experts warn — not too fast.","annotations":[],"targetForms":[],"audio":"audio/course-examples/4cc6fb95a81cb2d891fd060f.mp3"},{"text":"For one thing, more than half of the people in the United States are not qualified（qualify的过去分词形式） to work.","translation":"一方面，美国有一半以上的人不具备工作的资格。","source":"（2016年真题·阅读理解·Passage Three）","speechText":"For one thing, more than half of the people in the United States are not qualified to work.","annotations":[{"text":"（qualify的过去分词形式）","start":82,"end":98,"anchor":"qualified"}],"targetForms":["qualified"],"audio":"audio/course-examples/9a6ecc12461d29083000f936.mp3"},{"text":"By 1950 it had been taught to one and a half million people, and more than one hundred newspapers（newspaper的复数形式） and magazines in the language are published regularly throughout the world.","translation":"到1950年，已有150万人学习过这门语言，全球有超过一百种报纸和杂志定期出版。","source":"（2014年真题·阅读理解·Passage Two）","speechText":"By 1950 it had been taught to one and a half million people, and more than one hundred newspapers and magazines in the language are published regularly throughout the world.","annotations":[{"text":"（newspaper的复数形式）","start":97,"end":113,"anchor":"newspapers"}],"targetForms":["newspapers"],"audio":"audio/course-examples/70888131e6b4d34a7a233769.mp3"},{"text":"Offer to do something, finish a project or take the kids to their piano lessons.","translation":"主动提出做点什么、完成一个项目，或者送孩子们去上钢琴课。","source":"（2019年真题·阅读理解·Passage One）","speechText":"Offer to do something, finish a project or take the kids to their piano lessons.","annotations":[],"targetForms":[],"audio":"audio/course-examples/89ff5e18cd6acb5c93cd43b7.mp3"},{"text":"Spend half of your time talking and the other half listening.","translation":"把一半时间用于说话，另一半时间用于倾听。","source":"（2016年配套材料·选词填空）","speechText":"Spend half of your time talking and the other half listening.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e169e7a775fdf85ff0266c88.mp3"},{"text":"Only years later did I learn the truth about the matter.","translation":"直到多年以后，我才知道这件事的真相。","source":"（2016年真题·词汇语法·第41题）","speechText":"Only years later did I learn the truth about the matter.","annotations":[],"targetForms":[],"audio":"audio/course-examples/bcb1c4104a60d53d80918c1d.mp3"},{"text":"The couple have tried hard to save their troubled marriage for the sake of their children.","translation":"这对夫妻为了孩子，一直努力挽救陷入困境的婚姻。","source":"（2014年真题·词汇语法·第50题）","speechText":"The couple have tried hard to save their troubled marriage for the sake of their children.","annotations":[],"targetForms":[],"audio":"audio/course-examples/17ae837fc65bc73283753b16.mp3"},{"text":"You’ll be late for school again!","translation":"你上学又要迟到了！","source":"（2018年真题·阅读理解·Passage Two）","speechText":"You’ll be late for school again!","annotations":[],"targetForms":[],"audio":"audio/course-examples/20ab96d55dd2ce8a6a116903.mp3"},{"text":"An influencer is a person who can influence the decisions of followers because of the relationship with the audience and his or her knowledge in a particular area.","translation":"网络影响者是指这样的人：凭借与受众的关系以及在某一领域的知识，能够影响关注者的决定。","source":"（2020年真题·阅读理解·Passage Two）","speechText":"An influencer is a person who can influence the decisions of followers because of the relationship with the audience and his or her knowledge in a particular area.","annotations":[],"targetForms":[],"audio":"audio/course-examples/fb31f8c5fd897706fb3a0827.mp3"},{"text":"Pinned（pin的过去分词形式） to their drawing boards are blueprints for improved quake-resistant buildings.","translation":"被钉在他们绘图板上的是改进型抗震建筑的设计蓝图","source":"（2014年真题·阅读理解·Passage Three）","speechText":"Pinned to their drawing boards are blueprints for improved quake-resistant buildings.","annotations":[{"text":"（pin的过去分词形式）","start":6,"end":18,"anchor":"Pinned"}],"targetForms":["Pinned"],"audio":"audio/course-examples/f17e7050b7a28f484102fe6a.mp3"},{"text":"They tracked（track的过去式） kids' physical activities by using monitors that measured things like how fast, long and intensely they moved.","translation":"他们通过使用监测器来追踪孩子们的身体活动，这些监测器测量诸如他们移动得有多快、持续了多长时间以及活动得有多剧烈等数据。","source":"（2024年真题·完形填空）","speechText":"They tracked kids' physical activities by using monitors that measured things like how fast, long and intensely they moved.","annotations":[{"text":"（track的过去式）","start":12,"end":23,"anchor":"tracked"}],"targetForms":["tracked"],"audio":"audio/course-examples/cfa7a31bb38467cc0becc207.mp3"},{"text":"Therefore, when they look for jobs, they have few skills that they can offer.","translation":"因此，他们找工作时，几乎没有什么拿得出手的技能。","source":"（2016年真题·阅读理解·Passage Three）","speechText":"Therefore, when they look for jobs, they have few skills that they can offer.","annotations":[],"targetForms":[],"audio":"audio/course-examples/041eb699ad913b6f721787fe.mp3"},{"text":"She was wearing skintight pedal pushers, a flashy, floppy top, and sneakers with no socks（sock的复数形式） bizarrely inappropriate even at our very informal company.","translation":"她穿着紧身七分裤和花哨宽松的上衣，还没穿袜子就套上了运动鞋；即使在我们这家很不拘礼节的公司，这样的穿着也显得十分不得体。","source":"（2017年真题·阅读理解·Passage Three）","speechText":"She was wearing skintight pedal pushers, a flashy, floppy top, and sneakers with no socks bizarrely inappropriate even at our very informal company.","annotations":[{"text":"（sock的复数形式）","start":89,"end":100,"anchor":"socks"}],"targetForms":["socks"],"audio":"audio/course-examples/82794322d7ee45f7c3eeacc1.mp3"},{"text":"And it is true that the sea has a great capacity for absorbing（absorb的-ing形式） organic wastes.","translation":"而且，海洋确实具有很强的吸收有机废弃物的能力。","source":"（2015年配套材料·选词填空）","speechText":"And it is true that the sea has a great capacity for absorbing organic wastes.","annotations":[{"text":"（absorb的-ing形式）","start":62,"end":77,"anchor":"absorbing"}],"targetForms":["absorbing"],"audio":"audio/course-examples/0c10e581998af37f3cd1cd8e.mp3"},{"text":"It didn’t even matter that it was cold and had no bathroom.","translation":"甚至连住处寒冷、没有浴室也无所谓。","source":"（2015年真题·阅读理解·Passage One）","speechText":"It didn’t even matter that it was cold and had no bathroom.","annotations":[],"targetForms":[],"audio":"audio/course-examples/3c991ff7935bfe1e877917d5.mp3"}]},"14":{"vocabulary":[{"word":"dark","ipa":"/dɑːk/","partsOfSpeech":"adj./n.","meaning":"黑暗的，深色的，暗处"},{"word":"courage","ipa":"/ˈkʌrɪdʒ/","partsOfSpeech":"n.","meaning":"勇气，胆量，魄力"},{"word":"age","ipa":"/eɪdʒ/","partsOfSpeech":"n./v.","meaning":"年龄，时代，衰老，变老"},{"word":"serious","ipa":"/ˈsɪəriəs/","partsOfSpeech":"adj.","meaning":"严肃的，严重的，认真的，危险的"},{"word":"fashion","ipa":"/ˈfæʃ(ə)n/","partsOfSpeech":"n./v.","meaning":"时尚，流行，方式，塑造"},{"word":"quit","ipa":"/kwɪt/","partsOfSpeech":"v.","meaning":"离开，辞职，停止，放弃"},{"word":"dry","ipa":"/draɪ/","partsOfSpeech":"adj./v.","meaning":"干的，干燥的，变干"},{"word":"year","ipa":"/jɪə(r)/","partsOfSpeech":"n.","meaning":"年，年份，学年"},{"word":"collect","ipa":"/kəˈlekt/","partsOfSpeech":"v.","meaning":"收集，采集，领取"},{"word":"influence","ipa":"/ˈɪnfluəns/","partsOfSpeech":"n./v.","meaning":"影响，作用，影响力，感染"},{"word":"game","ipa":"/ɡeɪm/","partsOfSpeech":"n.","meaning":"游戏，比赛，运动"},{"word":"grow","ipa":"/ɡrəʊ/","partsOfSpeech":"v.","meaning":"生长，种植，变得，发展"},{"word":"food","ipa":"/fuːd/","partsOfSpeech":"n.","meaning":"食物，食品，粮食，养料"},{"word":"back","ipa":"/bæk/","partsOfSpeech":"n./adv./v.","meaning":"背部；后面的；后退，支持"},{"word":"lack","ipa":"/læk/","partsOfSpeech":"n./v.","meaning":"缺乏，不足"}],"examples":[{"text":"You have no business entering that office building after dark.","translation":"天黑后，你无权进入那栋办公楼。","source":"（2013年真题·词汇语法·第21题）","speechText":"You have no business entering that office building after dark.","annotations":[],"targetForms":[],"audio":"audio/course-examples/0d5c7b9e94e31f10e29100fc.mp3"},{"text":"Patience also gives you strength and courage to face any situation.","translation":"耐心还会给你力量和勇气，让你面对任何情况。","source":"（2021年真题·选句填空）","speechText":"Patience also gives you strength and courage to face any situation.","annotations":[],"targetForms":[],"audio":"audio/course-examples/8b4c716a5b1e8db1e2a12f82.mp3"},{"text":"Chloe, aged（age的过去分词形式） 15, even sleeps with her phone.","translation":"十五岁的Chloe甚至连睡觉都带着手机。","source":"（2021年真题·阅读理解·Passage Three）","speechText":"Chloe, aged 15, even sleeps with her phone.","annotations":[{"text":"（age的过去分词形式）","start":11,"end":23,"anchor":"aged"}],"targetForms":["aged"],"audio":"audio/course-examples/7f9ffc733000980c13b81fa7.mp3"},{"text":"As all serious rock, paper, scissors players know, there’s more to the game than luck.","translation":"正如所有认真对待石头、剪刀、布游戏的玩家都知道的那样，这个游戏不仅仅取决于运气。","source":"（2021年真题·阅读理解·Passage One）","speechText":"As all serious rock, paper, scissors players know, there’s more to the game than luck.","annotations":[],"targetForms":[],"audio":"audio/course-examples/83166e39b544f48e4be349ac.mp3"},{"text":"She tries her best to keep up with the changes in fashion.","translation":"她尽最大努力跟上时尚的变化。","source":"（2015年真题·词汇语法·第21题）","speechText":"She tries her best to keep up with the changes in fashion.","annotations":[],"targetForms":[],"audio":"audio/course-examples/1498e68ff6fc88876adc8231.mp3"},{"text":"Although quitting（quit的-ing形式） drinking can be difficult, you will never be sorry if you make this decision.","translation":"虽然戒酒可能很难，但只要作出这个决定，你绝不会后悔。","source":"（2022年真题·选句填空）","speechText":"Although quitting drinking can be difficult, you will never be sorry if you make this decision.","annotations":[{"text":"（quit的-ing形式）","start":17,"end":30,"anchor":"quitting"}],"targetForms":["quitting"],"audio":"audio/course-examples/e8174a3aba6f38104147c37b.mp3"},{"text":"But surprisingly, some of the driest（dry的最高级） places on Earth lie right beside the ocean.","translation":"但令人惊讶的是，地球上一些最干旱的地方就位于海洋旁边。","source":"（2026年真题·阅读理解·Passage Three）","speechText":"But surprisingly, some of the driest places on Earth lie right beside the ocean.","annotations":[{"text":"（dry的最高级）","start":36,"end":45,"anchor":"driest"}],"targetForms":["driest"],"audio":"audio/course-examples/3cd8338306fe186bd8f1d45d.mp3"},{"text":"I had dreamed about it for years（year的复数形式）.","translation":"多年来，我一直梦想着这件事。","source":"（2015年真题·阅读理解·Passage One）","speechText":"I had dreamed about it for years.","annotations":[{"text":"（year的复数形式）","start":32,"end":43,"anchor":"years"}],"targetForms":["years"],"audio":"audio/course-examples/3272e1d62f6f9e202e21711e.mp3"},{"text":"Nowadays, we still have a collecting（collect的-ing形式） instinct.","translation":"如今，我们仍然保留着收藏的本能。","source":"（2022年真题·阅读理解·Passage One）","speechText":"Nowadays, we still have a collecting instinct.","annotations":[{"text":"（collect的-ing形式）","start":36,"end":52,"anchor":"collecting"}],"targetForms":["collecting"],"audio":"audio/course-examples/6ef4757debd6135d842f403e.mp3"},{"text":"His wife had a great influence on Twain's later books.","translation":"他的妻子对吐温后来的作品产生了很大影响。","source":"（2013年真题·阅读理解·Passage Three）","speechText":"His wife had a great influence on Twain's later books.","annotations":[],"targetForms":[],"audio":"audio/course-examples/45e8647ad3978a4ea6ef5047.mp3"},{"text":"Many people think the game is all luck.","translation":"许多人认为，这个游戏全靠运气。","source":"（2021年真题·阅读理解·Passage One）","speechText":"Many people think the game is all luck.","annotations":[],"targetForms":[],"audio":"audio/course-examples/3c1cf495f61ecec5e89776cd.mp3"},{"text":"Its popularity in the United States continues to grow.","translation":"它在美国的受欢迎程度继续增长。","source":"（2023年真题·完形填空）","speechText":"Its popularity in the United States continues to grow.","annotations":[],"targetForms":[],"audio":"audio/course-examples/100728481f202896a3e50d12.mp3"},{"text":"Convenience foods（food的复数形式） from the supermarket simplify shopping and cooking.","translation":"超市里的方便食品让购物和做饭变得更简单。","source":"（2013年真题·阅读理解·Passage Two）","speechText":"Convenience foods from the supermarket simplify shopping and cooking.","annotations":[{"text":"（food的复数形式）","start":17,"end":28,"anchor":"foods"}],"targetForms":["foods"],"audio":"audio/course-examples/aea20befe427385288175099.mp3"},{"text":"It is time for students to go back to school.","translation":"到了学生们回学校的时候了。","source":"（2020年真题·作文）","speechText":"It is time for students to go back to school.","annotations":[],"targetForms":[],"audio":"audio/course-examples/b235673ab1a4790180a8991c.mp3"},{"text":"The only thing now standing in the way of further progress is lack of money.","translation":"目前唯一阻碍进一步进展的是资金不足。","source":"（2017年真题·词汇语法·第42题）","speechText":"The only thing now standing in the way of further progress is lack of money.","annotations":[],"targetForms":[],"audio":"audio/course-examples/c014e0feb26831f0d0f1cdd5.mp3"}]},"15":{"vocabulary":[{"word":"noise","ipa":"/nɔɪz/","partsOfSpeech":"n.","meaning":"噪音，喧闹声，嘈杂声，声音"},{"word":"sport","ipa":"/spɔːt/","partsOfSpeech":"n./v.","meaning":"运动，体育，游戏"},{"word":"means","ipa":"/miːnz/","partsOfSpeech":"n.","meaning":"方法，手段"},{"word":"respect","ipa":"/rɪˈspekt/","partsOfSpeech":"n./v.","meaning":"尊重，尊敬，方面"},{"word":"team","ipa":"/tiːm/","partsOfSpeech":"n./v.","meaning":"队伍，团队，组，合作"},{"word":"picnic","ipa":"/ˈpɪknɪk/","partsOfSpeech":"n./v.","meaning":"野餐，去野餐"},{"word":"wake","ipa":"/weɪk/","partsOfSpeech":"v.","meaning":"醒来，唤醒，唤起"},{"word":"project","ipa":"/ˈprɒdʒekt; prəˈdʒekt/","partsOfSpeech":"n./v.","meaning":"项目，工程，计划；预计，推算"},{"word":"neither","ipa":"/ˈnaɪðə(r)/","partsOfSpeech":"pron./conj.","meaning":"两者都不，既不，也不"},{"word":"disturb","ipa":"/dɪˈstɜːb/","partsOfSpeech":"v.","meaning":"打扰，妨碍，使不安，弄乱"},{"word":"grammar","ipa":"/ˈɡræmə(r)/","partsOfSpeech":"n.","meaning":"语法，语法书"},{"word":"transfer","ipa":"/trænsˈfɜː(r)/","partsOfSpeech":"v.","meaning":"转移，调动，转让"},{"word":"web","ipa":"/web/","partsOfSpeech":"n.","meaning":"网，网络，蜘蛛网"},{"word":"advantage","ipa":"/ədˈvɑːntɪdʒ/","partsOfSpeech":"n.","meaning":"优势，有利条件，利益，好处"},{"word":"authority","ipa":"/ɔːˈθɒrəti/","partsOfSpeech":"n.","meaning":"权威，权力，官方，当局，权威机构"}],"examples":[{"text":"Dunlop explained the singing noises（noise的复数形式） might bring in other possible mates.","translation":"Dunlop解释说，这些歌声可能会吸引其他潜在的配偶。","source":"（2023年真题·阅读理解·Passage Three）","speechText":"Dunlop explained the singing noises might bring in other possible mates.","annotations":[{"text":"（noise的复数形式）","start":35,"end":47,"anchor":"noises"}],"targetForms":["noises"],"audio":"audio/course-examples/b15829a6110f49b531594209.mp3"},{"text":"You can watch your favorite movie or sports（sport的复数形式） match.","translation":"你可以看自己最喜欢的电影或体育比赛。","source":"（2021年真题·选句填空）","speechText":"You can watch your favorite movie or sports match.","annotations":[{"text":"（sport的复数形式）","start":43,"end":55,"anchor":"sports"}],"targetForms":["sports"],"audio":"audio/course-examples/b1a84dcb8918e29823cc1d05.mp3"},{"text":"More education means more active mind in old age.","translation":"更多教育意味着老年时思维更活跃。","source":"（2022年真题·选句填空）","speechText":"More education means more active mind in old age.","annotations":[],"targetForms":[],"audio":"audio/course-examples/33f337411ebb2be412e8b142.mp3"},{"text":"In all outward respects（respect的复数形式）, her life appeared to be rather boring.","translation":"从一切外在方面来看，她的生活似乎相当平淡。","source":"（2015年真题·阅读理解·Passage Three）","speechText":"In all outward respects, her life appeared to be rather boring.","annotations":[{"text":"（respect的复数形式）","start":23,"end":37,"anchor":"respects"}],"targetForms":["respects"],"audio":"audio/course-examples/c35e11b2d63ac1eadcb8aa67.mp3"},{"text":"Employers then get opinions from the team members.","translation":"然后，雇主会听取团队成员的意见。","source":"（2020年真题·阅读理解·Passage One）","speechText":"Employers then get opinions from the team members.","annotations":[],"targetForms":[],"audio":"audio/course-examples/9f70dbc183f0731d99ec3ff4.mp3"},{"text":"Let's go on a picnic this weekend, shall we?","translation":"我们这周末去野餐，好吗？","source":"（2016年真题·词汇语法·第38题）","speechText":"Let's go on a picnic this weekend, shall we?","annotations":[],"targetForms":[],"audio":"audio/course-examples/d940426b3d7d79099ad0ec94.mp3"},{"text":"That is when sleeping insects “wake up”.","translation":"那时，休眠中的昆虫才会“醒来”。","source":"（2023年真题·阅读理解·Passage One）","speechText":"That is when sleeping insects “wake up”.","annotations":[],"targetForms":[],"audio":"audio/course-examples/f9f30b719b708ae8b3204d60.mp3"},{"text":"Offer to do something, finish a project or take the kids to their piano lessons.","translation":"提出帮忙做某事、完成一个项目，或者带孩子去上钢琴课。","source":"（2019年真题·阅读理解·Passage One）","speechText":"Offer to do something, finish a project or take the kids to their piano lessons.","annotations":[],"targetForms":[],"audio":"audio/course-examples/89ff5e18cd6acb5c93cd43b7.mp3"},{"text":"A person with a flat, dull voice which neither rises nor falls sounds like a flat and dull person!","translation":"一个人如果说话声音平淡、沉闷，没有高低起伏，听起来就像是一个平淡无趣的人！","source":"（2018年真题·阅读理解·Passage Three）","speechText":"A person with a flat, dull voice which neither rises nor falls sounds like a flat and dull person!","annotations":[],"targetForms":[],"audio":"audio/course-examples/ca75529d7421b53d50c9061c.mp3"},{"text":"When I am having a nap at noon, I hate being disturbed（disturb的过去分词形式） by other people.","translation":"我中午午睡时，讨厌被别人打扰。","source":"（2018年真题·词汇语法·第25题）","speechText":"When I am having a nap at noon, I hate being disturbed by other people.","annotations":[{"text":"（disturb的过去分词形式）","start":54,"end":70,"anchor":"disturbed"}],"targetForms":["disturbed"],"audio":"audio/course-examples/9ef29c7b76436322b41b0c24.mp3"},{"text":"When we were in high school, we learnt the basics of English grammar.","translation":"我们上高中时，学过英语语法的基础知识。","source":"（2018年真题·词汇语法·第30题）","speechText":"When we were in high school, we learnt the basics of English grammar.","annotations":[],"targetForms":[],"audio":"audio/course-examples/feeaedf20dd2bd3f234ec812.mp3"},{"text":"Now money is being transferred（transfer的过去分词形式） through some kind of cyberspace, which is really abstract and hard for anyone to understand.","translation":"如今，钱通过某种网络空间进行转移，这种方式十分抽象，对任何人来说都不容易理解。","source":"（2020年真题·阅读理解·Passage Three）","speechText":"Now money is being transferred through some kind of cyberspace, which is really abstract and hard for anyone to understand.","annotations":[{"text":"（transfer的过去分词形式）","start":30,"end":47,"anchor":"transferred"}],"targetForms":["transferred"],"audio":"audio/course-examples/1586c26103eb985e7b22c5c1.mp3"},{"text":"Although many Web pages can teach kids useful things, there are some other sites waiting to tempt young people who are immature and easily affected.","translation":"虽然很多网页能教给孩子有用的东西，但也有其他一些网站伺机诱惑那些尚不成熟、容易受影响的年轻人。","source":"（2017年真题·阅读理解·Passage One）","speechText":"Although many Web pages can teach kids useful things, there are some other sites waiting to tempt young people who are immature and easily affected.","annotations":[],"targetForms":[],"audio":"audio/course-examples/0b93f5a6a67a2363b32f2db8.mp3"},{"text":"Thoughtful parents would combine supervision with communication, which is the best way to take advantage of the Internet as a resource while protecting their children.","translation":"有心的家长会把监督与沟通结合起来；这样既能把互联网作为资源充分利用，又能保护孩子。","source":"（2017年真题·阅读理解·Passage One）","speechText":"Thoughtful parents would combine supervision with communication, which is the best way to take advantage of the Internet as a resource while protecting their children.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e07ecb8857c9a0211232de1c.mp3"},{"text":"One paper looking into the ideal amount of sleep found that “Sleep duration recommendations issued by public health authorities（authority的复数形式） help to inform the population of interventions, policies, and healthy sleep behaviors.”","translation":"一项关于理想睡眠时长的研究发现：“公共卫生机构发布的睡眠时长建议有助于向公众传达干预措施、政策以及健康睡眠行为的信息。”","source":"（2024年真题·阅读理解·Passage Three）","speechText":"One paper looking into the ideal amount of sleep found that “Sleep duration recommendations issued by public health authorities help to inform the population of interventions, policies, and healthy sleep behaviors.”","annotations":[{"text":"（authority的复数形式）","start":127,"end":143,"anchor":"authorities"}],"targetForms":["authorities"],"audio":"audio/course-examples/0284cfa20eecf1fdf4983448.mp3"}]},"16":{"vocabulary":[{"word":"noon","ipa":"/nuːn/","partsOfSpeech":"n.","meaning":"正午，中午"},{"word":"refuse","ipa":"/rɪˈfjuːz/","partsOfSpeech":"v.","meaning":"拒绝，回绝"},{"word":"territory","ipa":"/ˈterətri/","partsOfSpeech":"n.","meaning":"领土，版图，领域，范围"},{"word":"snow","ipa":"/snəʊ/","partsOfSpeech":"n./v.","meaning":"雪，下雪，积雪，如雪花般落下"},{"word":"accomplish","ipa":"/əˈkʌmplɪʃ/","partsOfSpeech":"v.","meaning":"完成，实现，达到"},{"word":"bath","ipa":"/bɑːθ/","partsOfSpeech":"n./v.","meaning":"洗澡，浴缸，沐浴，洗浴"},{"word":"dead","ipa":"/ded/","partsOfSpeech":"adj./adv./n.","meaning":"死的，无生命的，完全地，死者"},{"word":"notice","ipa":"/ˈnəʊtɪs/","partsOfSpeech":"n./v.","meaning":"注意，布告，通知，察觉"},{"word":"foot","ipa":"/fʊt/","partsOfSpeech":"n.","meaning":"脚，足，英尺"},{"word":"panda","ipa":"/ˈpændə/","partsOfSpeech":"n.","meaning":"熊猫，大熊猫"},{"word":"enormous","ipa":"/ɪˈnɔːməs/","partsOfSpeech":"adj.","meaning":"巨大的，庞大的，极大的"},{"word":"instrument","ipa":"/ˈɪnstrəmənt/","partsOfSpeech":"n.","meaning":"仪器，乐器，工具，手段"},{"word":"in","ipa":"/ɪn/","partsOfSpeech":"prep./adv.","meaning":"在...里面，在...期间"},{"word":"plastic","ipa":"/ˈplæstɪk/","partsOfSpeech":"n./adj.","meaning":"塑料，塑料的"},{"word":"camera","ipa":"/ˈkæm(ə)rə/","partsOfSpeech":"n.","meaning":"照相机，摄像机，镜头"}],"examples":[{"text":"When I am having a nap at noon, I hate being disturbed by other people.","translation":"我中午午睡时，讨厌被别人打扰。","source":"（2018年真题·词汇语法·第25题）","speechText":"When I am having a nap at noon, I hate being disturbed by other people.","annotations":[],"targetForms":[],"audio":"audio/course-examples/9ef29c7b76436322b41b0c24.mp3"},{"text":"Consumers can refuse the use of unnecessary single-use items when they order takeout.","translation":"消费者点外卖时，可以拒绝不必要的一次性用品。","source":"（2022年真题·阅读理解·Passage Three）","speechText":"Consumers can refuse the use of unnecessary single-use items when they order takeout.","annotations":[],"targetForms":[],"audio":"audio/course-examples/1d30b04fed7d485428f41136.mp3"},{"text":"Two players alternate in placing black and white stones on a large ruled board with the aim of surrounding territory.","translation":"两名棋手轮流在一个大型方格棋盘上落下黑子和白子，目的是围占地盘。","source":"（2023年真题·完形填空）","speechText":"Two players alternate in placing black and white stones on a large ruled board with the aim of surrounding territory.","annotations":[],"targetForms":[],"audio":"audio/course-examples/4c3eb4c6414fe1d36b378e94.mp3"},{"text":"Parts of the country may experience snow this weekend.","translation":"本周末，这个国家的部分地区可能会下雪。","source":"（2025年真题·选句填空·完整句选项）","speechText":"Parts of the country may experience snow this weekend.","annotations":[],"targetForms":[],"audio":"audio/course-examples/f1219f29482fb32b3559e266.mp3"},{"text":"Only when she had accomplished（accomplish的过去分词形式） the task did she realize that she had made a mistake.","translation":"直到完成了任务，她才意识到自己犯了一个错误。","source":"（2015年真题·词汇语法·第44题）","speechText":"Only when she had accomplished the task did she realize that she had made a mistake.","annotations":[{"text":"（accomplish的过去分词形式）","start":30,"end":49,"anchor":"accomplished"}],"targetForms":["accomplished"],"audio":"audio/course-examples/ebec612b86afcb0531914e5d.mp3"},{"text":"Take a warm bath.","translation":"洗个温水澡。","source":"（2017年配套材料·选句填空·完整句选项）","speechText":"Take a warm bath.","annotations":[],"targetForms":[],"audio":"audio/course-examples/16dd00cbdc01abc1c900fe8b.mp3"},{"text":"He's been dead for ages.","translation":"他已经去世很久了。","source":"（2016年真题·词汇语法·第24题）","speechText":"He's been dead for ages.","annotations":[],"targetForms":[],"audio":"audio/course-examples/29f0e223a2a5ec2b5541d357.mp3"},{"text":"If you know joyful people, you will probably notice common traits among them.","translation":"如果你认识快乐的人，大概会注意到他们具有一些共同特点。","source":"（2018年配套材料·选词填空）","speechText":"If you know joyful people, you will probably notice common traits among them.","annotations":[],"targetForms":[],"audio":"audio/course-examples/fec3d28c1410f36aa51c391e.mp3"},{"text":"Sit on the edge of the bed a minute before putting your feet（foot的复数形式） on the floor.","translation":"先在床边坐一分钟，再把双脚放到地上。","source":"（2018年真题·阅读理解·Passage Two）","speechText":"Sit on the edge of the bed a minute before putting your feet on the floor.","annotations":[{"text":"（foot的复数形式）","start":60,"end":71,"anchor":"feet"}],"targetForms":["feet"],"audio":"audio/course-examples/d7d4de1157f3477bf4ebb8c1.mp3"},{"text":"The panda is one of them.","translation":"熊猫就是其中之一。","source":"（2015年配套材料·英译汉）","speechText":"The panda is one of them.","annotations":[],"targetForms":[],"audio":"audio/course-examples/febacdfc55a74b112c8691c9.mp3"},{"text":"This situation changed, however, when suddenly factories began dumping enormous quantities of materials into the seas.","translation":"然而，当工厂突然开始向海洋倾倒大量物质时，这种情况就改变了。","source":"（2015年配套材料·选词填空）","speechText":"This situation changed, however, when suddenly factories began dumping enormous quantities of materials into the seas.","annotations":[],"targetForms":[],"audio":"audio/course-examples/5e4e298d1fa0881c8f66f89c.mp3"},{"text":"This new instrument is far superior to the old one we bought three years ago.","translation":"这台新仪器远比我们三年前买的那台旧仪器好。","source":"（2013年真题·词汇语法·第47题）","speechText":"This new instrument is far superior to the old one we bought three years ago.","annotations":[],"targetForms":[],"audio":"audio/course-examples/ba13aa0b624d5182b086723a.mp3"},{"text":"In 1870, Mark Twain married Olivia Langdon.","translation":"在1870年，马克·吐温与Olivia Langdon结婚。","source":"（2013年真题·阅读理解·Passage Three）","speechText":"In 1870, Mark Twain married Olivia Langdon.","annotations":[],"targetForms":[],"audio":"audio/course-examples/3b2f883eec70edf20fef98a6.mp3"},{"text":"Food delivery services are a major contributor to single-use plastic waste.","translation":"外卖服务是一次性塑料垃圾的主要来源之一。","source":"（2022年真题·阅读理解·Passage Three）","speechText":"Food delivery services are a major contributor to single-use plastic waste.","annotations":[],"targetForms":[],"audio":"audio/course-examples/de3ecbb6b6116b89d551b70c.mp3"},{"text":"Still, Fitz Patrick has mixed feelings about the speed cameras（camera的复数形式）.","translation":"不过，菲茨·帕特里克对测速摄像头仍抱有复杂的情绪。","source":"（2024年真题·阅读理解·Passage Two）","speechText":"Still, Fitz Patrick has mixed feelings about the speed cameras.","annotations":[{"text":"（camera的复数形式）","start":62,"end":75,"anchor":"cameras"}],"targetForms":["cameras"],"audio":"audio/course-examples/2097d33337e3ad20742cd396.mp3"}]},"17":{"vocabulary":[{"word":"few","ipa":"/fjuː/","partsOfSpeech":"adj./pron.","meaning":"很少的，少数的，几个，几乎没有"},{"word":"appear","ipa":"/əˈpɪə(r)/","partsOfSpeech":"v.","meaning":"出现，显得，看来，出版"},{"word":"equal","ipa":"/ˈiːkwəl/","partsOfSpeech":"adj./v./n.","meaning":"平等的，相等的，等于，对手"},{"word":"mother","ipa":"/ˈmʌðə(r)/","partsOfSpeech":"n.","meaning":"母亲，妈妈"},{"word":"thought","ipa":"/θɔːt/","partsOfSpeech":"n./v.","meaning":"思想，想法，思考（think的过去式/过去分词）"},{"word":"possession","ipa":"/pəˈzeʃ(ə)n/","partsOfSpeech":"n.","meaning":"拥有，财产，所有物"},{"word":"low","ipa":"/ləʊ/","partsOfSpeech":"adj./adv.","meaning":"低的，矮的，低声地，低价地"},{"word":"male","ipa":"/meɪl/","partsOfSpeech":"adj./n.","meaning":"男性的，雄性的，男子"},{"word":"system","ipa":"/ˈsɪstəm/","partsOfSpeech":"n.","meaning":"系统，体系，制度"},{"word":"picture","ipa":"/ˈpɪktʃə(r)/","partsOfSpeech":"n./v.","meaning":"照片，图画，想象，描绘"},{"word":"particular","ipa":"/pəˈtɪkjələ(r)/","partsOfSpeech":"adj./n.","meaning":"特定的，特殊的，挑剔的，详情"},{"word":"near","ipa":"/nɪə(r)/","partsOfSpeech":"prep./adv./adj.","meaning":"靠近，在...附近，接近的，亲近的"},{"word":"aim","ipa":"/eɪm/","partsOfSpeech":"n./v.","meaning":"目标，目的，瞄准，打算"},{"word":"gene","ipa":"/dʒiːn/","partsOfSpeech":"n.","meaning":"基因，遗传因子"},{"word":"well-known","ipa":"/ˌwel ˈnəʊn/","partsOfSpeech":"adj.","meaning":"著名的，众所周知的，出名的"}],"examples":[{"text":"Many children collect things, but few have enough money to buy the things they really want, and they lose interest.","translation":"许多孩子会收集东西，但很少有人有足够的钱买下真正想要的东西，因此他们逐渐失去了兴趣。","source":"（2022年真题·阅读理解·Passage One）","speechText":"Many children collect things, but few have enough money to buy the things they really want, and they lose interest.","annotations":[],"targetForms":[],"audio":"audio/course-examples/63482f1a26879054ddad9f18.mp3"},{"text":"A rainbow will appear","translation":"一道彩虹会出现","source":"（2026年真题·阅读理解·Passage Three）","speechText":"A rainbow will appear","annotations":[],"targetForms":[],"audio":"audio/course-examples/3db14b031a326e4446320c1b.mp3"},{"text":"His aim was to restore pride in being black and to inspire black Americans to campaign for equal rights.","translation":"他的目标是让黑人重新以自己的身份为荣，并激励美国黑人为争取平等权利而努力。","source":"（2014年真题·词汇语法·第48题）","speechText":"His aim was to restore pride in being black and to inspire black Americans to campaign for equal rights.","annotations":[],"targetForms":[],"audio":"audio/course-examples/996709929f6bfe62a797cc59.mp3"},{"text":"She spoke once of never really having a mother.","translation":"她曾说过，自己仿佛从未真正拥有过母亲。","source":"（2015年真题·阅读理解·Passage Three）","speechText":"She spoke once of never really having a mother.","annotations":[],"targetForms":[],"audio":"audio/course-examples/9a51800bb75353a7ace30c6f.mp3"},{"text":"Instead, it comes from internal thoughts（thought的复数形式） and assumptions.","translation":"相反，它源于内心的想法和假设。","source":"（2026年真题·阅读理解·Passage One）","speechText":"Instead, it comes from internal thoughts and assumptions.","annotations":[{"text":"（thought的复数形式）","start":40,"end":54,"anchor":"thoughts"}],"targetForms":["thoughts"],"audio":"audio/course-examples/1f0231c27ea77f5d24a05af7.mp3"},{"text":"Minimalism goes against consumer society by dramatically reducing possessions（possession的复数形式）.","translation":"极简主义通过大幅减少个人物品，来对抗消费主义社会的观念。","source":"（2021年真题·阅读理解·Passage Two）","speechText":"Minimalism goes against consumer society by dramatically reducing possessions.","annotations":[{"text":"（possession的复数形式）","start":77,"end":94,"anchor":"possessions"}],"targetForms":["possessions"],"audio":"audio/course-examples/df08de1ba6f4159633a89635.mp3"},{"text":"You should jump softly and low to the ground, and keep your hands low and close to your body.","translation":"你应该轻柔地、低着身子跳到地面，同时将双手低垂并贴近身体。","source":"（2024年真题·选句填空）","speechText":"You should jump softly and low to the ground, and keep your hands low and close to your body.","annotations":[],"targetForms":[],"audio":"audio/course-examples/8aaaa8ec23357ccfd0c3cd5a.mp3"},{"text":"When humpbacks live in denser populations, males looking for mates also have to deal with competing whales.","translation":"当座头鲸生活在种群密度更高的环境中时，寻找配偶的雄性座头鲸还必须应对其他竞争的鲸鱼。","source":"（2023年真题·阅读理解·Passage Three）","speechText":"When humpbacks live in denser populations, males looking for mates also have to deal with competing whales.","annotations":[],"targetForms":[],"audio":"audio/course-examples/fd1754fc4523737c8da37080.mp3"},{"text":"Indeed, the health benefits of jumping rope are many and affect multiple systems（system的复数形式） throughout the body.","translation":"确实，跳绳对健康有许多好处，并会影响全身多个系统。","source":"（2024年真题·选句填空）","speechText":"Indeed, the health benefits of jumping rope are many and affect multiple systems throughout the body.","annotations":[{"text":"（system的复数形式）","start":80,"end":93,"anchor":"systems"}],"targetForms":["systems"],"audio":"audio/course-examples/bf3f833f51b6d3c366f7e149.mp3"},{"text":"When you picture a desert, you probably imagine a vast, empty landscape far from any water.","translation":"当你想象沙漠时，你大概会想象一片辽阔而荒芜的景象，远离任何水源。","source":"（2026年真题·阅读理解·Passage Three）","speechText":"When you picture a desert, you probably imagine a vast, empty landscape far from any water.","annotations":[],"targetForms":[],"audio":"audio/course-examples/9ca7d39eff02cd318a66ed21.mp3"},{"text":"My brother likes eating very much but he isn't very particular about the food he eats.","translation":"我哥哥很喜欢吃东西，但对吃什么并不十分挑剔。","source":"（2016年真题·词汇语法·第28题）","speechText":"My brother likes eating very much but he isn't very particular about the food he eats.","annotations":[],"targetForms":[],"audio":"audio/course-examples/ad3eda3080ff4c5ba9dfbab2.mp3"},{"text":"That number is near estimated pre-whaling levels.","translation":"这一数量接近人们估计的大规模捕鲸活动开始前的水平。","source":"（2023年真题·阅读理解·Passage Three）","speechText":"That number is near estimated pre-whaling levels.","annotations":[],"targetForms":[],"audio":"audio/course-examples/f44f91e2b82ef81af60385b4.mp3"},{"text":"Over the years, people have made up new languages with this aim.","translation":"多年来，人们出于这个目的创造了一些新语言。","source":"（2014年真题·阅读理解·Passage Two）","speechText":"Over the years, people have made up new languages with this aim.","annotations":[],"targetForms":[],"audio":"audio/course-examples/0eb5d8cd399aa9e7f57fa0e1.mp3"},{"text":"Their genes（gene的复数形式） passed to future generations.","translation":"它们的基因传给了后代。","source":"（2022年真题·阅读理解·Passage One）","speechText":"Their genes passed to future generations.","annotations":[{"text":"（gene的复数形式）","start":11,"end":22,"anchor":"genes"}],"targetForms":["genes"],"audio":"audio/course-examples/4c58401c57cde3b40579d309.mp3"},{"text":"She is well-known in her lifetime and is still regarded as a great poet now.","translation":"她一生都广为人知，至今仍被视为伟大的诗人。","source":"（2015年·阅读理解·Passage Three）","speechText":"She is well-known in her lifetime and is still regarded as a great poet now.","annotations":[],"targetForms":[],"audio":"audio/course-examples/c4403c2a1808ee35844db44d.mp3"}]},"18":{"vocabulary":[{"word":"adopt","ipa":"/əˈdɒpt/","partsOfSpeech":"v.","meaning":"采用，采纳，收养，正式通过"},{"word":"automobile","ipa":"/ˈɔːtəməbiːl/","partsOfSpeech":"n.","meaning":"汽车，机动车"},{"word":"novel","ipa":"/ˈnɒv(ə)l/","partsOfSpeech":"n.","meaning":"小说，长篇小说"},{"word":"transform","ipa":"/trænsˈfɔːm/","partsOfSpeech":"v.","meaning":"改变，转换，变形"},{"word":"terrible","ipa":"/ˈterəb(ə)l/","partsOfSpeech":"adj.","meaning":"可怕的，极坏的，糟糕的"},{"word":"spy","ipa":"/spaɪ/","partsOfSpeech":"n./v.","meaning":"间谍，特务，暗中监视"},{"word":"accurate","ipa":"/ˈækjərət/","partsOfSpeech":"adj.","meaning":"准确的，精确的，正确的"},{"word":"baseball","ipa":"/ˈbeɪsbɔːl/","partsOfSpeech":"n.","meaning":"棒球，棒球运动"},{"word":"declare","ipa":"/dɪˈkleə(r)/","partsOfSpeech":"v.","meaning":"宣布，声明，申报，断言"},{"word":"corner","ipa":"/ˈkɔːnə(r)/","partsOfSpeech":"n./v.","meaning":"角落，拐角，困境，将...逼入死角"},{"word":"fiction","ipa":"/ˈfɪkʃ(ə)n/","partsOfSpeech":"n.","meaning":"小说，虚构的事"},{"word":"obtain","ipa":"/əbˈteɪn/","partsOfSpeech":"v.","meaning":"获得，得到，赢得，存在"},{"word":"else","ipa":"/els/","partsOfSpeech":"adv./adj.","meaning":"其他的，别的，另外"},{"word":"only","ipa":"/ˈəʊnli/","partsOfSpeech":"adv./adj.","meaning":"只有，仅仅，唯一的"},{"word":"stomach","ipa":"/ˈstʌmək/","partsOfSpeech":"n./v.","meaning":"胃，肚子，胃口，忍受"}],"examples":[{"text":"That fall, Yulia and her daughter were planning to adopt their first cat.","translation":"那个秋天，Yulia和女儿正计划领养她们的第一只猫。","source":"（2025年真题·阅读理解·Passage One）","speechText":"That fall, Yulia and her daughter were planning to adopt their first cat.","annotations":[],"targetForms":[],"audio":"audio/course-examples/9788f28cad095cded792106d.mp3"},{"text":"They dream of placing enzymes in the automobile to monitor exhaust and send data on pollution to a microprocessor that will then adjust the engine.","translation":"他们设想在汽车中安置酶来监测尾气，并把污染数据传送给微处理器，再由微处理器调节发动机。","source":"（2019年真题·阅读理解·Passage Two）","speechText":"They dream of placing enzymes in the automobile to monitor exhaust and send data on pollution to a microprocessor that will then adjust the engine.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e42542c695526ecbafd6f0fa.mp3"},{"text":"The books that we read can be novels（novel的复数形式）, essays or books about life.","translation":"我们读的书可以是小说、散文，也可以是关于生活的书籍。","source":"（2019年配套材料·英译汉）","speechText":"The books that we read can be novels, essays or books about life.","annotations":[{"text":"（novel的复数形式）","start":36,"end":48,"anchor":"novels"}],"targetForms":["novels"],"audio":"audio/course-examples/b1554c8a6ddfbc640b3a9d9b.mp3"},{"text":"the process of transforming volunteers into puppy raisers","translation":"将志愿者转变为幼犬养育者的流程","source":"（2022年·阅读理解·Passage Two）","speechText":"the process of transforming volunteers into puppy raisers","annotations":[],"targetForms":[],"audio":"audio/course-examples/28a6038c9624a6788f80b3a1.mp3"},{"text":"When something terrible happens to our friends, we often can’t respond properly.","translation":"当糟糕的事情发生在朋友身上时，我们往往不能作出恰当的回应。","source":"（2019年真题·阅读理解·Passage One）","speechText":"When something terrible happens to our friends, we often can’t respond properly.","annotations":[],"targetForms":[],"audio":"audio/course-examples/a12394f5453d0b8383169aef.mp3"},{"text":"The spy finally got all the information necessary for his government after a long stay here.","translation":"在这里待了很长一段时间后，这名间谍终于获得了他的政府所需要的全部信息。","source":"（2018年真题·词汇语法·第27题）","speechText":"The spy finally got all the information necessary for his government after a long stay here.","annotations":[],"targetForms":[],"audio":"audio/course-examples/d3475cb9eb3ddde4bb9ac764.mp3"},{"text":"These results must be accurate, because all the calculations have been done by an electronic computer.","translation":"这些结果一定是准确的，因为所有计算都是由电子计算机完成的。","source":"（2017年真题·词汇语法·第50题）","speechText":"These results must be accurate, because all the calculations have been done by an electronic computer.","annotations":[],"targetForms":[],"audio":"audio/course-examples/5358121a315b86b4751a5a68.mp3"},{"text":"Mark plays the violin, while his brother prefers to play baseball.","translation":"Mark拉小提琴，而他的哥哥或弟弟更喜欢打棒球。","source":"（2016年真题·词汇语法·第50题）","speechText":"Mark plays the violin, while his brother prefers to play baseball.","annotations":[],"targetForms":[],"audio":"audio/course-examples/6ff3d35b7bdb8ec0b2b2d762.mp3"},{"text":"The island where these rare birds nest has been declared（declare的过去分词形式） a reservation.","translation":"这个稀有鸟类筑巢的岛屿已被宣布为保护区。","source":"（2019年真题·词汇语法·第39题）","speechText":"The island where these rare birds nest has been declared a reservation.","annotations":[{"text":"（declare的过去分词形式）","start":56,"end":72,"anchor":"declared"}],"targetForms":["declared"],"audio":"audio/course-examples/f259fcc4ff03608910fac8e2.mp3"},{"text":"As National Day is round the corner, Shanghai is bathed in a festive atmosphere.","translation":"国庆节即将来临，上海洋溢着节日气氛。","source":"（2014年真题·词汇语法·第39题）","speechText":"As National Day is round the corner, Shanghai is bathed in a festive atmosphere.","annotations":[],"targetForms":[],"audio":"audio/course-examples/c0913d6df6836949742b21ff.mp3"},{"text":"Reading non-fiction and fiction improves your understanding of people and the world around you.","translation":"阅读非虚构作品和虚构作品，都能增进你对他人及周围世界的理解。","source":"（2016年配套材料·选句填空）","speechText":"Reading non-fiction and fiction improves your understanding of people and the world around you.","annotations":[],"targetForms":[],"audio":"audio/course-examples/38303a27c75df08c519ea183.mp3"},{"text":"Therefore, putting it near a sunny window to obtain enough indirect light would be your best bet.","translation":"因此，把它放在阳光充足的窗户附近，以获得足够的散射光，会是最好的选择。","source":"（2014年配套材料·选句填空）","speechText":"Therefore, putting it near a sunny window to obtain enough indirect light would be your best bet.","annotations":[],"targetForms":[],"audio":"audio/course-examples/976be1e85e4e01486671fb81.mp3"},{"text":"Dress warmly, or else you'll catch cold.","translation":"穿暖和些，否则你会感冒的。","source":"（2019年真题·词汇语法·第38题）","speechText":"Dress warmly, or else you'll catch cold.","annotations":[],"targetForms":[],"audio":"audio/course-examples/d6aaea9977a7a9404cc7e596.mp3"},{"text":"Don’t judge them only by their intonation!","translation":"不要仅凭他们说话的语调来评判他们！","source":"（2018年真题·阅读理解·Passage Three）","speechText":"Don’t judge them only by their intonation!","annotations":[],"targetForms":[],"audio":"audio/course-examples/694c13885791291638d4bf5d.mp3"},{"text":"All the while he was terrified by the fear that he had cancer of the stomach.","translation":"他始终因担心自己得了胃癌而感到恐惧。","source":"（2014年真题·词汇语法·第36题）","speechText":"All the while he was terrified by the fear that he had cancer of the stomach.","annotations":[],"targetForms":[],"audio":"audio/course-examples/70ded3267b9c87451e3d4ddd.mp3"}]},"19":{"vocabulary":[{"word":"virus","ipa":"/ˈvaɪrəs/","partsOfSpeech":"n.","meaning":"病毒，（计算机）病毒"},{"word":"student","ipa":"/ˈstjuːd(ə)nt/","partsOfSpeech":"n.","meaning":"学生，学者，研究者"},{"word":"modern","ipa":"/ˈmɒd(ə)n/","partsOfSpeech":"adj./n.","meaning":"现代的，近代的，现代人"},{"word":"between","ipa":"/bɪˈtwiːn/","partsOfSpeech":"prep./adv.","meaning":"在...之间，在中间"},{"word":"tolerate","ipa":"/ˈtɒləreɪt/","partsOfSpeech":"v.","meaning":"容忍，忍受，默许，宽恕"},{"word":"have","ipa":"/hæv; həv/","partsOfSpeech":"v./aux.","meaning":"有，让，已经"},{"word":"used","ipa":"/juːst;juːzd/","partsOfSpeech":"adj./v.","meaning":"用过的，旧的，习惯于，适应于；使用（use 的过去式和过去分词）"},{"word":"example","ipa":"/ɪɡˈzɑːmp(ə)l/","partsOfSpeech":"n.","meaning":"例子，榜样，样本，范例"},{"word":"every","ipa":"/ˈevri/","partsOfSpeech":"adj.","meaning":"每一个，每个，每隔，所有的"},{"word":"lead","ipa":"/liːd/","partsOfSpeech":"v.","meaning":"领导，引导，导致"},{"word":"room","ipa":"/ruːm/","partsOfSpeech":"n.","meaning":"房间，空间，余地，室"},{"word":"photo","ipa":"/ˈfəʊtəʊ/","partsOfSpeech":"n./v.","meaning":"照片，相片，拍照"},{"word":"view","ipa":"/vjuː/","partsOfSpeech":"n./v.","meaning":"观点，视野，风景，看待"},{"word":"next","ipa":"/nekst/","partsOfSpeech":"adj./adv./n.","meaning":"下一个的，其次，下一个人/物"},{"word":"real","ipa":"/ˈriːəl/","partsOfSpeech":"adj./adv.","meaning":"真实的，真正的，实际的；很、非常（非正式用法）"}],"examples":[{"text":"Avoid touching your face, as hands can introduce viruses（virus的复数形式）.","translation":"避免触摸脸部，因为双手可能把病毒带到脸上。","source":"（2025年真题·选句填空·完整句选项）","speechText":"Avoid touching your face, as hands can introduce viruses.","annotations":[{"text":"（virus的复数形式）","start":56,"end":68,"anchor":"viruses"}],"targetForms":["viruses"],"audio":"audio/course-examples/e234e31ac25d76fd7de049d8.mp3"},{"text":"Some students（student的复数形式） may want to travel by car.","translation":"有些学生可能想开车出行。","source":"（2015年真题·阅读理解·Passage Two）","speechText":"Some students may want to travel by car.","annotations":[{"text":"（student的复数形式）","start":13,"end":27,"anchor":"students"}],"targetForms":["students"],"audio":"audio/course-examples/b48a4eb3d3943130f3237ed5.mp3"},{"text":"In modern society many people have trouble falling asleep.","translation":"在现代社会，许多人难以入睡。","source":"（2017年配套材料·选句填空）","speechText":"In modern society many people have trouble falling asleep.","annotations":[],"targetForms":[],"audio":"audio/course-examples/f26ca820e0c930df40b751e1.mp3"},{"text":"It was the space between market days.","translation":"它原本是两个集市日之间的时间间隔。","source":"（2019年真题·阅读理解·Passage Three）","speechText":"It was the space between market days.","annotations":[],"targetForms":[],"audio":"audio/course-examples/da7cff298226a79713121266.mp3"},{"text":"Majesty Palm is used to living under bigger trees in its natural habitat in Madagascar, making it tolerate indirect light.","translation":"棕榈树在马达加斯加的自然栖息地中通常生长在较大的树木下方，因此能够耐受间接光照。","source":"（2014年配套材料·选句填空）","speechText":"Majesty Palm is used to living under bigger trees in its natural habitat in Madagascar, making it tolerate indirect light.","annotations":[],"targetForms":[],"audio":"audio/course-examples/c54cc22589018733446e971f.mp3"},{"text":"Psychologists and collectors have different opinions.","translation":"心理学家和收藏者有着不同的看法。","source":"（2022年真题·阅读理解·Passage One）","speechText":"Psychologists and collectors have different opinions.","annotations":[],"targetForms":[],"audio":"audio/course-examples/c2cffe55e326be6e72e79551.mp3"},{"text":"You can get your body used to the motion of jumping up and down before involving the coordination required of using a rope.","translation":"在开始使用绳子需要协调动作之前，你可以先让身体适应上下跳跃的动作。","source":"（2024年真题·选句填空）","speechText":"You can get your body used to the motion of jumping up and down before involving the coordination required of using a rope.","annotations":[],"targetForms":[],"audio":"audio/course-examples/260163ef54a4d4db97c91d5e.mp3"},{"text":"For example, Wednesday was called the fourth day (four days after Saturday).","translation":"例如，星期三被称为第四天，也就是星期六之后的第四天。","source":"（2019年真题·阅读理解·Passage Three）","speechText":"For example, Wednesday was called the fourth day (four days after Saturday).","annotations":[],"targetForms":[],"audio":"audio/course-examples/e5a1d4038d2a8dddeb3c46b2.mp3"},{"text":"The Babylonians decided that it should be every seventh day.","translation":"巴比伦人决定应每七天举行一次。","source":"（2019年真题·阅读理解·Passage Three）","speechText":"The Babylonians decided that it should be every seventh day.","annotations":[],"targetForms":[],"audio":"audio/course-examples/80446d1960ff553d95e79de7.mp3"},{"text":"This worry often leads people to think that the other person expects something big in return. ","translation":"这种担忧常常导致人们认为，对方期望得到某种很大的回报。","source":"（2026年真题·阅读理解·Passage One）","speechText":"This worry often leads people to think that the other person expects something big in return.","annotations":[],"targetForms":[],"audio":"audio/course-examples/a7f3b1a4ed66e095a3f0847c.mp3"},{"text":"Typically, an interview is held in a conference room or office.","translation":"面试通常在一个会议室或办公室举行。","source":"（2020年真题·阅读理解·Passage One）","speechText":"Typically, an interview is held in a conference room or office.","annotations":[],"targetForms":[],"audio":"audio/course-examples/25177f876cd877134226c265.mp3"},{"text":"Watch out for fake photos（photo的复数形式）.","translation":"当心虚假照片。","source":"（2020年真题·选句填空·完整句选项）","speechText":"Watch out for fake photos.","annotations":[{"text":"（photo的复数形式）","start":25,"end":37,"anchor":"photos"}],"targetForms":["photos"],"audio":"audio/course-examples/85d0226f7b1853a8994a8c63.mp3"},{"text":" There are different views on the use of speed cameras. ","translation":"人们对使用测速摄像头持有不同看法。","source":"（2024年真题·阅读理解·Passage Two）","speechText":"There are different views on the use of speed cameras.","annotations":[],"targetForms":[],"audio":"audio/course-examples/20e64d23fcaf1b9c13a26aa7.mp3"},{"text":"His new appointment takes effect from the beginning of next month.","translation":"他的新任命从下个月月初起生效。","source":"（2019年真题·词汇语法·第34题）","speechText":"His new appointment takes effect from the beginning of next month.","annotations":[],"targetForms":[],"audio":"audio/course-examples/5bab20347c0369c0c206142e.mp3"},{"text":"It is doubtful that safety is the real goal, said Jay Beeber, with the National Motorists Association, a driver advocacy group.","translation":"驾驶员权益组织“美国驾车者协会”的Jay Beeber说：“安全是否是真正的目标，值得怀疑。”","source":"（2024年真题·阅读理解·Passage Two）","speechText":"It is doubtful that safety is the real goal, said Jay Beeber, with the National Motorists Association, a driver advocacy group.","annotations":[],"targetForms":[],"audio":"audio/course-examples/a7dc623d6ecc335e06011ade.mp3"}]},"20":{"vocabulary":[{"word":"mention","ipa":"/ˈmenʃ(ə)n/","partsOfSpeech":"v./n.","meaning":"提到，谈及，提及"},{"word":"street","ipa":"/striːt/","partsOfSpeech":"n.","meaning":"街道，马路，街区"},{"word":"planet","ipa":"/ˈplænɪt/","partsOfSpeech":"n.","meaning":"行星，地球"},{"word":"video","ipa":"/ˈvɪdiəʊ/","partsOfSpeech":"n.","meaning":"视频，录像"},{"word":"private","ipa":"/ˈpraɪvət/","partsOfSpeech":"adj.","meaning":"私人的，私密的，私立的"},{"word":"moral","ipa":"/ˈmɒrəl/","partsOfSpeech":"adj./n.","meaning":"道德的，品行的，道德规范"},{"word":"forward","ipa":"/ˈfɔːwəd/","partsOfSpeech":"adv./adj./v.","meaning":"向前，向前的，转交，促进"},{"word":"title","ipa":"/ˈtaɪt(ə)l/","partsOfSpeech":"n./v.","meaning":"标题，头衔，冠军，加标题"},{"word":"wide","ipa":"/waɪd/","partsOfSpeech":"adj./adv.","meaning":"宽的，广阔的，广泛地，张大地"},{"word":"admit","ipa":"/ədˈmɪt/","partsOfSpeech":"v.","meaning":"承认，允许进入，接纳，容纳"},{"word":"award","ipa":"/əˈwɔːd/","partsOfSpeech":"n./v.","meaning":"奖，奖品，授予"},{"word":"nut","ipa":"/nʌt/","partsOfSpeech":"n.","meaning":"坚果"},{"word":"tree","ipa":"/triː/","partsOfSpeech":"n.","meaning":"树，树木，乔木，谱系"},{"word":"tenth","ipa":"/tenθ/","partsOfSpeech":"num./n.","meaning":"第十，十分之一"},{"word":"stair","ipa":"/steə(r)/","partsOfSpeech":"n.","meaning":"楼梯，阶梯，梯级"}],"examples":[{"text":"\"Cash was the best way to teach people about financial knowledge because it's so easy to grasp.\" Philip Haglund, CEO of Gimi, mentions（mention的第三人称单数）. ","translation":"“现金是向人们传授财务知识的最佳方式，因为它最容易理解。”Gimi公司首席执行官菲利普·哈格伦德提到。","source":"（2020年阅读 Passage Three）","speechText":"\"Cash was the best way to teach people about financial knowledge because it's so easy to grasp.\" Philip Haglund, CEO of Gimi, mentions.","annotations":[{"text":"（mention的第三人称单数）","start":134,"end":150,"anchor":"mentions"}],"targetForms":["mentions"],"audio":"audio/course-examples/65738e00a1379e73ea07cf55.mp3"},{"text":"Martin Cooper operated a large, heavy, new communication device on a street in New York.","translation":"Martin Cooper在纽约的一条街上，操作了一台体积大、重量重的新型通信设备。","source":"（2023年真题·阅读理解·Passage Two）","speechText":"Martin Cooper operated a large, heavy, new communication device on a street in New York.","annotations":[],"targetForms":[],"audio":"audio/course-examples/1f73ee83d0d00f713c26315d.mp3"},{"text":"Then, there is the horizontal movement of air across the planet.","translation":"另外，还有空气在地球表面的水平流动。","source":"（2026年真题·阅读理解·Passage Three）","speechText":"Then, there is the horizontal movement of air across the planet.","annotations":[],"targetForms":[],"audio":"audio/course-examples/d0ffc8f8fcdd7dde952e8776.mp3"},{"text":"Videos（video的复数形式） of her theatrical demonstrations have attracted hundreds of millions of views across social media platforms.","translation":"她那些富有戏剧性的演示视频，在各大社交媒体平台累计获得了数亿次观看。","source":"（2024年真题·阅读理解·Passage One）","speechText":"Videos of her theatrical demonstrations have attracted hundreds of millions of views across social media platforms.","annotations":[{"text":"（video的复数形式）","start":6,"end":18,"anchor":"Videos"}],"targetForms":["Videos"],"audio":"audio/course-examples/43da282e46b8a54ab6dcbafe.mp3"},{"text":"The reality is that writing is a lonely, private and poor-paying affair.","translation":"现实是，写作是一件孤独、私密而且收入微薄的事情。","source":"（2015年真题·阅读理解·Passage One）","speechText":"The reality is that writing is a lonely, private and poor-paying affair.","annotations":[],"targetForms":[],"audio":"audio/course-examples/f64c56e9f4540e36eacd89d1.mp3"},{"text":"People who feel they have unlimited moral choices in their lives when it comes to matters of sex or drugs, for example, tend to be unhappier than those who do not feel they have so many choices in life.","translation":"例如，在性或毒品等问题上，那些觉得自己拥有无限道德选择的人，往往比不认为生活中有如此多选择的人更不快乐。","source":"（2016年真题·阅读理解·Passage One）","speechText":"People who feel they have unlimited moral choices in their lives when it comes to matters of sex or drugs, for example, tend to be unhappier than those who do not feel they have so many choices in life.","annotations":[],"targetForms":[],"audio":"audio/course-examples/87f6d618b4fac0fcc5c2c231.mp3"},{"text":"Unlike forward walking, which primarily engages the ankles, backward walking shifts the workload to the knees.","translation":"向前走主要调动脚踝，而倒着走会把更多负荷转移到膝盖上。","source":"（2025年真题·阅读理解·Passage Two）","speechText":"Unlike forward walking, which primarily engages the ankles, backward walking shifts the workload to the knees.","annotations":[],"targetForms":[],"audio":"audio/course-examples/08bc2142e133bd315c0eff73.mp3"},{"text":"Post them on a variety of social media, use “#” and catchy titles（title的复数形式） and make sure that they can be easily found.","translation":"把内容发布到多种社交媒体上，使用“#”话题标签和吸引人的标题，确保人们容易找到这些内容。","source":"（2020年真题·阅读理解·Passage Two）","speechText":"Post them on a variety of social media, use “#” and catchy titles and make sure that they can be easily found.","annotations":[{"text":"（title的复数形式）","start":65,"end":77,"anchor":"titles"}],"targetForms":["titles"],"audio":"audio/course-examples/4f254cdbc88e59d1b713e01c.mp3"},{"text":"Another technique takes embryo (胚胎) cells and develops them into a wide variety of cell types and tissues.","translation":"另一种技术利用胚胎细胞，将其培养成各种不同类型的细胞和组织。","source":"（2017年配套材料·选词填空）","speechText":"Another technique takes embryo cells and develops them into a wide variety of cell types and tissues.","annotations":[{"text":"(胚胎)","start":31,"end":35,"anchor":"embryo"}],"targetForms":[],"audio":"audio/course-examples/c13c9101c8789e7edf25d898.mp3"},{"text":"Since most men have difficulty admitting（admit的-ing形式） loneliness and hurt, they tend to become angry instead.","translation":"由于大多数男性难以承认自己的孤独和受伤，他们往往会转而表现出愤怒。","source":"（2018年真题·阅读理解·Passage one）","speechText":"Since most men have difficulty admitting loneliness and hurt, they tend to become angry instead.","annotations":[{"text":"（admit的-ing形式）","start":40,"end":54,"anchor":"admitting"}],"targetForms":["admitting"],"audio":"audio/course-examples/89ff77b5b18f336e8f4397ed.mp3"},{"text":"Cooper received an award there for his lifetime of work.","translation":"Cooper在那里因其毕生的工作成就而获得了一个奖项。","source":"（2023年真题·阅读理解·Passage Two）","speechText":"Cooper received an award there for his lifetime of work.","annotations":[],"targetForms":[],"audio":"audio/course-examples/4e2c6106a3331d9181c58ba1.mp3"},{"text":"Thousands of years ago, humans collected nuts（nut的复数形式） and fruits.","translation":"几千年前，人类采集坚果和水果。","source":"（2022年真题·阅读理解·Passage One）","speechText":"Thousands of years ago, humans collected nuts and fruits.","annotations":[{"text":"（nut的复数形式）","start":45,"end":55,"anchor":"nuts"}],"targetForms":["nuts"],"audio":"audio/course-examples/380ee8d2396124ce1c5f2fdd.mp3"},{"text":"Majesty Palm is used to living under bigger trees（tree的复数形式） in its natural habitat in Madagascar, making it tolerate indirect light.","translation":"Majesty Palm棕榈在马达加斯加的原生环境中，习惯生长在更高大的树木下，因此能够适应散射光。","source":"（2014年配套材料·选句填空）","speechText":"Majesty Palm is used to living under bigger trees in its natural habitat in Madagascar, making it tolerate indirect light.","annotations":[{"text":"（tree的复数形式）","start":49,"end":60,"anchor":"trees"}],"targetForms":["trees"],"audio":"audio/course-examples/c54cc22589018733446e971f.mp3"},{"text":"Sometimes these market days were fixed at every tenth day, sometimes every seventh or every fifth day.","translation":"这些集市日有时定在每隔十天一次，有时每隔七天或五天一次。","source":"（2019年真题·阅读理解·Passage Three）","speechText":"Sometimes these market days were fixed at every tenth day, sometimes every seventh or every fifth day.","annotations":[],"targetForms":[],"audio":"audio/course-examples/b38823b40ef042327ce9b76f.mp3"},{"text":"Lundberg will still listen in from the stairs（stair的复数形式） sometimes, because it's pretty funny.","translation":"Lundberg有时仍会在楼梯上听听孩子们打电话，因为这实在很有趣。","source":"（2026年真题·阅读理解·Passage Two）","speechText":"Lundberg will still listen in from the stairs sometimes, because it's pretty funny.","annotations":[{"text":"（stair的复数形式）","start":45,"end":57,"anchor":"stairs"}],"targetForms":["stairs"],"audio":"audio/course-examples/d29756e7819d25c075d5ac24.mp3"}]},"21":{"vocabulary":[{"word":"indeed","ipa":"/ɪnˈdiːd/","partsOfSpeech":"adv.","meaning":"的确，实在，确实，真正地"},{"word":"bar","ipa":"/bɑː(r)/","partsOfSpeech":"n./v.","meaning":"酒吧，条，障碍，阻挡"},{"word":"deer","ipa":"/dɪə(r)/","partsOfSpeech":"n.","meaning":"鹿"},{"word":"cool","ipa":"/kuːl/","partsOfSpeech":"adj./v.","meaning":"凉爽的，冷静的，酷的，变凉"},{"word":"vivid","ipa":"/ˈvɪvɪd/","partsOfSpeech":"adj.","meaning":"生动的，鲜艳的，栩栩如生的，清晰的"},{"word":"electronic","ipa":"/ɪˌlekˈtrɒnɪk/","partsOfSpeech":"adj.","meaning":"电子的，电子设备的，网上的"},{"word":"stretch","ipa":"/stretʃ/","partsOfSpeech":"v./n.","meaning":"伸展，延伸，弹性"},{"word":"county","ipa":"/ˈkaʊnti/","partsOfSpeech":"n.","meaning":"县，郡"},{"word":"zero","ipa":"/ˈzɪərəʊ/","partsOfSpeech":"num./n./v.","meaning":"零，没有，最低点，归零"},{"word":"introduce","ipa":"/ˌɪntrəˈdjuːs/","partsOfSpeech":"v.","meaning":"介绍，引进，提出，推行"},{"word":"thing","ipa":"/θɪŋ/","partsOfSpeech":"n.","meaning":"事情，东西，事物，情况"},{"word":"liberation","ipa":"/ˌlɪbəˈreɪʃ(ə)n/","partsOfSpeech":"n.","meaning":"解放，释放，解脱"},{"word":"center","ipa":"/ˈsentə(r)/","partsOfSpeech":"n./v.","meaning":"中心，中心点，集中，（使）注意力集中于"},{"word":"east","ipa":"/iːst/","partsOfSpeech":"n./adj./adv.","meaning":"东方，东部的，向东"},{"word":"scissors","ipa":"/ˈsɪzəz/","partsOfSpeech":"n.","meaning":"剪刀"}],"examples":[{"text":"Indeed, the health benefits of jumping rope are many and affect multiple systems throughout the body.","translation":"确实，跳绳对健康有许多好处，并会影响全身多个系统。","source":"（2024年真题·选句填空）","speechText":"Indeed, the health benefits of jumping rope are many and affect multiple systems throughout the body.","annotations":[],"targetForms":[],"audio":"audio/course-examples/bf3f833f51b6d3c366f7e149.mp3"},{"text":"College professors these days face an ever-higher bar to grab the attention of their students, forced to compete with the pulling power of smartphones and laptops in large lecture halls.","translation":"如今，大学教授要吸引学生的注意力，面临的要求越来越高；在大讲堂里，他们不得不与智能手机和笔记本电脑的吸引力竞争。","source":"（2024年真题·阅读理解·Passage One）","speechText":"College professors these days face an ever-higher bar to grab the attention of their students, forced to compete with the pulling power of smartphones and laptops in large lecture halls.","annotations":[],"targetForms":[],"audio":"audio/course-examples/ea232264ace4b552f0220c74.mp3"},{"text":"The huntsman caught only a glimpse of the deer before it ran into the woods.","translation":"那只鹿跑进树林前，猎人只来得及瞥见它一眼。","source":"（2017年真题·词汇语法·第40题）","speechText":"The huntsman caught only a glimpse of the deer before it ran into the woods.","annotations":[],"targetForms":[],"audio":"audio/course-examples/d520d8131a5ff3f5af72e147.mp3"},{"text":"Any moisture in the air cools（cool的第三人称单数形式） and changes into clouds and rain.","translation":"空气中的水汽冷却后，便形成云和雨。","source":"（2026年真题·阅读理解·Passage Three）","speechText":"Any moisture in the air cools and changes into clouds and rain.","annotations":[{"text":"（cool的第三人称单数形式）","start":29,"end":44,"anchor":"cools"}],"targetForms":["cools"],"audio":"audio/course-examples/791a585b0c311e7f5191dcf9.mp3"},{"text":"Joy on the other hand, is described as a vivid emotion of pleasure.","translation":"另一方面，喜悦被描述为一种鲜明而强烈的愉快情绪。","source":"（2018年配套材料·选词填空）","speechText":"Joy on the other hand, is described as a vivid emotion of pleasure.","annotations":[],"targetForms":[],"audio":"audio/course-examples/47a4f7053d3b3de015e93ba3.mp3"},{"text":"These results must be accurate, because all the calculations have been done by an electronic computer.","translation":"这些结果一定是准确的，因为所有计算都是由电子计算机完成的。","source":"（2017年真题·词汇语法·第50题）","speechText":"These results must be accurate, because all the calculations have been done by an electronic computer.","annotations":[],"targetForms":[],"audio":"audio/course-examples/5358121a315b86b4751a5a68.mp3"},{"text":"Get up with a leisurely yawn and stretch.","translation":"悠闲地打着哈欠、伸着懒腰起床。","source":"（2018年真题·阅读理解·Passage Two）","speechText":"Get up with a leisurely yawn and stretch.","annotations":[],"targetForms":[],"audio":"audio/course-examples/9741dea5007d272eb80fe45b.mp3"},{"text":"His short story, \"The Celebrated Jumping Frog of Calaver’s County\", was an immediate success and his new life began.","translation":"他的短篇小说《卡拉维拉县著名的跳蛙》一发表就大获成功，他的新生活也由此开始。","source":"（2013年真题·阅读理解·Passage Three）","speechText":"His short story, \"The Celebrated Jumping Frog of Calaver’s County\", was an immediate success and his new life began.","annotations":[],"targetForms":[],"audio":"audio/course-examples/1eebf13da0cee52d3b4e10d9.mp3"},{"text":"At Lufka Refillable Zero Waste store in Tampa, customers bring in reusable containers to fill with soap, shampoo and cleaning supplies instead of buying products in single-use packaging.","translation":"在坦帕市的Lufka零废弃补充装商店，顾客自带可重复使用的容器来装肥皂、洗发水和清洁用品，而不是购买采用一次性包装的产品。","source":"（2026年真题·完形填空）","speechText":"At Lufka Refillable Zero Waste store in Tampa, customers bring in reusable containers to fill with soap, shampoo and cleaning supplies instead of buying products in single-use packaging.","annotations":[],"targetForms":[],"audio":"audio/course-examples/bf0ca81b176602377245ff4c.mp3"},{"text":"Avoid touching your face, as hands can introduce viruses.","translation":"避免触摸脸部，因为双手可能把病毒带到脸上。","source":"（2025年真题·选句填空·完整句选项）","speechText":"Avoid touching your face, as hands can introduce viruses.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e234e31ac25d76fd7de049d8.mp3"},{"text":"Allow things（thing的复数形式） to settle with time.","translation":"让事情随着时间慢慢平息下来。","source":"（2021年真题·选句填空）","speechText":"Allow things to settle with time.","annotations":[{"text":"（thing的复数形式）","start":12,"end":24,"anchor":"things"}],"targetForms":["things"],"audio":"audio/course-examples/a93c41e3ce03f9a10db0e363.mp3"},{"text":"This is the era of women’s liberation.","translation":"这是妇女解放的时代。","source":"（2013年真题·阅读理解·Passage Two）","speechText":"This is the era of women’s liberation.","annotations":[],"targetForms":[],"audio":"audio/course-examples/0c9844086efe055206aaf2f6.mp3"},{"text":"Her work has centered（center的过去分词形式） on humpbacks that reproduce near Australia’s Great Barrier Reef.","translation":"她的研究主要围绕在澳大利亚大堡礁附近繁殖的座头鲸展开。","source":"（2023年真题·阅读理解·Passage Three）","speechText":"Her work has centered on humpbacks that reproduce near Australia’s Great Barrier Reef.","annotations":[{"text":"（center的过去分词形式）","start":21,"end":36,"anchor":"centered"}],"targetForms":["centered"],"audio":"audio/course-examples/35f19141245806be0058bd7d.mp3"},{"text":"In the case of the Namib Desert, for example, when it does rain, that rain does not fall in the desert itself but rather in the mountains to the east.","translation":"以纳米布沙漠为例，那里即使下雨，雨也不是下在沙漠本身，而是下在东面的山中。","source":"（2026年真题·阅读理解·Passage Three）","speechText":"In the case of the Namib Desert, for example, when it does rain, that rain does not fall in the desert itself but rather in the mountains to the east.","annotations":[],"targetForms":[],"audio":"audio/course-examples/4f8f8ce2042c51de8d79737f.mp3"},{"text":"Losers were likely to throw the hand symbol of scissors","translation":"失败者很可能会打出代表剪刀的手势","source":"（2021年真题·阅读理解·Passage One）","speechText":"Losers were likely to throw the hand symbol of scissors","annotations":[],"targetForms":[],"audio":"audio/course-examples/cd711cb72c2f749389f351a9.mp3"}]},"22":{"vocabulary":[{"word":"follow","ipa":"/ˈfɒləʊ/","partsOfSpeech":"v.","meaning":"跟随，遵循，听懂"},{"word":"according","ipa":"/əˈkɔːdɪŋ/","partsOfSpeech":"adv./adj.","meaning":"根据，按照；相符的，according to（介词短语）：根据，按照"},{"word":"build","ipa":"/bɪld/","partsOfSpeech":"v./n.","meaning":"建筑，建立，体型，构造"},{"word":"site","ipa":"/saɪt/","partsOfSpeech":"n./v.","meaning":"遗址，地点，网站，使坐落于"},{"word":"decide","ipa":"/dɪˈsaɪd/","partsOfSpeech":"v.","meaning":"决定，下决心，判决，解决"},{"word":"essay","ipa":"/ˈeseɪ/","partsOfSpeech":"n.","meaning":"散文，随笔，论文"},{"word":"culture","ipa":"/ˈkʌltʃə(r)/","partsOfSpeech":"n./v.","meaning":"文化，文明，修养，培植"},{"word":"produce","ipa":"/prəˈdjuːs;ˈprɒdjuːs/","partsOfSpeech":"v./n.","meaning":"生产，引起；产品，农产品"},{"word":"physics","ipa":"/ˈfɪzɪks/","partsOfSpeech":"n.","meaning":"物理学，物理现象"},{"word":"warm","ipa":"/wɔːm/","partsOfSpeech":"adj./v.","meaning":"温暖的，热情的，使温暖，变暖"},{"word":"profession","ipa":"/prəˈfeʃn/","partsOfSpeech":"n.","meaning":"职业，专业，声明"},{"word":"public","ipa":"/ˈpʌblɪk/","partsOfSpeech":"adj./n.","meaning":"公众的，公共的，公开的，大众"},{"word":"network","ipa":"/ˈnetwɜːk/","partsOfSpeech":"n./v.","meaning":"网络，网状物，广播网，联网"},{"word":"poem","ipa":"/ˈpəʊɪm/","partsOfSpeech":"n.","meaning":"诗，韵文"},{"word":"vegetable","ipa":"/ˈvedʒtəb(ə)l/","partsOfSpeech":"n.","meaning":"蔬菜"}],"examples":[{"text":"Follow their examples and have fun with kids on the Net!","translation":"遵循着他们的样子，和孩子们一起在网上玩得开心吧！","source":"（2017年真题·阅读理解·Passage One）","speechText":"Follow their examples and have fun with kids on the Net!","annotations":[],"targetForms":[],"audio":"audio/course-examples/3d37d4d479cc30eaa9bc0ad7.mp3"},{"text":"According to Baldwin, \"practice, practice, practice\" is the key to success.","translation":"根据Baldwin，“练习、练习、再练习”是成功的关键。","source":"（2021年真题·阅读理解·Passage One）","speechText":"According to Baldwin, \"practice, practice, practice\" is the key to success.","annotations":[],"targetForms":[],"audio":"audio/course-examples/a4ecccbcd9f9359d0584588a.mp3"},{"text":"The new smart structures could be very expensive to build.","translation":"建造这种新的智能结构，费用可能非常高。","source":"（2014年真题·阅读理解·Passage Three）","speechText":"The new smart structures could be very expensive to build.","annotations":[],"targetForms":[],"audio":"audio/course-examples/cd5899c128e6c69929bab179.mp3"},{"text":"Many fake news stories use images from unrelated sites（site的复数形式）.","translation":"许多假新闻使用与报道无关的网站上的图片。","source":"（2020年真题·选句填空）","speechText":"Many fake news stories use images from unrelated sites.","annotations":[{"text":"（site的复数形式）","start":54,"end":65,"anchor":"sites"}],"targetForms":["sites"],"audio":"audio/course-examples/b377a2a341dbca9ebe8111c2.mp3"},{"text":"The Babylonians decided（decide的过去式） that it should be every seventh day.","translation":"巴比伦人决定每隔七天设一个集市日。","source":"（2019年真题·阅读理解·Passage Three）","speechText":"The Babylonians decided that it should be every seventh day.","annotations":[{"text":"（decide的过去式）","start":23,"end":35,"anchor":"decided"}],"targetForms":["decided"],"audio":"audio/course-examples/80446d1960ff553d95e79de7.mp3"},{"text":"The books that we read can be novels, essays（essay的复数形式） or books about life.","translation":"我们读的书可以是小说、散文，也可以是关于生活的书籍。","source":"（2019年配套材料·英译汉）","speechText":"The books that we read can be novels, essays or books about life.","annotations":[{"text":"（essay的复数形式）","start":44,"end":56,"anchor":"essays"}],"targetForms":["essays"],"audio":"audio/course-examples/b1554c8a6ddfbc640b3a9d9b.mp3"},{"text":"So it's really about changing the culture and slowing traffic down.","translation":"所以关键在于改变文化，同时减缓交通流量。","source":"（2024年真题·阅读理解·Passage Two）","speechText":"So it's really about changing the culture and slowing traffic down.","annotations":[],"targetForms":[],"audio":"audio/course-examples/466609599739f88277f0f948.mp3"},{"text":"Reusable containers require more energy and materials to produce.","translation":"可重复使用的容器在生产过程中需要更多的能源和材料。","source":"（2026年真题·完形填空）","speechText":"Reusable containers require more energy and materials to produce.","annotations":[],"targetForms":[],"audio":"audio/course-examples/2eabb6b31056679c43131287.mp3"},{"text":"By junior year, students majoring in physics are committed to learning, she says.","translation":"她说，到了大三，物理专业的学生都已全身心投入学习。","source":"（2024年真题·阅读理解·Passage One）","speechText":"By junior year, students majoring in physics are committed to learning, she says.","annotations":[],"targetForms":[],"audio":"audio/course-examples/021b1f533b7ff67ab011c604.mp3"},{"text":"Temperatures are warming（warm的-ing形式） and daylight lasts longer.","translation":"气温正在回升，白昼也越来越长。","source":"（2023年真题·阅读理解·Passage One）","speechText":"Temperatures are warming and daylight lasts longer.","annotations":[{"text":"（warm的-ing形式）","start":24,"end":37,"anchor":"warming"}],"targetForms":["warming"],"audio":"audio/course-examples/3ebc9959da3baf42e31072ff.mp3"},{"text":"When you go to university to study for a degree, you have decided to study professionally, rather than as an amateur; so being a student is now your profession for at least the next four years.","translation":"当你到大学攻读学位时，你就决定了要以专业而非业余的态度学习；因此，至少在接下来的四年里，当学生就是你的职业。","source":"（2017年真题·阅读理解·Passage Two）","speechText":"When you go to university to study for a degree, you have decided to study professionally, rather than as an amateur; so being a student is now your profession for at least the next four years.","annotations":[],"targetForms":[],"audio":"audio/course-examples/b9077f2caa2e3cec6eee1756.mp3"},{"text":"The question is, how do we arrange them in a fair way with the public support?","translation":"问题是，我们该如何在获得公众支持的前提下，公平地安排这些事项？","source":"（2024年真题·阅读理解·Passage Two）","speechText":"The question is, how do we arrange them in a fair way with the public support?","annotations":[],"targetForms":[],"audio":"audio/course-examples/53cd5e9179fe1a25c68837d0.mp3"},{"text":"There seems to be everything on the network.","translation":"网络上似乎什么都有。","source":"（2017年真题·阅读理解·Passage One）","speechText":"There seems to be everything on the network.","annotations":[],"targetForms":[],"audio":"audio/course-examples/eff2c92ce48038385f67495c.mp3"},{"text":"Less than a dozen of her poems（poem的复数形式） were published during her lifetime.","translation":"她生前发表的诗歌不到十二首。","source":"（2015年真题·阅读理解·Passage Three）","speechText":"Less than a dozen of her poems were published during her lifetime.","annotations":[{"text":"（poem的复数形式）","start":30,"end":41,"anchor":"poems"}],"targetForms":["poems"],"audio":"audio/course-examples/f8aea5f00c689a9b09cc1c63.mp3"},{"text":"The gardener will harvest more vegetables（vegetable的复数形式） in fall.","translation":"园丁将在秋天收获更多蔬菜。","source":"（2023年真题·阅读理解·Passage One·第12题选项）","speechText":"The gardener will harvest more vegetables in fall.","annotations":[{"text":"（vegetable的复数形式）","start":41,"end":57,"anchor":"vegetables"}],"targetForms":["vegetables"],"audio":"audio/course-examples/a166633343eb23ccc605aaa2.mp3"}]},"23":{"vocabulary":[{"word":"promise","ipa":"/ˈprɒmɪs/","partsOfSpeech":"v./n.","meaning":"答应，允诺，希望，前途"},{"word":"model","ipa":"/ˈmɒd(ə)l/","partsOfSpeech":"n./v./adj.","meaning":"模型，模范，模特，做模型；模范的；模型的"},{"word":"industry","ipa":"/ˈɪndəstri/","partsOfSpeech":"n.","meaning":"工业，产业，行业，勤奋"},{"word":"former","ipa":"/ˈfɔːmə(r)/","partsOfSpeech":"adj./n.","meaning":"前任的，以前的，前者"},{"word":"war","ipa":"/wɔː(r)/","partsOfSpeech":"n./v.","meaning":"战争，冲突，斗争，作战"},{"word":"wild","ipa":"/waɪld/","partsOfSpeech":"adj./n./adv.","meaning":"野生的，野蛮的，狂热的，荒野；不受控制地、自然地"},{"word":"addict","ipa":"/ˈædɪkt/ (n.); /əˈdɪkt/ (v.)","partsOfSpeech":"n./v.","meaning":"入迷的人，瘾君子，使沉溺，使上瘾"},{"word":"barely","ipa":"/ˈbeəli/","partsOfSpeech":"adv.","meaning":"仅仅，勉强，几乎不，刚刚"},{"word":"occupation","ipa":"/ˌɒkjuˈpeɪʃ(ə)n/","partsOfSpeech":"n.","meaning":"职业，占领，消遣，居住"},{"word":"radio","ipa":"/ˈreɪdiəʊ/","partsOfSpeech":"n./v.","meaning":"收音机，无线电，用无线电发送"},{"word":"restore","ipa":"/rɪˈstɔː(r)/","partsOfSpeech":"v.","meaning":"恢复，修复，归还，复职"},{"word":"temporary","ipa":"/ˈtemprəri/","partsOfSpeech":"adj./n.","meaning":"暂时的，临时的，临时工"},{"word":"air","ipa":"/eə(r)/","partsOfSpeech":"n.","meaning":"空气，天空"},{"word":"acknowledge","ipa":"/əkˈnɒlɪdʒ/","partsOfSpeech":"v.","meaning":"承认，答谢，认可"},{"word":"complaint","ipa":"/kəmˈpleɪnt/","partsOfSpeech":"n.","meaning":"抱怨，怨言，控告"}],"examples":[{"text":"Networks hold great promise; however, it’s also home to people who mean to hurt others or use their technical knowledge to steal from them.","translation":"网络蕴藏着巨大的前景；然而，它也是一些人的活动场所，这些人意图伤害他人，或利用技术知识窃取他人的财物。","source":"（2017年真题·英译汉）","speechText":"Networks hold great promise; however, it’s also home to people who mean to hurt others or use their technical knowledge to steal from them.","annotations":[],"targetForms":[],"audio":"audio/course-examples/2581e5f1da79b48c1486edf7.mp3"},{"text":"If phones are not recycled, more and more of these metals need to be mined to keep up with the demand for new models（model的复数形式）.","translation":"如果手机没有被回收，为了满足人们对新机型的需求，就需要开采越来越多的这类金属。","source":"（2022年真题·完形填空）","speechText":"If phones are not recycled, more and more of these metals need to be mined to keep up with the demand for new models.","annotations":[{"text":"（model的复数形式）","start":116,"end":128,"anchor":"models"}],"targetForms":["models"],"audio":"audio/course-examples/1e1545e8e90bfbdc01661b50.mp3"},{"text":"By law, children less than 16 years old cannot work in many industries（industry的复数形式）.","translation":"法律规定，不满十六岁的儿童不能在许多行业工作。","source":"（2016年真题·阅读理解·Passage Three）","speechText":"By law, children less than 16 years old cannot work in many industries.","annotations":[{"text":"（industry的复数形式）","start":70,"end":85,"anchor":"industries"}],"targetForms":["industries"],"audio":"audio/course-examples/ba1915c44f5bf190074179a0.mp3"},{"text":"The former represents a kind of comprehension which is written in the text.","translation":"前者指的是一种以文字形式表达的理解。","source":"（2016年真题·阅读理解·Passage Two）","speechText":"The former represents a kind of comprehension which is written in the text.","annotations":[],"targetForms":[],"audio":"audio/course-examples/b74e579c5aa9b57e1f69af7d.mp3"},{"text":"It was during the Civil War that Mark Twain's life as a writer started.","translation":"马克·吐温正是在美国内战期间开始了作家生涯。","source":"（2013年真题·阅读理解·Passage Three）","speechText":"It was during the Civil War that Mark Twain's life as a writer started.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e08a94a6205bc84773e54d44.mp3"},{"text":"Wild as these notions may sound, every one has its advocates (and opposers) in the scientific community as well as its striking commercial application.","translation":"尽管这些想法听起来可能很疯狂，但每一种想法在科学界都有自己的支持者（和反对者），而且都有引人注目的商业应用。","source":"（2019年真题·阅读理解·Passage Two）","speechText":"Wild as these notions may sound, every one has its advocates (and opposers) in the scientific community as well as its striking commercial application.","annotations":[],"targetForms":[],"audio":"audio/course-examples/c549fbefdd884bedcb004c96.mp3"},{"text":"Because children may become addicted（addict的过去分词） to computer games.","translation":"因为孩子可能会沉迷于电脑游戏。","source":"（2017年·阅读理解·Passage One）","speechText":"Because children may become addicted to computer games.","annotations":[{"text":"（addict的过去分词）","start":36,"end":49,"anchor":"addicted"}],"targetForms":["addicted"],"audio":"audio/course-examples/920460cec55f8b72cf521f92.mp3"},{"text":"It was so hard to sell a story that I barely made enough to eat.","translation":"故事很难卖出去，我赚到的钱几乎只够糊口。","source":"（2015年真题·阅读理解·Passage One）","speechText":"It was so hard to sell a story that I barely made enough to eat.","annotations":[],"targetForms":[],"audio":"audio/course-examples/53d0681397144f49a11f7b11.mp3"},{"text":"A class is said rather vaguely to consist of a group of persons sharing similar occupations（occupation的复数形式） and incomes, and as a consequence similar life-styles and beliefs.","translation":"一种相当笼统的说法是：阶级由一群职业和收入相近、因而生活方式和信念也相近的人组成。","source":"（2014年真题·词汇语法·第49题）","speechText":"A class is said rather vaguely to consist of a group of persons sharing similar occupations and incomes, and as a consequence similar life-styles and beliefs.","annotations":[{"text":"（occupation的复数形式）","start":91,"end":108,"anchor":"occupations"}],"targetForms":["occupations"],"audio":"audio/course-examples/49e1fd8a4b3a6da9a85e66f7.mp3"},{"text":"Many radio stations provide the same sort of service — they announce who’s driving where, when, how many riders they will take and what the expenses will be.","translation":"许多广播电台也提供同类服务：它们会播报谁在什么时候开车去哪里、能搭载多少乘客，以及费用是多少。","source":"（2015年真题·阅读理解·Passage Two）","speechText":"Many radio stations provide the same sort of service — they announce who’s driving where, when, how many riders they will take and what the expenses will be.","annotations":[],"targetForms":[],"audio":"audio/course-examples/2f57f9d97b8ba965dc135fdc.mp3"},{"text":"His aim was to restore pride in being black and to inspire black Americans to campaign for equal rights.","translation":"他的目标是让黑人重新以自己的身份为荣，并激励美国黑人为争取平等权利而努力。","source":"（2014年真题·词汇语法·第48题）","speechText":"His aim was to restore pride in being black and to inspire black Americans to campaign for equal rights.","annotations":[],"targetForms":[],"audio":"audio/course-examples/996709929f6bfe62a797cc59.mp3"},{"text":"For example, they may offer you a temporary contract first as a consultant.","translation":"例如，它们可能先向你提供一份临时合同，让你以顾问身份工作。","source":"（2020年真题·阅读理解·Passage One）","speechText":"For example, they may offer you a temporary contract first as a consultant.","annotations":[],"targetForms":[],"audio":"audio/course-examples/dfd3a9084fa62971ce223832.mp3"},{"text":"Then, there is the horizontal movement of air across the planet.","translation":"另外，还有空气在地球表面的水平流动。","source":"（2026年真题·阅读理解·Passage Three）","speechText":"Then, there is the horizontal movement of air across the planet.","annotations":[],"targetForms":[],"audio":"audio/course-examples/d0ffc8f8fcdd7dde952e8776.mp3"},{"text":"You should try to acknowledge a person who works hard.","translation":"你应该尽量去认可一个努力工作的人。","source":"（2023年真题·选句填空·完整句选项）","speechText":"You should try to acknowledge a person who works hard.","annotations":[],"targetForms":[],"audio":"audio/course-examples/658b01c34a1b0ac7d954df24.mp3"},{"text":"Bob’s constant complaints（complaint的复数形式） and criticism made Sandy confused and irritated.","translation":"Bob不停地抱怨和批评，让Sandy感到困惑而恼火。","source":"（2018年真题·阅读理解·Passage one）","speechText":"Bob’s constant complaints and criticism made Sandy confused and irritated.","annotations":[{"text":"（complaint的复数形式）","start":25,"end":41,"anchor":"complaints"}],"targetForms":["complaints"],"audio":"audio/course-examples/ae2e6ffd32fc424655171ba2.mp3"}]},"24":{"vocabulary":[{"word":"memory","ipa":"/ˈmeməri/","partsOfSpeech":"n.","meaning":"记忆，记忆力，回忆，内存"},{"word":"regular","ipa":"/ˈreɡjələ(r)/","partsOfSpeech":"adj.","meaning":"规则的，定期的，经常的"},{"word":"ease","ipa":"/iːz/","partsOfSpeech":"n./v.","meaning":"容易，舒适，减轻，缓和"},{"word":"for","ipa":"/fɔː(r); fə(r)/","partsOfSpeech":"prep./conj.","meaning":"为，为了，因为，对于"},{"word":"era","ipa":"/ˈɪərə/","partsOfSpeech":"n.","meaning":"时代，年代，纪元"},{"word":"drought","ipa":"/draʊt/","partsOfSpeech":"n.","meaning":"干旱，旱灾，缺乏"},{"word":"external","ipa":"/ɪkˈstɜːn(ə)l/","partsOfSpeech":"adj./n.","meaning":"外部的，外面的，外表，外部事物"},{"word":"dirty","ipa":"/ˈdɜːti/","partsOfSpeech":"adj./v.","meaning":"脏的，下流的，卑鄙的，弄脏"},{"word":"oppose","ipa":"/əˈpəʊz/","partsOfSpeech":"v.","meaning":"反对，反抗，对抗，抵制"},{"word":"symbol","ipa":"/ˈsɪmb(ə)l/","partsOfSpeech":"n.","meaning":"象征；符号；标志"},{"word":"acquire","ipa":"/əˈkwaɪə(r)/","partsOfSpeech":"v.","meaning":"获得；习得"},{"word":"obvious","ipa":"/ˈɒbviəs/","partsOfSpeech":"adj.","meaning":"明显的；显而易见的"},{"word":"stand","ipa":"/stænd/","partsOfSpeech":"v./n.","meaning":"站立；忍受；立场"},{"word":"forecast","ipa":"/ˈfɔːkɑːst/","partsOfSpeech":"v./n.","meaning":"预测；预报"},{"word":"positive","ipa":"/ˈpɒzətɪv/","partsOfSpeech":"adj./n.","meaning":"积极的；确定的；正数"}],"examples":[{"text":"These are usually signs of mild forgetfulness, not serious memory problems.","translation":"这些通常只是轻度健忘的表现，而不是严重的记忆问题。","source":"（2019年配套材料·选句填空）","speechText":"These are usually signs of mild forgetfulness, not serious memory problems.","annotations":[],"targetForms":[],"audio":"audio/course-examples/7518d84750d0fc74d7714cd0.mp3"},{"text":"Regular exercise can reduce the damage that long-term stress may have on our body.","translation":"经常锻炼可以减轻长期压力可能对身体造成的伤害。","source":"（2020年真题·翻译）","speechText":"Regular exercise can reduce the damage that long-term stress may have on our body.","annotations":[],"targetForms":[],"audio":"audio/course-examples/88a388592412665033290dc7.mp3"},{"text":"The emotional problems can be eased（ease的过去分词形式） by supportive friends and family.","translation":"有支持自己的朋友和家人，情绪问题便能得到缓解。","source":"（2019年配套材料·选句填空）","speechText":"The emotional problems can be eased by supportive friends and family.","annotations":[{"text":"（ease的过去分词形式）","start":35,"end":48,"anchor":"eased"}],"targetForms":["eased"],"audio":"audio/course-examples/e218100425e2c2b2f8593e41.mp3"},{"text":"For young people overseas, Chinese games are becoming a new form of digital cultural experience. ","translation":"对于海外的年轻人来说，中国游戏正成为一种新的数字文化体验形式。","source":"（2026年真题·翻译）","speechText":"For young people overseas, Chinese games are becoming a new form of digital cultural experience.","annotations":[],"targetForms":[],"audio":"audio/course-examples/3ada4aecd722d8b7480926b8.mp3"},{"text":"This is the era of women’s liberation.","translation":"这是妇女解放的时代。","source":"（2013年真题·阅读理解·Passage Two）","speechText":"This is the era of women’s liberation.","annotations":[],"targetForms":[],"audio":"audio/course-examples/0c9844086efe055206aaf2f6.mp3"},{"text":"That is to say, it is not a drought-tolerant plant","translation":"也就是说，它不是耐旱植物。","source":"（2014年配套材料·选句填空）","speechText":"That is to say, it is not a drought-tolerant plant","annotations":[],"targetForms":[],"audio":"audio/course-examples/36db9b712114db4a89f10abf.mp3"},{"text":"Instead of looking for external things to provide happiness in our lives, we must strive to find the joy within.","translation":"我们不应向外寻求能带来幸福的事物，而应努力在内心寻找快乐。","source":"（2018年配套材料·选词填空）","speechText":"Instead of looking for external things to provide happiness in our lives, we must strive to find the joy within.","annotations":[],"targetForms":[],"audio":"audio/course-examples/c713dc7a45226964466ba186.mp3"},{"text":"People who like to garden may be ready to get their hands dirty and start clearing the ground for new plantings.","translation":"喜欢园艺的人可能已经准备好弄脏自己的手，开始清理地面，种植新的植物。","source":"（2023年真题·阅读理解·Passage One）","speechText":"People who like to garden may be ready to get their hands dirty and start clearing the ground for new plantings.","annotations":[],"targetForms":[],"audio":"audio/course-examples/a42a2453e79fafd7b386e56e.mp3"},{"text":"We call this a “process” conversation as opposed（oppose的过去分词形式） to a “content” conversation.","translation":"我们把这称为“过程型”对话，以区别于“内容型”对话。","source":"（2016年真题·阅读理解·Passage Two）","speechText":"We call this a “process” conversation as opposed to a “content” conversation.","annotations":[{"text":"（oppose的过去分词形式）","start":48,"end":63,"anchor":"opposed"}],"targetForms":["opposed"],"audio":"audio/course-examples/92d0d909f565b00440e4f1e2.mp3"},{"text":"You and an opponent each throw one of three hand symbols（symbol的复数形式）.","translation":"你和对手各自出示三种手势中的一种。","source":"（2021年真题·阅读理解·Passage One）","speechText":"You and an opponent each throw one of three hand symbols.","annotations":[{"text":"（symbol的复数形式）","start":56,"end":69,"anchor":"symbols"}],"targetForms":["symbols"],"audio":"audio/course-examples/49dad89de0ec6755e39f4529.mp3"},{"text":"People collect things to acquire historical significance.","translation":"人们收集物品，以获得历史意义。","source":"（2022年阅读 Passage One）","speechText":"People collect things to acquire historical significance.","annotations":[],"targetForms":[],"audio":"audio/course-examples/9dd6e0532601c5e2039a9d90.mp3"},{"text":"Today the need for a new auxiliary language like Esperanto seems less obvious.","translation":"如今，人们似乎不再那么明显地需要世界语这样的新辅助语言了。","source":"（2014年真题·阅读理解·Passage Two）","speechText":"Today the need for a new auxiliary language like Esperanto seems less obvious.","annotations":[],"targetForms":[],"audio":"audio/course-examples/80944a2b95ae3135f99b70fb.mp3"},{"text":"Don't stand there doing nothing.","translation":"别站在那里无所事事。","source":"（2019年真题·词汇语法·第22题）","speechText":"Don't stand there doing nothing.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e5d6df1f5aea20ddb966d1c8.mp3"},{"text":"Should we use genetic forecasting（forecast的-ing形式） to pre-eliminate “unfit” babies?","translation":"我们应该利用基因预测，提前排除那些“不合适”的婴儿吗？","source":"（2019年真题·阅读理解·Passage Two）","speechText":"Should we use genetic forecasting to pre-eliminate “unfit” babies?","annotations":[{"text":"（forecast的-ing形式）","start":33,"end":50,"anchor":"forecasting"}],"targetForms":["forecasting"],"audio":"audio/course-examples/67afc7b5dd9d6ab984a0ced6.mp3"},{"text":"Rather than thinking negatively, you should stay positive.","translation":"你应该保持积极，而不是消极地思考。","source":"（2021年真题·选句填空）","speechText":"Rather than thinking negatively, you should stay positive.","annotations":[],"targetForms":[],"audio":"audio/course-examples/9dd8490142b238e574a8ab97.mp3"}]},"25":{"vocabulary":[{"word":"prepare","ipa":"/prɪˈpeə(r)/","partsOfSpeech":"v.","meaning":"准备；预备"},{"word":"consist","ipa":"/kənˈsɪst/","partsOfSpeech":"v.","meaning":"由…组成；在于；存在于"},{"word":"proud","ipa":"/praʊd/","partsOfSpeech":"adj.","meaning":"骄傲的；自豪的"},{"word":"option","ipa":"/ˈɒpʃ(ə)n/","partsOfSpeech":"n.","meaning":"选择；选项；选修课"},{"word":"material","ipa":"/məˈtɪəriəl/","partsOfSpeech":"n./adj.","meaning":"材料；物质；物质的"},{"word":"pick","ipa":"/pɪk/","partsOfSpeech":"v./n.","meaning":"挑选；采摘；捡起"},{"word":"elsewhere","ipa":"/ˌelsˈweə(r)/","partsOfSpeech":"adv.","meaning":"在别处；去别处"},{"word":"fund","ipa":"/fʌnd/","partsOfSpeech":"n./v.","meaning":"资金；基金；资助"},{"word":"present","ipa":"/ˈprez(ə)nt/ (n./adj.); /prɪˈzent/ (v.)","partsOfSpeech":"n./adj./v.","meaning":"礼物；现在的；出席的；呈现；到场"},{"word":"suppose","ipa":"/səˈpəʊz/","partsOfSpeech":"v.","meaning":"假设；认为；料想；推断"},{"word":"facility","ipa":"/fəˈsɪləti/","partsOfSpeech":"n.","meaning":"设施；设备；天赋；才能"},{"word":"rude","ipa":"/ruːd/","partsOfSpeech":"adj.","meaning":"粗鲁的；无礼的"},{"word":"right","ipa":"/raɪt/","partsOfSpeech":"adj./adv./n./v.","meaning":"正确的；右边的；正好；权利；右边；矫正"},{"word":"spend","ipa":"/spend/","partsOfSpeech":"v./n.","meaning":"花费；度过；花销；预算"},{"word":"quite","ipa":"/kwaɪt/","partsOfSpeech":"adv.","meaning":"相当；很；完全"}],"examples":[{"text":"Luck and chance play a part, but \"you have to be prepared（prepare的过去分词形式） and have a strategy,\" he says.","translation":"他说，运气和偶然性确实会起作用，但“你必须做好准备，并制定策略”。","source":"（2021年真题·阅读理解·Passage One）","speechText":"Luck and chance play a part, but \"you have to be prepared and have a strategy,\" he says.","annotations":[{"text":"（prepare的过去分词形式）","start":57,"end":73,"anchor":"prepared"}],"targetForms":["prepared"],"audio":"audio/course-examples/a7452113a0dd55174e9d63ba.mp3"},{"text":"Also, happiness consists（consist的第三人称单数形式） in contentment.","translation":"此外，幸福在于知足。","source":"（2014年配套材料·英译汉）","speechText":"Also, happiness consists in contentment.","annotations":[{"text":"（consist的第三人称单数形式）","start":24,"end":42,"anchor":"consists"}],"targetForms":["consists"],"audio":"audio/course-examples/c4d5e385c9c2d4f592e1ddf5.mp3"},{"text":"We are so proud of her.","translation":"我们为她感到非常骄傲。","source":"（2013年配套材料·选词填空）","speechText":"We are so proud of her.","annotations":[],"targetForms":[],"audio":"audio/course-examples/d16c0baa84f9dcd0476df3cf.mp3"},{"text":"There are many options（option的复数形式） one can try to relieve cold.","translation":"人们可以尝试许多方法来缓解感冒症状。","source":"（2015年配套材料·选句填空·完整句选项）","speechText":"There are many options one can try to relieve cold.","annotations":[{"text":"（option的复数形式）","start":22,"end":35,"anchor":"options"}],"targetForms":["options"],"audio":"audio/course-examples/02ac5026a2fb374cccbabe39.mp3"},{"text":"Reusable containers require more energy and materials（material的复数形式） to produce.","translation":"可重复使用的容器在生产过程中需要更多的能源和材料。","source":"（2026年真题·完形填空）","speechText":"Reusable containers require more energy and materials to produce.","annotations":[{"text":"（material的复数形式）","start":53,"end":68,"anchor":"materials"}],"targetForms":["materials"],"audio":"audio/course-examples/2eabb6b31056679c43131287.mp3"},{"text":"Making your voice heard is important, too, but try to pick your battles.","translation":"让自己的声音被听见也很重要，但尽量选择正确的时机和方式。","source":"（2013年配套材料·选句填空·完整句选项）","speechText":"Making your voice heard is important, too, but try to pick your battles.","annotations":[],"targetForms":[],"audio":"audio/course-examples/079106cb1f78b38440801e81.mp3"},{"text":"The account is attached to a prepaid card that is currently available in Sweden only, but expected to launch elsewhere in Europe in 2020.","translation":"该账户绑定一张预付卡，目前仅在瑞典提供，预计将于2020年在欧洲其他地区推出。","source":"（2020年真题·阅读理解·Passage Three）","speechText":"The account is attached to a prepaid card that is currently available in Sweden only, but expected to launch elsewhere in Europe in 2020.","annotations":[],"targetForms":[],"audio":"audio/course-examples/d9002d0b85cc9dc708ecdfe5.mp3"},{"text":"The study, which is funded（fund的过去分词形式） by the British Heart Foundation, is led by Dr Graham Burdge, a Professor of Cardiovascular Science.","translation":"这项研究由英国心脏基金会资助，并由心血管科学教授Graham Burdge博士领导。","source":"（2014年配套材料·选词填空）","speechText":"The study, which is funded by the British Heart Foundation, is led by Dr Graham Burdge, a Professor of Cardiovascular Science.","annotations":[{"text":"（fund的过去分词形式）","start":26,"end":39,"anchor":"funded"}],"targetForms":["funded"],"audio":"audio/course-examples/4857db641599ba87a83ddcf9.mp3"},{"text":"A man who is dissatisfied with his present condition is never happy.","translation":"一个不满于自己现状的人永远不会快乐。","source":"（2014年配套材料·英译汉）","speechText":"A man who is dissatisfied with his present condition is never happy.","annotations":[],"targetForms":[],"audio":"audio/course-examples/968360312a2d35fa269ff05c.mp3"},{"text":"Suppose you are Li Hua.","translation":"假设你是李华。","source":"（2026年·写作）","speechText":"Suppose you are Li Hua.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e8d344b9a543041252b8d89f.mp3"},{"text":"We can find many sports facilities（facility的复数形式） on the playground of this primary school.","translation":"我们可以在这所小学的操场上看到许多体育设施。","source":"（2018年真题·词汇语法·第29题）","speechText":"We can find many sports facilities on the playground of this primary school.","annotations":[{"text":"（facility的复数形式）","start":34,"end":49,"anchor":"facilities"}],"targetForms":["facilities"],"audio":"audio/20261016-list1/examples/06.mp3"},{"text":"We don't mean to be rude or thoughtless----so why do we act this way when we really want to help?","translation":"我们并不是有意粗鲁或考虑不周；既然真心想帮忙，为什么却会这样做呢？","source":"（2019年真题·阅读理解·Passage One）","speechText":"We don't mean to be rude or thoughtless----so why do we act this way when we really want to help?","annotations":[],"targetForms":[],"audio":"audio/course-examples/775aa74e60c4f623bbb4f1b9.mp3"},{"text":"Everything would have been all right.","translation":"本来一切都会很顺利的。","source":"（2017年真题·词汇语法·第30题）","speechText":"Everything would have been all right.","annotations":[],"targetForms":[],"audio":"audio/course-examples/52a7a11202c85facc0920007.mp3"},{"text":"At most universities teachers can give students advice on how to spend their money.","translation":"在大多数大学，老师能够就如何支配金钱给学生提供建议。","source":"（2021年真题·完形填空）","speechText":"At most universities teachers can give students advice on how to spend their money.","annotations":[],"targetForms":[],"audio":"audio/course-examples/518b8c587a301fac5dcdfed5.mp3"},{"text":"The reason was quite simple: Men had not invented the week.","translation":"原因很简单：那时，人类还没有发明“星期”这种计时方式。","source":"（2019年真题·阅读理解·Passage Three）","speechText":"The reason was quite simple: Men had not invented the week.","annotations":[],"targetForms":[],"audio":"audio/course-examples/618b99baa7444c6b94bc533c.mp3"}]},"26":{"vocabulary":[{"word":"race","ipa":"/reɪs/","partsOfSpeech":"n./v.","meaning":"比赛；种族；赛跑"},{"word":"medium","ipa":"/ˈmiːdiəm/","partsOfSpeech":"adj./n.","meaning":"中等的；半熟的；媒介；中号；方法手段"},{"word":"most","ipa":"/məʊst/","partsOfSpeech":"det./adv.","meaning":"最多；大多数；最"},{"word":"officer","ipa":"/ˈɒfɪsə(r)/","partsOfSpeech":"n.","meaning":"军官；官员；警官"},{"word":"nurse","ipa":"/nɜːs/","partsOfSpeech":"n./v.","meaning":"护士；护理；照料"},{"word":"such","ipa":"/sʌtʃ/","partsOfSpeech":"det./pron./adv.","meaning":"这样的；如此的；如此"},{"word":"badly","ipa":"/ˈbædli/","partsOfSpeech":"adv.","meaning":"糟糕地；严重地；非常；负面地"},{"word":"topic","ipa":"/ˈtɒpɪk/","partsOfSpeech":"n.","meaning":"话题；主题"},{"word":"taxi","ipa":"/ˈtæksi/","partsOfSpeech":"n.","meaning":"出租车"},{"word":"cow","ipa":"/kaʊ/","partsOfSpeech":"n.","meaning":"奶牛；母牛"},{"word":"husband","ipa":"/ˈhʌzbənd/","partsOfSpeech":"n.","meaning":"丈夫"},{"word":"actor","ipa":"/ˈæktə(r)/","partsOfSpeech":"n.","meaning":"男演员"},{"word":"dictionary","ipa":"/ˈdɪkʃən(ə)ri/","partsOfSpeech":"n.","meaning":"词典；字典"},{"word":"letter","ipa":"/ˈletə(r)/","partsOfSpeech":"n.","meaning":"信；字母；文学；正式文书"},{"word":"supermarket","ipa":"/ˈsuːpəmɑːkɪt/","partsOfSpeech":"n.","meaning":"超市"}],"examples":[{"text":"Should we attempt to eliminate \"inferior\" people and breed a \"super race\"?","translation":"我们应该尝试消灭所谓“劣等”的人，并培育所谓“超级种族”吗？","source":"（2019年真题·阅读理解·Passage Two）","speechText":"Should we attempt to eliminate \"inferior\" people and breed a \"super race\"?","annotations":[],"targetForms":[],"audio":"audio/course-examples/4bbbb8d47cf4b2b57bc4d597.mp3"},{"text":"Choose your medium and write an interesting bio（简历）.","translation":"选择你的媒介，撰写一段有趣的个人简介","source":"（2020年真题·阅读理解·Passage Two）","speechText":"Choose your medium and write an interesting bio.","annotations":[{"text":"（简历）","start":47,"end":51,"anchor":"bio"}],"targetForms":[],"audio":"audio/course-examples/c3c23967196d712054140084.mp3"},{"text":"In reality, most people expect much less.","translation":"事实上，大多数人的期待远没有那么高。","source":"（2026年真题·阅读理解·Passage One）","speechText":"In reality, most people expect much less.","annotations":[],"targetForms":[],"audio":"audio/course-examples/6a2a4c64de5cafdb58550a76.mp3"},{"text":"Still, they have earned the support of important safety advocates, including Jonathan Adkins, the chief executive officer of the Governors Highway Safety Association.","translation":"不过，它们已经获得了一些重要安全倡导者的支持，其中包括州长公路安全协会首席执行官Jonathan Adkins。","source":"（2024年真题·阅读理解·Passage Two）","speechText":"Still, they have earned the support of important safety advocates, including Jonathan Adkins, the chief executive officer of the Governors Highway Safety Association.","annotations":[],"targetForms":[],"audio":"audio/course-examples/56849352044a39b3dae3a778.mp3"},{"text":"If you do get sick, the best place for you is at home, where you can nurse yourself back to health.","translation":"如果你确实生病了，最适合你的地方就是家里，你可以在那里照顾自己，恢复健康。","source":"（2015年配套材料·选句填空）","speechText":"If you do get sick, the best place for you is at home, where you can nurse yourself back to health.","annotations":[],"targetForms":[],"audio":"audio/course-examples/62324f77f689cb547d935651.mp3"},{"text":"Jessica Damiano is one such expert.","translation":"Jessica Damiano就是这样一位专家。","source":"（2023年真题·阅读理解·Passage One）","speechText":"Jessica Damiano is one such expert.","annotations":[],"targetForms":[],"audio":"audio/course-examples/fa40d8a29cb8a183fc7de0fb.mp3"},{"text":"because of her badly looking sneakers.","translation":"因为她的运动鞋看起来太糟糕了。","source":"（2017年·阅读理解·Passage Three）","speechText":"because of her badly looking sneakers.","annotations":[],"targetForms":[],"audio":"audio/course-examples/6a9249d0667ce6eb35e161cf.mp3"},{"text":"Also ensure that you keep posting and following a specific topic.","translation":"还要确保你持续发布内容，并始终围绕某个特定主题。","source":"（2020年真题·阅读理解·Passage Two）","speechText":"Also ensure that you keep posting and following a specific topic.","annotations":[],"targetForms":[],"audio":"audio/course-examples/1f22ac0292ad32bc9d0ecb2e.mp3"},{"text":"She grabbed me by the arm and pulled me out of the taxi.","translation":"她一把抓住我的胳膊，把我从出租车里拉了出来。","source":"（2015年真题·词汇语法·第48题）","speechText":"She grabbed me by the arm and pulled me out of the taxi.","annotations":[],"targetForms":[],"audio":"audio/course-examples/363fe4d5191d3541a4ee137f.mp3"},{"text":"Should we breed people with cow-like stomachs so they can digest grass and hay, thereby relieving the food problem by modifying us to eat lower down on the food chain?","translation":"我们是否应该培育出像牛一样有胃的人，让他们能够消化草和干草，从而通过改变人类在食物链中的位置来解决粮食问题？","source":"（2019年·阅读理解·Passage Two）","speechText":"Should we breed people with cow-like stomachs so they can digest grass and hay, thereby relieving the food problem by modifying us to eat lower down on the food chain?","annotations":[],"targetForms":[],"audio":"audio/course-examples/f146fbc787ba5ac31610fa36.mp3"},{"text":"Much family quarrelling ends when husbands（husband的复数形式） and wives realize what these energy cycles mean, and which cycle each member of the family has.","translation":"许多家庭争吵的结束，源于夫妻们意识到这些能量循环的含义，以及每个家庭成员所处的特定循环。","source":"（2018年真题·阅读理解·Passage Two）","speechText":"Much family quarrelling ends when husbands and wives realize what these energy cycles mean, and which cycle each member of the family has.","annotations":[{"text":"（husband的复数形式）","start":42,"end":56,"anchor":"husbands"}],"targetForms":["husbands"],"audio":"audio/course-examples/0d651811a1545b0be449ad6b.mp3"},{"text":"An actor named Steve Roach thinks that people collect things to remember their childhood.","translation":"一位名叫Steve Roach的男演员认为，人们收藏物品是为了回忆童年。","source":"（2022年真题·阅读理解·Passage One）","speechText":"An actor named Steve Roach thinks that people collect things to remember their childhood.","annotations":[],"targetForms":[],"audio":"audio/course-examples/4e20bff60437db8ad03ca7d6.mp3"},{"text":"Happiness, according to the Oxford English dictionary, is based on luck or good fortune.","translation":"根据《牛津英语词典》，幸福建立在运气或好运的基础上。","source":"（2018年配套材料·选词填空）","speechText":"Happiness, according to the Oxford English dictionary, is based on luck or good fortune.","annotations":[],"targetForms":[],"audio":"audio/course-examples/70ce22277efa57d4e01e0e25.mp3"},{"text":"But then we got an official letter and we were blown away.","translation":"但后来我们收到了一封正式信函，感到非常震惊。","source":"（2013年配套材料·选词填空）","speechText":"But then we got an official letter and we were blown away.","annotations":[],"targetForms":[],"audio":"audio/course-examples/a375a2a6a9ad8e9a85ae72e0.mp3"},{"text":"Convenience foods from the supermarket simplify shopping and cooking.","translation":"超市里的方便食品让购物和做饭变得更简单。","source":"（2013年真题·阅读理解·Passage Two）","speechText":"Convenience foods from the supermarket simplify shopping and cooking.","annotations":[],"targetForms":[],"audio":"audio/course-examples/aea20befe427385288175099.mp3"}]},"27":{"vocabulary":[{"word":"that","ipa":"/ðæt/","partsOfSpeech":"det./pron./conj.","meaning":"那；那个"},{"word":"hundred","ipa":"/ˈhʌndrəd/","partsOfSpeech":"num./n.","meaning":"百；许多"},{"word":"medicine","ipa":"/ˈmedsn; ˈmedɪsn/","partsOfSpeech":"n.","meaning":"药；医学"},{"word":"program","ipa":"/ˈprəʊɡræm/","partsOfSpeech":"n./v.","meaning":"节目，程序，计划；编程"},{"word":"enhance","ipa":"/ɪnˈhɑːns/","partsOfSpeech":"v.","meaning":"提高；增强；加强"},{"word":"refrigerator","ipa":"/rɪˈfrɪdʒəreɪtə(r)/","partsOfSpeech":"n.","meaning":"冰箱；冷藏库"},{"word":"opposite","ipa":"/ˈɒpəzɪt/","partsOfSpeech":"adj./n./prep.","meaning":"相反的；对立面；在…对面"},{"word":"last","ipa":"/lɑːst/","partsOfSpeech":"adj./adv./v./n.","meaning":"最后的；上一次；持续；剩下的部分；末尾"},{"word":"surface","ipa":"/ˈsɜːfɪs/","partsOfSpeech":"n./v./adj.","meaning":"表面；表层；浮出水面；表面上的"},{"word":"predict","ipa":"/prɪˈdɪkt/","partsOfSpeech":"v.","meaning":"预测；预言；预告"},{"word":"psychology","ipa":"/saɪˈkɒlədʒi/","partsOfSpeech":"n.","meaning":"心理学；心理状态"},{"word":"improve","ipa":"/ɪmˈpruːv/","partsOfSpeech":"v.","meaning":"改善；提高；改进"},{"word":"restrict","ipa":"/rɪˈstrɪkt/","partsOfSpeech":"v.","meaning":"限制；约束；限定"},{"word":"total","ipa":"/ˈtəʊt(ə)l/","partsOfSpeech":"adj./n./v.","meaning":"总的；总数；共计"},{"word":"occur","ipa":"/əˈkɜː(r)/","partsOfSpeech":"v.","meaning":"发生；出现"}],"examples":[{"text":"At that time, he was working as a newspaperman in Nevada and California.","translation":"那时，他正在内华达州和加利福尼亚州从事新闻工作。","source":"（2013年·阅读理解·Passage Three）","speechText":"At that time, he was working as a newspaperman in Nevada and California.","annotations":[],"targetForms":[],"audio":"audio/course-examples/b5ab057b527449c5f95ae03b.mp3"},{"text":"Videos of her theatrical demonstrations have attracted hundreds（hundred的复数形式） of millions of views across social media platforms.","translation":"她那些富有戏剧性的演示视频，在各大社交媒体平台累计获得了数亿次观看。","source":"（2024年真题·阅读理解·Passage One）","speechText":"Videos of her theatrical demonstrations have attracted hundreds of millions of views across social media platforms.","annotations":[{"text":"（hundred的复数形式）","start":63,"end":77,"anchor":"hundreds"}],"targetForms":["hundreds"],"audio":"audio/course-examples/43da282e46b8a54ab6dcbafe.mp3"},{"text":"According to the American College of Sports Medicine, backward walking burns 40 percent more calories per minute than forward walking.","translation":"根据美国运动医学会的数据，倒着走每分钟消耗的热量比向前走多40%。","source":"（2025年真题·阅读理解·Passage Two）","speechText":"According to the American College of Sports Medicine, backward walking burns 40 percent more calories per minute than forward walking.","annotations":[],"targetForms":[],"audio":"audio/course-examples/95d176a1e9d10f260982fd88.mp3"},{"text":"The simplest solution is the use of programs（program的复数形式） which block offensive sites.","translation":"最简单的解决办法，是使用能够屏蔽不良网站的程序。","source":"（2017年真题·阅读理解·Passage One）","speechText":"The simplest solution is the use of programs which block offensive sites.","annotations":[{"text":"（program的复数形式）","start":44,"end":58,"anchor":"programs"}],"targetForms":["programs"],"audio":"audio/course-examples/e4a043b1f116ba0e9c7b21f5.mp3"},{"text":"So, exercise makes the body more efficient and enhances（enhance的第三人称单数形式） the body’s ability to respond to stress.","translation":"因此，运动能让身体更高效地运作，并增强身体应对压力的能力。","source":"（2020年真题·翻译）","speechText":"So, exercise makes the body more efficient and enhances the body’s ability to respond to stress.","annotations":[{"text":"（enhance的第三人称单数形式）","start":55,"end":73,"anchor":"enhances"}],"targetForms":["enhances"],"audio":"audio/course-examples/426db1768e69b73228376a88.mp3"},{"text":"When it is time for a meal, he will even lead his family over to the refrigerator to let them know that he is hungry!","translation":"一到吃饭时间，它甚至会带着家人走到冰箱旁，告诉他们自己饿了！","source":"（2025年真题·阅读理解·Passage One）","speechText":"When it is time for a meal, he will even lead his family over to the refrigerator to let them know that he is hungry!","annotations":[],"targetForms":[],"audio":"audio/course-examples/e642897f6a11c956c3ec2d7b.mp3"},{"text":"When the ground shakes and the building tips forward, the computer would force the building to shift in the opposite direction.","translation":"当地面震动、建筑向前倾斜时，计算机会迫使建筑向相反方向移动。","source":"（2014年真题·阅读理解·Passage Three）","speechText":"When the ground shakes and the building tips forward, the computer would force the building to shift in the opposite direction.","annotations":[],"targetForms":[],"audio":"audio/course-examples/53690679d4f20bc8c0df0590.mp3"},{"text":"Temperatures are warming and daylight lasts（last的第三人称单数形式） longer.","translation":"气温正在上升，日照时间也持续更长了。","source":"（2023年真题·阅读理解·Passage One）","speechText":"Temperatures are warming and daylight lasts longer.","annotations":[{"text":"（last的第三人称单数形式）","start":43,"end":58,"anchor":"lasts"}],"targetForms":["lasts"],"audio":"audio/course-examples/3ebc9959da3baf42e31072ff.mp3"},{"text":"However, though it likes wet conditions, it will eventually rot if the roots stay constantly below the surface of water.","translation":"然而，尽管它喜欢湿润的环境，如果根部一直浸在水面以下，最终还是会腐烂。","source":"（2014年配套材料·选句填空）","speechText":"However, though it likes wet conditions, it will eventually rot if the roots stay constantly below the surface of water.","annotations":[],"targetForms":[],"audio":"audio/course-examples/99cbc4365125765ab8421c56.mp3"},{"text":"predict the coming of an earthquake with accuracy ","translation":"准确预测地震的发生","source":"（2014年·阅读理解·Passage Three）","speechText":"predict the coming of an earthquake with accuracy","annotations":[],"targetForms":[],"audio":"audio/course-examples/b334cfb29e97c6ee43525ee3.mp3"},{"text":"Experts in media studies and online psychology have been examining the fake news phenomenon.","translation":"媒体研究和网络心理学领域的专家一直在研究假新闻现象。","source":"（2020年真题·选句填空）","speechText":"Experts in media studies and online psychology have been examining the fake news phenomenon.","annotations":[],"targetForms":[],"audio":"audio/course-examples/2d0237af087516c6d19a6e6d.mp3"},{"text":"Pinned to their drawing boards are blueprints for improved（improve的过去分词形式） quake-resistant buildings.","translation":"在他们的绘图板上，绘制着改善抗震建筑的蓝图。","source":"（2014年真题·阅读理解·Passage Three）","speechText":"Pinned to their drawing boards are blueprints for improved quake-resistant buildings.","annotations":[{"text":"（improve的过去分词形式）","start":58,"end":74,"anchor":"improved"}],"targetForms":["improved"],"audio":"audio/course-examples/f17e7050b7a28f484102fe6a.mp3"},{"text":"Damiano thinks that early mulching may restrict the growth of the plants.","translation":"Damiano认为，过早铺设覆盖物可能限制植物生长。","source":"（2023年真题·阅读理解·Passage One·阅读题补全）","speechText":"Damiano thinks that early mulching may restrict the growth of the plants.","annotations":[],"targetForms":[],"audio":"audio/course-examples/c17ef8df359792b3b556b64e.mp3"},{"text":"More than 45,000 kilograms of agricultural products at a total value of 400,000 yuan, were ordered within a few hours.","translation":"几小时内，人们订购了价值40万元、超过4.5万吨的农产品。","source":"（2020年真题·阅读理解·Passage Two）","speechText":"More than 45,000 kilograms of agricultural products at a total value of 400,000 yuan, were ordered within a few hours.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e08e7622dc0f1ecf8ae42ab7.mp3"},{"text":"This is usually when we are running into difficulties, when mismatch is occurring（occur的-ing形式） between expectations and meaning.","translation":"这通常是当我们遇到困难时，期望与意义之间出现不一致的情况。","source":"（2016年真题·阅读理解·Passage Two）","speechText":"This is usually when we are running into difficulties, when mismatch is occurring between expectations and meaning.","annotations":[{"text":"（occur的-ing形式）","start":81,"end":95,"anchor":"occurring"}],"targetForms":["occurring"],"audio":"audio/course-examples/69ad5d81fd0045b7e9166c11.mp3"}]},"28":{"vocabulary":[{"word":"method","ipa":"/ˈmeθəd/","partsOfSpeech":"n.","meaning":"方法；办法"},{"word":"north","ipa":"/nɔːθ/","partsOfSpeech":"n./adj./adv.","meaning":"北方；北方的；向北"},{"word":"withdraw","ipa":"/wɪðˈdrɔː/","partsOfSpeech":"v.","meaning":"撤回；取款；退出；罢工"},{"word":"refer","ipa":"/rɪˈfɜː(r)/","partsOfSpeech":"v.","meaning":"提到；涉及；将……送交给（以求获得帮助等）"},{"word":"far","ipa":"/fɑː(r)/","partsOfSpeech":"adj./adv.","meaning":"远的；遥远地"},{"word":"active","ipa":"/ˈæktɪv/","partsOfSpeech":"adj.","meaning":"积极的；活跃的；主动的"},{"word":"tough","ipa":"/tʌf/","partsOfSpeech":"adj.","meaning":"艰难的；顽固的；坚强的；坚韧的"},{"word":"receive","ipa":"/rɪˈsiːv/","partsOfSpeech":"v.","meaning":"收到；接收；接待"},{"word":"protect","ipa":"/prəˈtekt/","partsOfSpeech":"v.","meaning":"保护；防护；维护"},{"word":"adapt","ipa":"/əˈdæpt/","partsOfSpeech":"v.","meaning":"适应；改编；调整"},{"word":"landscape","ipa":"/ˈlændskeɪp/","partsOfSpeech":"n.","meaning":"风景；地貌"},{"word":"fill","ipa":"/fɪl/","partsOfSpeech":"v.","meaning":"装满；填满；填充"},{"word":"punish","ipa":"/ˈpʌnɪʃ/","partsOfSpeech":"v.","meaning":"惩罚；处罚；制裁"},{"word":"country","ipa":"/ˈkʌntri/","partsOfSpeech":"n.","meaning":"国家；乡下；乡村"},{"word":"much","ipa":"/mʌtʃ/","partsOfSpeech":"det./pron./adv.","meaning":"许多；大量；非常"}],"examples":[{"text":"The Romans counted it as from midnight, and most modern nations use this method.","translation":"罗马人从午夜开始计算一天，如今大多数国家都采用这种方法。","source":"（2019年真题·阅读理解·Passage Three）","speechText":"The Romans counted it as from midnight, and most modern nations use this method.","annotations":[],"targetForms":[],"audio":"audio/course-examples/84fa6acf5800e2eabc38486f.mp3"},{"text":"That rising air spreads outward and sinks between 20 and 40 degrees north and south of the equator, and stops cloud formation—which explains why there are so many deserts along the subtropical belt (亚热带), such as the Sahara Desert.","translation":"上升的空气向外扩散，并在赤道南北纬20至40度之间下沉，阻碍云的形成；这就解释了为什么撒哈拉沙漠等许多沙漠分布在亚热带地区。","source":"（2026年真题·阅读理解·Passage Three）","speechText":"That rising air spreads outward and sinks between 20 and 40 degrees north and south of the equator, and stops cloud formation—which explains why there are so many deserts along the subtropical belt , such as the Sahara Desert.","annotations":[{"text":"(亚热带)","start":198,"end":203,"anchor":"belt"}],"targetForms":[],"audio":"audio/course-examples/08d58611685aef196c2eb321.mp3"},{"text":"Her parents seem to have been rather withdrawn（withdraw的过去分词形式，此处作形容词） people, and the members of the family spent a good deal of time by themselves.","translation":"她的父母似乎都比较内向，家人也有很多时间各自独处。","source":"（2015年真题·阅读理解·Passage Three）","speechText":"Her parents seem to have been rather withdrawn people, and the members of the family spent a good deal of time by themselves.","annotations":[{"text":"（withdraw的过去分词形式，此处作形容词）","start":46,"end":70,"anchor":"withdrawn"}],"targetForms":["withdrawn"],"audio":"audio/course-examples/45ff0c1f5e619fb7f5fafbe3.mp3"},{"text":"He or she can diagnose the problem or refer you to a specialist.","translation":"他或她可以诊断问题，或将你转诊给专科医生。","source":"（2019年配套材料·选句填空·完整句选项）","speechText":"He or she can diagnose the problem or refer you to a specialist.","annotations":[],"targetForms":[],"audio":"audio/course-examples/7cb296be51725268aa3002a9.mp3"},{"text":"Marine pollution is far from new.","translation":"海洋污染早已不是新鲜事。","source":"（2015年配套材料·选词填空）","speechText":"Marine pollution is far from new.","annotations":[],"targetForms":[],"audio":"audio/course-examples/04675c75589d0e117a993cef.mp3"},{"text":"You are there to study (an active process) rather than to be taught (passive).","translation":"你来是为了学习（一个主动的过程），而不是被教导（被动）。","source":"（2017年真题·阅读理解·Passage Two）","speechText":"You are there to study (an active process) rather than to be taught (passive).","annotations":[],"targetForms":[],"audio":"audio/course-examples/3804f93a69e5980f7d09af6a.mp3"},{"text":"No matter how tough the situation is, smile!","translation":"无论处境多么艰难，都要微笑！","source":"（2021年真题·选句填空）","speechText":"No matter how tough the situation is, smile!","annotations":[],"targetForms":[],"audio":"audio/course-examples/6b3f418dcb518e19f444119d.mp3"},{"text":"Cooper received（receive的过去式） an award there for his lifetime of work.","translation":"Cooper在那里因其毕生的工作成就而获得了一个奖项。","source":"（2023年真题·阅读理解·Passage Two）","speechText":"Cooper received an award there for his lifetime of work.","annotations":[{"text":"（receive的过去式）","start":15,"end":28,"anchor":"received"}],"targetForms":["received"],"audio":"audio/course-examples/4e2c6106a3331d9181c58ba1.mp3"},{"text":"She would rather see the whole street redesigned to discourage speeding and protect walkers and bicyclists.","translation":"她更希望整条街道被重新设计，以遏制超速行为，并保护行人和骑自行车的人。","source":"（2024年真题·阅读理解·Passage Two）","speechText":"She would rather see the whole street redesigned to discourage speeding and protect walkers and bicyclists.","annotations":[],"targetForms":[],"audio":"audio/course-examples/585b48fc494ccd1e44a57ad0.mp3"},{"text":"Therefore, the structure of products should be adjusted accordingly to adapt to social development.","translation":"因此，应相应调整产品结构，以适应社会发展。","source":"（2013年配套材料·英译汉）","speechText":"Therefore, the structure of products should be adjusted accordingly to adapt to social development.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e0253ead22dbcf00fabbfa8e.mp3"},{"text":"When you picture a desert, you probably imagine a vast, empty landscape far from any water.","translation":"想到沙漠时，你可能会想象出一片辽阔、空旷、远离任何水源的地貌。","source":"（2026年真题·阅读理解·Passage Three）","speechText":"When you picture a desert, you probably imagine a vast, empty landscape far from any water.","annotations":[],"targetForms":[],"audio":"audio/course-examples/9ca7d39eff02cd318a66ed21.mp3"},{"text":"Customers' containers are weighed first, then filled（fill的过去分词形式）.","translation":"先给顾客的容器称重，然后再装入商品。","source":"（2026年真题·完形填空）","speechText":"Customers' containers are weighed first, then filled.","annotations":[{"text":"（fill的过去分词形式）","start":52,"end":65,"anchor":"filled"}],"targetForms":["filled"],"audio":"audio/course-examples/9dac400994454d068c5e7cd2.mp3"},{"text":"This plant was severely punished（punish的过去分词） by the government for releasing pollutants into water.","translation":"这家工厂因向水中排放污染物而受到政府的严厉处罚。","source":"（2018年·词汇语法）","speechText":"This plant was severely punished by the government for releasing pollutants into water.","annotations":[{"text":"（punish的过去分词）","start":32,"end":45,"anchor":"punished"}],"targetForms":["punished"],"audio":"audio/course-examples/fa446556373bff383775e53b.mp3"},{"text":"You’ll not only save money, but you’ll also see a lot more of the country.","translation":"你不仅能省钱，还能看到这个国家更多的地方。","source":"（2015年真题·阅读理解·Passage Two）","speechText":"You’ll not only save money, but you’ll also see a lot more of the country.","annotations":[],"targetForms":[],"audio":"audio/course-examples/7f8c6c949021f82db86192eb.mp3"},{"text":"In reality, most people expect much less.","translation":"实际上，大多数人预期的远少于这个。","source":"（2026年真题·阅读理解·Passage One）","speechText":"In reality, most people expect much less.","annotations":[],"targetForms":[],"audio":"audio/course-examples/6a2a4c64de5cafdb58550a76.mp3"}]},"29":{"vocabulary":[{"word":"play","ipa":"/pleɪ/","partsOfSpeech":"v./n.","meaning":"玩；扮演；比赛；戏剧；假装"},{"word":"pupil","ipa":"/ˈpjuːp(ə)l/","partsOfSpeech":"n.","meaning":"学生；小学生"},{"word":"baby","ipa":"/ˈbeɪbi/","partsOfSpeech":"n.","meaning":"婴儿；幼崽"},{"word":"festival","ipa":"/ˈfestɪvl; ˈfestəvəl/","partsOfSpeech":"n./adj.","meaning":"节日；喜庆的"},{"word":"holiday","ipa":"/ˈhɒlədeɪ/","partsOfSpeech":"n.","meaning":"假期；假日；节日"},{"word":"target","ipa":"/ˈtɑːɡɪt/","partsOfSpeech":"n./v.","meaning":"目标；靶子；把…作为目标"},{"word":"rat","ipa":"/ræt/","partsOfSpeech":"n.","meaning":"老鼠；耗子；叛徒"},{"word":"manage","ipa":"/ˈmænɪdʒ/","partsOfSpeech":"v.","meaning":"管理；经营；设法做到…"},{"word":"smart","ipa":"/smɑːt/","partsOfSpeech":"adj.","meaning":"聪明的；智能的"},{"word":"device","ipa":"/dɪˈvaɪs/","partsOfSpeech":"n.","meaning":"装置；设备；手段；设计"},{"word":"poet","ipa":"/ˈpəʊɪt/","partsOfSpeech":"n.","meaning":"诗人"},{"word":"life","ipa":"/laɪf/","partsOfSpeech":"n.","meaning":"生活；生命；人生"},{"word":"capital","ipa":"/ˈkæpɪt(ə)l/","partsOfSpeech":"n./adj.","meaning":"首都；资本；大写字母；主要的"},{"word":"accent","ipa":"/ˈæksent/","partsOfSpeech":"n./v.","meaning":"口音；重音；强调；重读"},{"word":"department","ipa":"/dɪˈpɑːtmənt/","partsOfSpeech":"n.","meaning":"部门；系；科"}],"examples":[{"text":"Now, 78 years later, he is still playing（play的-ing形式）.","translation":"如今，七十八年过去了，他仍在玩。","source":"（2025年真题·完形填空）","speechText":"Now, 78 years later, he is still playing.","annotations":[{"text":"（play的-ing形式）","start":40,"end":53,"anchor":"playing"}],"targetForms":["playing"],"audio":"audio/course-examples/3633cc1d809ad6a081fee6a9.mp3"},{"text":"Of the thirty pupils（pupil的复数形式） to begin ballet each year, fewer than twenty-five usually graduate; the others drop out because of poor health or lack of ability.","translation":"每年开始学习芭蕾的三十名学生中，通常不到二十五人能毕业；其他人因健康状况不佳或能力不足而退学。","source":"（2013年真题·阅读理解·Passage One）","speechText":"Of the thirty pupils to begin ballet each year, fewer than twenty-five usually graduate; the others drop out because of poor health or lack of ability.","annotations":[{"text":"（pupil的复数形式）","start":20,"end":32,"anchor":"pupils"}],"targetForms":["pupils"],"audio":"audio/course-examples/522b3178c9dd3d73179a03d9.mp3"},{"text":"Should we use genetic forecasting to pre-eliminate “unfit” babies（baby的复数形式）?","translation":"我们应该利用基因预测，提前排除那些“不合适”的婴儿吗？","source":"（2019年真题·阅读理解·Passage Two）","speechText":"Should we use genetic forecasting to pre-eliminate “unfit” babies?","annotations":[{"text":"（baby的复数形式）","start":65,"end":76,"anchor":"babies"}],"targetForms":["babies"],"audio":"audio/course-examples/67afc7b5dd9d6ab984a0ced6.mp3"},{"text":"On this day they didn't work, but met for trade and religious festivals（festival的复数形式）.","translation":"这一天，他们不工作，而是聚在一起交易、庆祝宗教节日。","source":"（2019年真题·阅读理解·Passage Three）","speechText":"On this day they didn't work, but met for trade and religious festivals.","annotations":[{"text":"（festival的复数形式）","start":71,"end":86,"anchor":"festivals"}],"targetForms":["festivals"],"audio":"audio/course-examples/446c8a23dd41a09187cf2d56.mp3"},{"text":"The phenomenon of the holiday economy shows that Chinese people’s consumption concept is undergoing great changes.","translation":"假日经济现象表明，中国人的消费观念正在发生巨大变化。","source":"（2013年配套材料·英译汉）","speechText":"The phenomenon of the holiday economy shows that Chinese people’s consumption concept is undergoing great changes.","annotations":[],"targetForms":[],"audio":"audio/course-examples/322e64fc76d65d846b5d71d0.mp3"},{"text":"According to report from China Daily, in an event targeted（target的过去分词） at helping poverty reduction, influencers attracted more than 930,000 viewers.","translation":"据《中国日报》报道，在一场旨在帮助减贫的活动中，网红吸引了超过93万名观众。","source":"（2020年·阅读理解·Passage Two）","speechText":"According to report from China Daily, in an event targeted at helping poverty reduction, influencers attracted more than 930,000 viewers.","annotations":[{"text":"（target的过去分词）","start":58,"end":71,"anchor":"targeted"}],"targetForms":["targeted"],"audio":"audio/course-examples/09b684928607748a44258989.mp3"},{"text":"Thus for rats（rat的复数形式）, population and violence are directly related.","translation":"因此，对老鼠来说，种群数量与暴力行为有直接关系。","source":"（2014年真题·阅读理解·Passage One）","speechText":"Thus for rats, population and violence are directly related.","annotations":[{"text":"（rat的复数形式）","start":13,"end":23,"anchor":"rats"}],"targetForms":["rats"],"audio":"audio/20261016-list1/examples/02.mp3"},{"text":"But unlike cars, ants somehow manage to avoid the problem of stop-and-go traffic.","translation":"但与汽车不同，蚂蚁似乎总能设法避免走走停停的交通问题。","source":"（2025年真题·阅读理解·Passage Three）","speechText":"But unlike cars, ants somehow manage to avoid the problem of stop-and-go traffic.","annotations":[],"targetForms":[],"audio":"audio/course-examples/4ddfa6becb113bdeb0050a15.mp3"},{"text":"Many of them have difficulties in using smart devices.","translation":"他们当中许多人在使用智能设备时遇到困难。","source":"（2021年真题·写作）","speechText":"Many of them have difficulties in using smart devices.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e2b3f9c426809f9ceb1220ff.mp3"},{"text":"The device was not physically connected to phone lines.","translation":"这台设备并没有通过实体线路连接到电话线上。","source":"（2023年真题·阅读理解·Passage Two）","speechText":"The device was not physically connected to phone lines.","annotations":[],"targetForms":[],"audio":"audio/course-examples/516804bec61da89727cdc115.mp3"},{"text":"Along with the Greek poet Sappho, she may be one of the two greatest women poets（poet的复数形式） who have ever lived.","translation":"她与希腊诗人萨福，可能是有史以来最伟大的两位女诗人。","source":"（2015年真题·阅读理解·Passage Three）","speechText":"Along with the Greek poet Sappho, she may be one of the two greatest women poets who have ever lived.","annotations":[{"text":"（poet的复数形式）","start":80,"end":91,"anchor":"poets"}],"targetForms":["poets"],"audio":"audio/course-examples/219702101060ecd6430ae36a.mp3"},{"text":"Most people understand that life gets unpredictable.","translation":"大多数人都明白，生活有时会变得难以预料。","source":"（2026年真题·阅读理解·Passage One）","speechText":"Most people understand that life gets unpredictable.","annotations":[],"targetForms":[],"audio":"audio/course-examples/9c4c2601c575a137118bd154.mp3"},{"text":"the increasing use of rubber and steel in capital construction","translation":"在资本建设中橡胶和钢材的使用日益增多","source":"（2014年真题·阅读理解·Passage Three）","speechText":"the increasing use of rubber and steel in capital construction","annotations":[],"targetForms":[],"audio":"audio/course-examples/a72d93a52cb7f32f21e88b50.mp3"},{"text":"A French friend of mine once said to me, “Your accent in French is excellent but you will never sound like a Frenchman until you put all your heart into your voice.”","translation":"我的一位法国朋友曾对我说：“你的法语口音很好，但只有把全部感情融入声音中，听起来才会像一个法国人。”","source":"（2018年真题·阅读理解·Passage Three）","speechText":"A French friend of mine once said to me, “Your accent in French is excellent but you will never sound like a Frenchman until you put all your heart into your voice.”","annotations":[],"targetForms":[],"audio":"audio/course-examples/56006ae3d1e058fc3bbe5243.mp3"},{"text":"If a great job is the destination, HR departments（department的复数形式） play the gatekeeper.","translation":"如果一份好工作是目的地，人力资源部门就充当着守门人的角色。","source":"（2016年配套材料·选词填空）","speechText":"If a great job is the destination, HR departments play the gatekeeper.","annotations":[{"text":"（department的复数形式）","start":49,"end":66,"anchor":"departments"}],"targetForms":["departments"],"audio":"audio/course-examples/5619d1376d114fcc346808d2.mp3"}]},"30":{"vocabulary":[{"word":"status","ipa":"/ˈsteɪtəs/","partsOfSpeech":"n.","meaning":"地位；身份；状态；状况"},{"word":"fetch","ipa":"/fetʃ/","partsOfSpeech":"v.","meaning":"取来；接来；售得"},{"word":"gate","ipa":"/ɡeɪt/","partsOfSpeech":"n.","meaning":"大门；入口"},{"word":"credit","ipa":"/ˈkredɪt/","partsOfSpeech":"n./v.","meaning":"信用；学分；赞扬；相信；把钱存入（账户）"},{"word":"on","ipa":"/ɒn/","partsOfSpeech":"prep./adv./adj.","meaning":"在…上；穿着；开着"},{"word":"universe","ipa":"/ˈjuːnɪvɜːs/","partsOfSpeech":"n.","meaning":"宇宙；世界"},{"word":"point","ipa":"/pɔɪnt/","partsOfSpeech":"n./v.","meaning":"要点；得分；指向"},{"word":"where","ipa":"/weə(r)/","partsOfSpeech":"adv./conj.","meaning":"在哪里；在…的地方"},{"word":"train","ipa":"/treɪn/","partsOfSpeech":"n./v.","meaning":"火车；训练"},{"word":"always","ipa":"/ˈɔːlweɪz/","partsOfSpeech":"adv.","meaning":"总是；一直；永远"},{"word":"buy","ipa":"/baɪ/","partsOfSpeech":"v./n.","meaning":"买；购买"},{"word":"please","ipa":"/pliːz/","partsOfSpeech":"int./v.","meaning":"请；使高兴"},{"word":"recent","ipa":"/ˈriːs(ə)nt/","partsOfSpeech":"adj.","meaning":"最近的；近来的"},{"word":"tired","ipa":"/ˈtaɪəd/","partsOfSpeech":"adj.","meaning":"疲倦的；厌倦的"},{"word":"office","ipa":"/ˈɒfɪs/","partsOfSpeech":"n.","meaning":"办公室；官职"}],"examples":[{"text":"In spite of fortune and social status, she was actually an ordinary-looking woman.","translation":"尽管拥有财富和社会地位，她实际上相貌平平。","source":"（2018年真题·词汇语法·第24题）","speechText":"In spite of fortune and social status, she was actually an ordinary-looking woman.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e49a2418decdc6c7bebe2c64.mp3"},{"text":"Despite his age, every evening includes playtime with Ben's collection of toys, and then an exciting game of fetch around the apartment.","translation":"尽管年纪不小，他每天晚上都会和本的玩具一起玩耍，然后在公寓里玩一场激动人心的接球游戏。","source":"（2025年真题·阅读理解·Passage One）","speechText":"Despite his age, every evening includes playtime with Ben's collection of toys, and then an exciting game of fetch around the apartment.","annotations":[],"targetForms":[],"audio":"audio/course-examples/f12b1814bed37db74b8d1020.mp3"},{"text":"A good performance at a job interview can get you through the gate and pass the gatekeeper.","translation":"在求职面试中表现出色，能帮助你跨过大门、通过把关人的审核","source":"（2016年配套材料·选词填空）","speechText":"A good performance at a job interview can get you through the gate and pass the gatekeeper.","annotations":[],"targetForms":[],"audio":"audio/course-examples/3d186ed39063025148218ab4.mp3"},{"text":"It feels good to take credit for things, especially when you work hard for them.","translation":"得到认可感觉很好，尤其是当你为它付出了努力时。","source":"（2013年配套材料·选句填空）","speechText":"It feels good to take credit for things, especially when you work hard for them.","annotations":[],"targetForms":[],"audio":"audio/course-examples/8cefb293c9ed059d57c118d1.mp3"},{"text":"I don't just watch them on television.","translation":"我不只是在电视上看他们。","source":"（2022年真题·阅读理解·Passage One）","speechText":"I don't just watch them on television.","annotations":[],"targetForms":[],"audio":"audio/course-examples/6411912219feb1b72ea3a593.mp3"},{"text":"I felt very small when I realized the hugeness of the universe.","translation":"当我意识到宇宙如此浩瀚时，便感到自己十分渺小。","source":"（2025年真题·翻译）","speechText":"I felt very small when I realized the hugeness of the universe.","annotations":[],"targetForms":[],"audio":"audio/course-examples/a94606850598cfcac213721a.mp3"},{"text":"Just jumping to the landline is missing the whole point, Griffith said.","translation":"Griffith说，一上来就改用固定电话，会错过问题的关键。","source":"（2026年真题·阅读理解·Passage Two）","speechText":"Just jumping to the landline is missing the whole point, Griffith said.","annotations":[],"targetForms":[],"audio":"audio/course-examples/5a6ef4b295e1a8757cfbef14.mp3"},{"text":"Look at the website where the story comes from.","translation":"查看故事来源的网站。","source":"（2020年真题·选句填空）","speechText":"Look at the website where the story comes from.","annotations":[],"targetForms":[],"audio":"audio/course-examples/7c8d2de74e6f9421e71b2854.mp3"},{"text":"There are many inexpensive, older hotels near bus or train stations.","translation":"汽车站或火车站附近有许多价格低廉的老旅馆。","source":"（2015年真题·阅读理解·Passage Two）","speechText":"There are many inexpensive, older hotels near bus or train stations.","annotations":[],"targetForms":[],"audio":"audio/course-examples/729e5165204251d5563667be.mp3"},{"text":"But it was not always that way.","translation":"但情况并非一直如此。","source":"（2024年真题·阅读理解·Passage One）","speechText":"But it was not always that way.","annotations":[],"targetForms":[],"audio":"audio/course-examples/f7793030f40b066140bae69b.mp3"},{"text":"We've all heard that money doesn't buy happiness, and that's certainly true.","translation":"我们都听说过金钱买不到幸福，这话确实没错。","source":"（2016年真题·阅读理解·Passage One）","speechText":"We've all heard that money doesn't buy happiness, and that's certainly true.","annotations":[],"targetForms":[],"audio":"audio/course-examples/d4cecb0ed19f412c96b9f946.mp3"},{"text":"PTO stands for “Please turn over the page”, of course.","translation":"当然，PTO是“请翻到下一页”的缩写。","source":"（2013年真题·词汇语法·第32题）","speechText":"PTO stands for “Please turn over the page”, of course.","annotations":[],"targetForms":[],"audio":"audio/course-examples/6793953a35e77d8517f9ce33.mp3"},{"text":"The team's study appeared in a recent issue of Nature Communications Biology.","translation":"该团队的研究发表在近期一期《Nature Communications Biology》上。","source":"（2023年真题·阅读理解·Passage Three）","speechText":"The team's study appeared in a recent issue of Nature Communications Biology.","annotations":[],"targetForms":[],"audio":"audio/course-examples/385cb6212e0811439170b44a.mp3"},{"text":"If you’re feeling tired, upset or lonely, getting lost in a story can give you comfort and help you to relax.","translation":"如果你感到疲惫、烦躁或孤独，沉浸在一个故事中能给你安慰，也有助于放松身心。","source":"（2016年配套材料·选句填空）","speechText":"If you’re feeling tired, upset or lonely, getting lost in a story can give you comfort and help you to relax.","annotations":[],"targetForms":[],"audio":"audio/course-examples/80dd30192ac29b5a76aef3fe.mp3"},{"text":"Typically, an interview is held in a conference room or office.","translation":"面试通常在会议室或办公室举行。","source":"（2020年真题·阅读理解·Passage One）","speechText":"Typically, an interview is held in a conference room or office.","annotations":[],"targetForms":[],"audio":"audio/course-examples/25177f876cd877134226c265.mp3"}]},"31":{"vocabulary":[{"word":"wire","ipa":"/ˈwaɪə(r)/","partsOfSpeech":"n.","meaning":"电线；金属丝"},{"word":"rise","ipa":"/raɪz/","partsOfSpeech":"v./n.","meaning":"上升；升起；增长"},{"word":"dance","ipa":"/dɑːns/","partsOfSpeech":"n./v.","meaning":"舞蹈；跳舞"},{"word":"everything","ipa":"/ˈevriθɪŋ/","partsOfSpeech":"pron.","meaning":"一切；所有事物"},{"word":"peak","ipa":"/piːk/","partsOfSpeech":"n./adj./v.","meaning":"山峰；巅峰；高峰的；达到顶峰"},{"word":"reflect","ipa":"/rɪˈflekt/","partsOfSpeech":"v.","meaning":"反映；反射"},{"word":"ocean","ipa":"/ˈəʊʃ(ə)n/","partsOfSpeech":"n.","meaning":"海洋；大海"},{"word":"sit","ipa":"/sɪt/","partsOfSpeech":"v.","meaning":"坐；使就座"},{"word":"fit","ipa":"/fɪt/","partsOfSpeech":"adj./v./n.","meaning":"健康的；合适的；适合；安装"},{"word":"manner","ipa":"/ˈmænə(r)/","partsOfSpeech":"n.","meaning":"方式；态度；举止；礼貌"},{"word":"tool","ipa":"/tuːl/","partsOfSpeech":"n.","meaning":"工具；手段"},{"word":"resident","ipa":"/ˈrezɪdənt/","partsOfSpeech":"n./adj.","meaning":"居民；住院医师；居住的"},{"word":"luck","ipa":"/lʌk/","partsOfSpeech":"n.","meaning":"运气；好运；机遇"},{"word":"rainbow","ipa":"/ˈreɪnbəʊ/","partsOfSpeech":"n.","meaning":"彩虹；五彩缤纷的事物"},{"word":"further","ipa":"/ˈfɜːðə(r)/","partsOfSpeech":"adv./adj./v.","meaning":"进一步；此外；而且；更远的；促进"}],"examples":[{"text":"Don't touch that wire, it's live.","translation":"别碰那根电线，它带电。","source":"（2016年真题·词汇语法·第35题）","speechText":"Don't touch that wire, it's live.","annotations":[],"targetForms":[],"audio":"audio/course-examples/dddddf294d41da57d86b493e.mp3"},{"text":"However, the cost of studying is on the rise.","translation":"然而，学习费用正在不断上涨。","source":"（2021年真题·完形填空）","speechText":"However, the cost of studying is on the rise.","annotations":[],"targetForms":[],"audio":"audio/course-examples/18649039aceebe8d8f4af230.mp3"},{"text":"The period devoted to dance class increases gradually from two or three hours a day to five or six.","translation":"用于舞蹈课的时间，逐渐从每天两三个小时增加到五六个小时。","source":"（2013年真题·阅读理解·Passage One）","speechText":"The period devoted to dance class increases gradually from two or three hours a day to five or six.","annotations":[],"targetForms":[],"audio":"audio/course-examples/69c15104275d02b7a7019eaf.mp3"},{"text":"There seems to be everything on the network.","translation":"网络上似乎什么都有。","source":"（2017年真题·阅读理解·Passage One）","speechText":"There seems to be everything on the network.","annotations":[],"targetForms":[],"audio":"audio/course-examples/eff2c92ce48038385f67495c.mp3"},{"text":"The possible explanation to the trouble is that Tom is at his temperature and energy peak in the evening.","translation":"这个问题的一种可能解释是，Tom的体温和精力会在晚上达到高峰。","source":"（2018年真题·阅读理解·Passage Two）","speechText":"The possible explanation to the trouble is that Tom is at his temperature and energy peak in the evening.","annotations":[],"targetForms":[],"audio":"audio/course-examples/203b0d0383b66f345478ff61.mp3"},{"text":"Each person’s style of play reflects（reflect的第三人称单数形式） his or her personality and can serve as a medium for self-reflection.","translation":"每个人的棋风都反映出其个性，也可以成为自我反思的媒介。","source":"（2023年真题·完形填空）","speechText":"Each person’s style of play reflects his or her personality and can serve as a medium for self-reflection.","annotations":[{"text":"（reflect的第三人称单数形式）","start":36,"end":54,"anchor":"reflects"}],"targetForms":["reflects"],"audio":"audio/course-examples/ec7f43c8333b3941a24e9e50.mp3"},{"text":"Boris Worm is an ocean biologist at Canada's Dalhousie University.","translation":"Boris Worm是加拿大达尔豪斯大学的一位海洋生物学家。","source":"（2023年真题·阅读理解·Passage Three）","speechText":"Boris Worm is an ocean biologist at Canada's Dalhousie University.","annotations":[],"targetForms":[],"audio":"audio/course-examples/3efaea85b1e13da5a1a59cc9.mp3"},{"text":"Sit on the edge of the bed a minute before putting your feet on the floor.","translation":"先在床边坐一分钟，再把双脚放到地上。","source":"（2018年真题·阅读理解·Passage Two）","speechText":"Sit on the edge of the bed a minute before putting your feet on the floor.","annotations":[],"targetForms":[],"audio":"audio/course-examples/d7d4de1157f3477bf4ebb8c1.mp3"},{"text":"Nevertheless, the goal is the same--get the candidate who is the best fit for the position.","translation":"不过，目标是相同的：找到最适合这个职位的求职者。","source":"（2020年真题·阅读理解·Passage One）","speechText":"Nevertheless, the goal is the same--get the candidate who is the best fit for the position.","annotations":[],"targetForms":[],"audio":"audio/course-examples/40f06a40dd2263a214fe8e5f.mp3"},{"text":"By doing all these things, they are learning manners（manner的复数形式） and how to speak formally, she said.","translation":"她说，通过做这些事情，孩子们正在学习礼貌，以及如何正式地交谈。","source":"（2026年真题·阅读理解·Passage Two）","speechText":"By doing all these things, they are learning manners and how to speak formally, she said.","annotations":[{"text":"（manner的复数形式）","start":52,"end":65,"anchor":"manners"}],"targetForms":["manners"],"audio":"audio/course-examples/cee11de74d20d6553dc6857d.mp3"},{"text":"Or use a search tool to see if the same image has been used in other contexts.","translation":"或者使用搜索工具，看看同一张图片是否曾用于其他语境。","source":"（2020年真题·选句填空）","speechText":"Or use a search tool to see if the same image has been used in other contexts.","annotations":[],"targetForms":[],"audio":"audio/course-examples/5862866dbf232f878fb75705.mp3"},{"text":"The space seems more like a prison cell than a home and you may think the resident cannot afford to buy more things to fill the apartment with.","translation":"这个空间看起来更像牢房，而不像家；你可能会以为住户没有能力购买更多东西来填满公寓。","source":"（2021年真题·阅读理解·Passage Two）","speechText":"The space seems more like a prison cell than a home and you may think the resident cannot afford to buy more things to fill the apartment with.","annotations":[],"targetForms":[],"audio":"audio/course-examples/9362e76cdeb29a18ed2ff1b9.mp3"},{"text":"Many people think the game is all luck.","translation":"许多人认为，这个游戏全靠运气。","source":"（2021年真题·阅读理解·Passage One）","speechText":"Many people think the game is all luck.","annotations":[],"targetForms":[],"audio":"audio/course-examples/3c1cf495f61ecec5e89776cd.mp3"},{"text":"A rainbow will appear.","translation":"一道彩虹将会出现。","source":"（2026年·阅读理解·Passage Three）","speechText":"A rainbow will appear.","annotations":[],"targetForms":[],"audio":"audio/course-examples/64a8030ba661fe0fed75baed.mp3"},{"text":"In the light of these he puts further questions, and so on.","translation":"根据这些回答，他会提出进一步的问题，以此类推。","source":"（2016年真题·阅读理解·Passage Two）","speechText":"In the light of these he puts further questions, and so on.","annotations":[],"targetForms":[],"audio":"audio/course-examples/338215f587639cbed37045fe.mp3"}]},"32":{"vocabulary":[{"word":"rubber","ipa":"/ˈrʌbə(r)/","partsOfSpeech":"n.","meaning":"橡胶；橡皮"},{"word":"wonder","ipa":"/ˈwʌndə(r)/","partsOfSpeech":"v./n.","meaning":"想知道；不知是否；奇迹；惊讶"},{"word":"access","ipa":"/ˈækses/","partsOfSpeech":"n./v.","meaning":"通道；使用权；进入；访问"},{"word":"ordinary","ipa":"/ˈɔːd(ə)n(ə)ri/","partsOfSpeech":"adj.","meaning":"普通的；平常的"},{"word":"prospect","ipa":"/ˈprɒspekt/","partsOfSpeech":"n./v.","meaning":"前景；展望；勘探"},{"word":"lie","ipa":"/laɪ/","partsOfSpeech":"v./n.","meaning":"躺；位于；说谎；谎言；方向位置"},{"word":"dull","ipa":"/dʌl/","partsOfSpeech":"adj./v.","meaning":"迟钝的；无聊的；暗淡的；减轻；缓解；使迟钝"},{"word":"talent","ipa":"/ˈtælənt/","partsOfSpeech":"n.","meaning":"天赋；人才"},{"word":"oxygen","ipa":"/ˈɒksɪdʒən/","partsOfSpeech":"n.","meaning":"氧气"},{"word":"steal","ipa":"/stiːl/","partsOfSpeech":"v.","meaning":"偷；窃取；偷偷移动"},{"word":"cancer","ipa":"/ˈkænsə(r)/","partsOfSpeech":"n.","meaning":"癌症；恶性肿瘤"},{"word":"address","ipa":"/əˈdres/","partsOfSpeech":"n./v.","meaning":"地址；演讲；称呼；解决"},{"word":"awkward","ipa":"/ˈɔːkwəd/","partsOfSpeech":"adj.","meaning":"尴尬的；笨拙的；棘手的"},{"word":"function","ipa":"/ˈfʌŋkʃ(ə)n/","partsOfSpeech":"n./v.","meaning":"功能；作用；运行"},{"word":"confirm","ipa":"/kənˈfɜːm/","partsOfSpeech":"v.","meaning":"确认；证实；确定"}],"examples":[{"text":"Later, people tried to lift a building off its foundation, and insert rubber and steel between the building and its foundation to reduce the impact of ground vibrations.","translation":"后来，人们尝试把建筑抬离地基，在建筑与地基之间放入橡胶和钢材，以减小地面震动的影响。","source":"（2014年真题·阅读理解·Passage Three）","speechText":"Later, people tried to lift a building off its foundation, and insert rubber and steel between the building and its foundation to reduce the impact of ground vibrations.","annotations":[],"targetForms":[],"audio":"audio/20261016-list1/examples/09.mp3"},{"text":"I wasn’t going to be one of those people who died wondering（wonder的-ing形式）.","translation":"我不愿到临终时还在想：如果当初尝试了，结果会怎样？","source":"（2015年真题·阅读理解·Passage One）","speechText":"I wasn’t going to be one of those people who died wondering.","annotations":[{"text":"（wonder的-ing形式）","start":59,"end":74,"anchor":"wondering"}],"targetForms":["wondering"],"audio":"audio/course-examples/00306fa942769cc9987b6d93.mp3"},{"text":"As the manager’s private secretary, Helen has easy access to all his correspondence.","translation":"作为经理的私人秘书，Helen很容易接触到他所有的往来信件。","source":"（2014年真题·词汇语法·第22题）","speechText":"As the manager’s private secretary, Helen has easy access to all his correspondence.","annotations":[],"targetForms":[],"audio":"audio/course-examples/3835db9c43b8c73d094c3678.mp3"},{"text":"In spite of fortune and social status, she was actually an ordinary-looking woman.","translation":"尽管拥有财富和社会地位，她实际上却是一位相貌普通的女性。","source":"（2018年·词汇语法 第24题）","speechText":"In spite of fortune and social status, she was actually an ordinary-looking woman.","annotations":[],"targetForms":[],"audio":"audio/course-examples/e49a2418decdc6c7bebe2c64.mp3"},{"text":"When I left a 20-year career in the U.S. Coast Guard to become a freelance writer, I had no prospects（prospect的复数形式） at all.","translation":"当我结束在美国海岸警卫队长达二十年的职业生涯、转而成为自由撰稿人时，前途一片渺茫。","source":"（2015年真题·阅读理解·Passage One）","speechText":"When I left a 20-year career in the U.S. Coast Guard to become a freelance writer, I had no prospects at all.","annotations":[{"text":"（prospect的复数形式）","start":101,"end":116,"anchor":"prospects"}],"targetForms":["prospects"],"audio":"audio/course-examples/040947555fc00b4c53d7ae3d.mp3"},{"text":"There are no decorative objects lying（lie的现在分词形式） around－just the essentials.","translation":"周围没有摆放任何装饰品，只有必需品。","source":"（2021年真题·阅读理解·Passage Two）","speechText":"There are no decorative objects lying around－just the essentials.","annotations":[{"text":"（lie的现在分词形式）","start":37,"end":49,"anchor":"lying"}],"targetForms":["lying"],"audio":"audio/course-examples/4185c981ebf2e3b35ac54fc0.mp3"},{"text":"A person with a flat, dull voice which neither rises nor falls sounds like a flat and dull person!","translation":"一个人如果说话声音平淡、沉闷，没有高低起伏，听起来就像是一个平淡无趣的人！","source":"（2018年真题·阅读理解·Passage Three）","speechText":"A person with a flat, dull voice which neither rises nor falls sounds like a flat and dull person!","annotations":[],"targetForms":[],"audio":"audio/course-examples/ca75529d7421b53d50c9061c.mp3"},{"text":"Here are some best practices used by industry leaders to attract the best talent for the job.","translation":"以下是业内领先者为岗位吸引最优秀人才的一些成功做法。","source":"（2020年真题·阅读理解·Passage One）","speechText":"Here are some best practices used by industry leaders to attract the best talent for the job.","annotations":[],"targetForms":[],"audio":"audio/course-examples/8a438c9566497760a302aedb.mp3"},{"text":"The oxygen in the air we breathe mixes with our blood and gives us life.","translation":"我们呼吸的空气中的氧气进入血液，维持着我们的生命。","source":"（2013年真题·词汇语法·第37题）","speechText":"The oxygen in the air we breathe mixes with our blood and gives us life.","annotations":[],"targetForms":[],"audio":"audio/course-examples/6e7620b14e1e8dbfb86e9668.mp3"},{"text":"The police were given an order that the stolen（steal的过去分词形式） documents must be recovered at all costs.","translation":"警方接到命令，必须不惜一切代价追回被盗文件。","source":"（2013年真题·词汇语法·第46题）","speechText":"The police were given an order that the stolen documents must be recovered at all costs.","annotations":[{"text":"（steal的过去分词形式）","start":46,"end":60,"anchor":"stolen"}],"targetForms":["stolen"],"audio":"audio/course-examples/7e8ff9d8ccfd9c6ca87769b3.mp3"},{"text":"All the while he was terrified by the fear that he had cancer of the stomach.","translation":"他始终因担心自己得了胃癌而感到恐惧。","source":"（2014年真题·词汇语法·第36题）","speechText":"All the while he was terrified by the fear that he had cancer of the stomach.","annotations":[],"targetForms":[],"audio":"audio/course-examples/70ded3267b9c87451e3d4ddd.mp3"},{"text":"A fake news website may use an address that sounds like a real newspaper, but does not have many real stories about her topics.","translation":"一个假新闻网站可能会使用看起来像真实报纸的网址，但其内容中关于相关主题的真实新闻并不多。","source":"（2020年·选句填空）","speechText":"A fake news website may use an address that sounds like a real newspaper, but does not have many real stories about her topics.","annotations":[],"targetForms":[],"audio":"audio/course-examples/bdcc52949223352506336897.mp3"},{"text":"Everyone will be thankful not to face awkward silence.","translation":"能避免尴尬的沉默，每个人都会心存感激。","source":"（2017年真题·阅读理解·Passage Two）","speechText":"Everyone will be thankful not to face awkward silence.","annotations":[],"targetForms":[],"audio":"audio/course-examples/19678e6e8d5d67e5c078b025.mp3"},{"text":"Recent research suggests that backward walking does more than strengthen muscles—it also sharpens cognitive（认知的）function.","translation":"近期研究表明，倒着走不仅能增强肌肉，还能提升认知功能。","source":"（2025年真题·阅读理解·Passage Two）","speechText":"Recent research suggests that backward walking does more than strengthen muscles—it also sharpens cognitive function.","annotations":[{"text":"（认知的）","start":107,"end":112,"anchor":"cognitive"}],"targetForms":[],"audio":"audio/course-examples/0567b4369fe0417812d74fbb.mp3"},{"text":"When asked by news reporters, the Prime Minister confirmed（confirm的过去式） that he would visit France next month.","translation":"面对新闻记者的提问，首相确认他将于下个月访问法国。","source":"（2017年真题·词汇语法·第45题）","speechText":"When asked by news reporters, the Prime Minister confirmed that he would visit France next month.","annotations":[{"text":"（confirm的过去式）","start":58,"end":71,"anchor":"confirmed"}],"targetForms":["confirmed"],"audio":"audio/course-examples/270fea74375ae4482bc825ed.mp3"}]}}};
